Table_Dialog_Left_13 = {
  [89834] = "{id=89834,Text='处理这样的食材，我们可以用辅佐的香料衬托。',Speaker=6730,}",
  [89835] = "{id=89835,Text='有些食材的味道不好闻，我们就需要用香料掩盖食物原味。',Speaker=6730,}",
  [89836] = "{id=89836,Text='一道完美的料理离不开顶级的香料。',Speaker=6730,}",
  [89837] = "{id=89837,Text='我听说碧莎最近获得了一批顶级的香料，去找她拿一点。',Speaker=6730,}",
  [89838] = "{id=89838,Text='你好，冒险者，我听说了你们最近在找会长学习制作精致料理呢。',Speaker=6446,}",
  [89839] = "{id=89839,Text='会长的要求很严格呢，还能跟的上吗？',Speaker=6446,}",
  [89840] = "{id=89840,Text='那就好，如果有不懂的要问我哦！',Speaker=6446,}",
  [89841] = "{id=89841,Text='顶级香料？确实我最近买了一批顶级香料，但是运送香料的马车在普隆德拉南门被一些波利抢劫了。',Speaker=6446,}",
  [89842] = "{id=89842,Text='如果你能帮我找回香料，我可以送给你一点！',Speaker=6446,}",
  [89843] = "{id=89843,Text='冒险者，请帮助他们从痛苦中获得解脱吧。',Speaker=6625,}",
  [89844] = "{id=89844,Text='我的香料！太棒了，冒险者，你帮我狠狠教训了那群波利吗？',Speaker=6446,Option='当然',}",
  [89845] = "{id=89845,Text='我就知道！',Speaker=6446,Emoji=2,}",
  [89846] = "{id=89846,Text='好了，这是会长想要的香料，你快拿去给他吧！',Speaker=6446,}",
  [89847] = "{id=89847,Text='速度真慢，冒险者，想要做精致料理，手脚一定要熟练。',Speaker=6730,}",
  [89848] = "{id=89848,Text='这股香味，这是碧莎的香料吧，真是美妙……',Speaker=6730,}",
  [89849] = "{id=89849,Text='这是你的奖励，好好保留。',Speaker=6730,}",
  [89850] = "{id=89850,Text='明天是[c][ffff00]第三节课[-][/c]，不要迟到了！',Speaker=6730,}",
  [89851] = "{id=89851,Text='呼，这几天整天面对一群对料理一无所知的人，真是让人伤透了脑筋。',Speaker=6730,}",
  [89852] = "{id=89852,Text='冒险者，好好表现吧，如果你不合格，我是不会教你做料理的。',Speaker=6730,}",
  [89853] = "{id=89853,Text='第三节课，也是最重要的一节课。',Speaker=6730,}",
  [89854] = "{id=89854,Text='纵然食物的颜色和香味都非常重要，但是判断一道料理是否合格的本质，还是料理的味道。',Speaker=6730,}",
  [89855] = "{id=89855,Text='如果希望做出美味的料理，第一步是什么你知道吗？',Speaker=6730,Option='{我不知道,2},{我不关心,2},{优秀的食材,3}',}",
  [89856] = "{id=89856,Text='你太令人失望了，冒险者，多学习一下料理的知识吧。',Speaker=6730,}",
  [89857] = "{id=89857,Text='不错，优秀的食材是成功制作料理的第一步。',Speaker=6730,}",
  [89858] = "{id=89858,Text='我听说胡雷特最近获得了一批鲜美的蘑菇，你去找他拿一点。',Speaker=6730,}",
  [89859] = "{id=89859,Text='啊，是奥尔里昂大人让你来的吧。',Speaker=6444,}",
  [89860] = "{id=89860,Text='确实，最近我获得了一批蘑菇，这几天我一直在风干这批蘑菇。',Speaker=6444,}",
  [89861] = "{id=89861,Text='但是这批蘑菇需要人看守，避免被盗虫偷吃。',Speaker=6444,}",
  [89862] = "{id=89862,Text='冒险者，如果你帮我看管蘑菇，我就可以把蘑菇给你。',Speaker=6444,Option='{没问题,6},{没兴趣,5}',}",
  [89863] = "{id=89863,Text='真是没礼貌！我不会给你蘑菇的！',Speaker=6444,}",
  [89864] = "{id=89864,Text='那么太感谢了，蘑菇就放在桌子旁边的箱子里，请好好看守，务必小心那群偷吃的盗虫。',Speaker=6444,}",
  [89865] = "{id=89865,Text='美味的蘑菇！是否开始保护蘑菇？',Speaker=6741,Option='{是的,8},{等等,7}',}",
  [89866] = "{id=89866,Text='太棒了！看样子你已经顺利赶走盗虫了，这是你想要的蘑菇！快送给奥尔里昂大人吧。',Speaker=6444,}",
  [89867] = "{id=89867,Text='哦，你已经拿到蘑菇了吗？不错！',Speaker=6730,}",
  [89868] = "{id=89868,Text='明天是最重要的一天，我将会教你顶级料理的制作方式。',Speaker=6730,}",
  [89869] = "{id=89869,Text='好好休息吧，准备好你的笔记本，明天是[c][ffff00]第四节课[-][/c]，好好学！',Speaker=6730,}",
  [89870] = "{id=89870,Text='终于来了吗，我等你好久了。',Speaker=6730,}",
  [89871] = "{id=89871,Text='第四节课，我会教你做一道醇珍蘑菇汤，这套厨具借给你用。',Speaker=6730,}",
  [89872] = "{id=89872,Text='现在听我说，加入蘑菇。',Speaker=6730,}",
  [89873] = "{id=89873,Text='然后再加入香料。',Speaker=6730,}",
  [89874] = "{id=89874,Text='最后加入颜色调料提色。',Speaker=6730,}",
  [89875] = "{id=89875,Text='好了，这个要煮一会，等着吧。',Speaker=6730,}",
  [89876] = "{id=89876,Text='美食配美酒，今天只有美食总感觉少了点什么……',Speaker=6730,}",
  [89877] = "{id=89877,Text='我听说莱厄斯最近买来了一些斐扬酒师酿造的美酒，你去拿一点。',Speaker=6730,}",
  [89878] = "{id=89878,Text='要酒？一边去，我的美酒可是花了大功夫从斐扬买到的，你这小鬼。',Speaker=6447,}",
  [89879] = "{id=89879,Text='什么？会长指导你煮了蘑菇汤！',Speaker=6447,}",
  [89880] = "{id=89880,Text='如果你能拿给我蘑菇汤，我才愿意把酒分给你！',Speaker=6447,Emoji=21,}",
  [89881] = "{id=89881,Text='真慢，蘑菇汤都煮好了，酒呢？',Speaker=6730,}",
  [89882] = "{id=89882,Text='什么？那个家伙还想要我的蘑菇汤！不给他！',Speaker=6730,Emoji=12,}",
  [89883] = "{id=89883,Text='气死我了，如果想喝酒只能用蘑菇汤换了……',Speaker=6730,}",
  [89884] = "{id=89884,Text='你倒一小碗给他吧，如果不是为了斐扬的美酒……',Speaker=6730,}",
  [89885] = "{id=89885,Text='蘑菇汤！哈哈哈哈……',Speaker=6447,}",
  [89886] = "{id=89886,Text='小鬼还挺厉害的嘛，呐，这是你想要的酒。',Speaker=6447,}",
  [89887] = "{id=89887,Text='换来了酒吗？做的不错，来品尝蘑菇汤吧，这是你的作品，不过还是在我的指导下。',Speaker=6730,}",
  [89888] = "{id=89888,Text='蘑菇汤的味道如何？',Speaker=6730,}",
  [89889] = "{id=89889,Text='这就是料理的魔力，希望你经过这次学习可以体会到我们料理师对料理的热爱。',Speaker=6730,}",
  [89890] = "{id=89890,Text='这些是你的奖励，明天是[c][ffff00]最后一课[-][/c]，不要迟到了！',Speaker=6730,}",
  [89891] = "{id=89891,Text='今天是精致料理的最后一次学习了，我们昨天已经制作了料理，今天的课程与料理制作无关。',Speaker=6730,}",
  [89892] = "{id=89892,Text='而是有关作为热爱美食的料理师，必须要有的分享精神。',Speaker=6730,}",
  [89893] = "{id=89893,Text='这里是我保存好的蘑菇汤，请你分别带给希莎娅、碧莎、胡雷特。',Speaker=6730,}",
  [89894] = "{id=89894,Text='他们对你学习料理提供了很多帮助。',Speaker=6730,}",
  [89895] = "{id=89895,Text='去吧，冒险者。',Speaker=6730,}",
  [89896] = "{id=89896,Text='会长的特别配方的蘑菇汤！莫非这次他教你做的是这道菜吗？',Speaker=6731,}",
  [89897] = "{id=89897,Text='……',Speaker=6731,}",
  [89898] = "{id=89898,Text='没想到，会长居然把自己的独门配方拿出来，让我品尝一下。',Speaker=6731,}",
  [89899] = "{id=89899,Text='太美味了，会长果然是最棒的。',Speaker=6731,}",
  [89900] = "{id=89900,Text='什么？是你做的？人不可貌相啊，谢谢你今天的款待。',Speaker=6731,}",
  [89901] = "{id=89901,Text='冒险者，这次有什么需要我帮组的吗？',Speaker=6446,}",
  [89902] = "{id=89902,Text='啊！你送来了你做的蘑菇汤，让我尝一尝……',Speaker=6446,}",
  [89903] = "{id=89903,Text='太美味了，没想到我的香料还可以做出来这么美味的汤。',Speaker=6446,}",
  [89904] = "{id=89904,Text='原来是奥尔里昂大人的配方，果然大人对食物的见解比较高深啊。',Speaker=6446,}",
  [89905] = "{id=89905,Text='谢谢你，冒险者，有机会也要来吃我做的料理哦。',Speaker=6446,}",
  [89906] = "{id=89906,Text='快拿来吧！咕哝咕哝咕哝……',Speaker=6444,}",
  [89907] = "{id=89907,Text='啊，真好喝！喂，你这是什么表情……',Speaker=6444,}",
  [89908] = "{id=89908,Text='你刚走过来我就闻到了蘑菇的香味，一闻就知道是会长大人指导的料理。',Speaker=6444,}",
  [89909] = "{id=89909,Text='这是我今年喝过最美味的汤了！',Speaker=6444,}",
  [89910] = "{id=89910,Text='也不枉我送你蘑菇，干的不错！',Speaker=6444,}",
  [89911] = "{id=89911,Text='蘑菇汤都送到了吗？',Speaker=6730,}",
  [89912] = "{id=89912,Text='很好，现在你明白了美食的真谛吗？',Speaker=6730,Option='明白了！',}",
  [89913] = "{id=89913,Text='是的，美食需要与人分享，其他人喜欢自己制作的食物，才是一个料理师的最高荣誉。',Speaker=6730,}",
  [89914] = "{id=89914,Text='希望这几天的教学，你可以有所收获。',Speaker=6730,}",
  [89915] = "{id=89915,Text='也不枉费我说了这么多。',Speaker=6730,}",
  [89916] = "{id=89916,Text='好了，这些是最后的奖励，拿好吧。',Speaker=6730,}",
  [89918] = "{id=89918,Text='你好，冒险者，欢迎你的到来！',Speaker=6728,}",
  [89919] = "{id=89919,Text='冒险者，你要领取15枚游园币奖励吗？每个人只能领取一次哦！',Speaker=6728,Option='{确认领取,2},{更换账号,3}',}",
  [89920] = "{id=89920,Text='我明白了，我会在这里等你再次到来！',Speaker=6728,}",
  [89921] = "{id=89921,Text='这是你的游园币，好好利用，不要浪费哦！',Speaker=6728,}",
  [89922] = "{id=89922,Text='亲爱的冒险者，特大喜讯，最近圣地管理者路德维希、爱马仕、桑德亚都被美食所吸引，来到了活动广场。',Speaker=6731,}",
  [89923] = "{id=89923,Text='活动广场开启了通往圣地【猫猫之家】【花海】【梦幻摩天轮】的捷径。',Speaker=6731,}",
  [89924] = "{id=89924,Text='只要跟他们三位申请，就可以直接前往圣地游玩呢！',Speaker=6731,}",
  [89925] = "{id=89925,Text='据说圣地里还有游园会管理者乔治娅、曼切斯顿和莫莫，如果陪他们聊天，可以获得更多奖励！',Speaker=6731,}",
  [89926] = "{id=89926,Text='冒险者，还不快行动起来！',Speaker=6731,}",
  [89927] = "{id=89927,Text='你好，冒险者，欢迎你的到来！',Speaker=6729,}",
  [89928] = "{id=89928,Text='冒险者，你要领取15枚游园币奖励吗？每个人只能领取一次哦！',Speaker=6729,Option='{确认领取,2},{更换账号,3}',}",
  [89929] = "{id=89929,Text='我明白了，我会在这里等你再次到来！',Speaker=6729,}",
  [89930] = "{id=89930,Text='这是你的游园币，好好利用，不要浪费哦！',Speaker=6729,}",
  [89931] = "{id=89931,Text='你好，冒险者，欢迎你的到来！',Speaker=6727,}",
  [89932] = "{id=89932,Text='冒险者，你要领取15枚游园币奖励吗？每个人只能领取一次哦！',Speaker=6727,Option='{确认领取,2},{更换账号,3}',}",
  [89933] = "{id=89933,Text='我明白了，我会在这里等你再次到来！',Speaker=6727,}",
  [89934] = "{id=89934,Text='这是你的游园币，好好利用，不要浪费哦！',Speaker=6727,}",
  [89935] = "{id=89935,Text='亲爱的冒险者，马上将有一场华丽的美食大赛，你愿意帮助皇家美食协会准备一些比赛需要的食材吗？',Speaker=6731,}",
  [89936] = "{id=89936,Text='快来活动广场参加美食储备赛吧！',Speaker=6731,}",
  [89937] = "{id=89937,Text='每天凌晨5点的时候，美食协会的厨师们都会准时开始收食材。做一个负责任的厨师真不容易啊，起早贪黑工作！',Speaker=6731,}",
  [89938] = "{id=89938,Text='每天都可以找到四位厨师捐赠食材，每次捐赠厨师们都有好礼相送哦！',Speaker=6731,}",
  [89939] = "{id=89939,Text='日安，[c][ffff00][PlayerName][-][/c]，请问你是否确定要参加我们此次的食材储备赛呢？',Speaker=6720,Option='{确认参加,3},{更换账号,2}',}",
  [89940] = "{id=89940,Text='活动机会难得，务必确认是否要参加哦！',Speaker=6720,}",
  [89941] = "{id=89941,Text='让我看看我们缺少哪种食材……',Speaker=6720,}",
  [89942] = "{id=89942,Text='唔……我们缺少[c][ffff00]疯兔肉[-][/c]，请你捐给我们一点吧！',Speaker=6720,}",
  [89943] = "{id=89943,Text='这么快就找到了我们需要的食材吗？真不愧是[c][ffff00][PlayerName][-][/c]！让我看看是不是收集足够了呢…',Speaker=6720,}",
  [89944] = "{id=89944,Text='数量已经足够了，你确定要捐赠给我吗？',Speaker=6720,Option='{捐赠,16},{暂时不捐,15}',}",
  [89945] = "{id=89945,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6720,}",
  [89946] = "{id=89946,Text='谢谢你，有了这些食材，我们就可以顺利的举办比赛了！',Speaker=6720,}",
  [89947] = "{id=89947,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6720,}",
  [89948] = "{id=89948,Text='让我看看我们缺少哪种食材……',Speaker=6720,}",
  [89949] = "{id=89949,Text='唔……我们缺少[c][ffff00]螃蟹肉[-][/c]，请你捐给我们一点吧！',Speaker=6720,}",
  [89950] = "{id=89950,Text='这么快就找到了我们需要的食材吗？真不愧是[c][ffff00][PlayerName][-][/c]！让我看看是不是收集足够了呢…',Speaker=6720,}",
  [89951] = "{id=89951,Text='数量已经足够了，你确定要捐赠给我吗？',Speaker=6720,Option='{捐赠,26},{暂时不捐,25}',}",
  [89952] = "{id=89952,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6720,}",
  [89953] = "{id=89953,Text='谢谢你，有了这些食材，我们就可以顺利的举办比赛了！',Speaker=6720,}",
  [89954] = "{id=89954,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6720,}",
  [89955] = "{id=89955,Text='让我看看我们缺少哪种食材……',Speaker=6720,}",
  [89956] = "{id=89956,Text='唔……我们缺少[c][ffff00]西门小番茄[-][/c]，请你捐给我们一点吧！',Speaker=6720,}",
  [89957] = "{id=89957,Text='这么快就找到了我们需要的食材吗？真不愧是[c][ffff00][PlayerName][-][/c]！让我看看是不是收集足够了呢…',Speaker=6720,}",
  [89958] = "{id=89958,Text='数量已经足够了，你确定要捐赠给我吗？',Speaker=6720,Option='{捐赠,36},{暂时不捐,35}',}",
  [89959] = "{id=89959,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6720,}",
  [89960] = "{id=89960,Text='谢谢你，有了这些食材，我们就可以顺利的举办比赛了！',Speaker=6720,}",
  [89961] = "{id=89961,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6720,}",
  [89962] = "{id=89962,Text='让我看看我们缺少哪种食材……',Speaker=6720,}",
  [89963] = "{id=89963,Text='唔……我们缺少[c][ffff00]波利苹果[-][/c]，请你捐给我们一点吧！',Speaker=6720,}",
  [89964] = "{id=89964,Text='这么快就找到了我们需要的食材吗？真不愧是[c][ffff00][PlayerName][-][/c]！让我看看是不是收集足够了呢…',Speaker=6720,}",
  [89965] = "{id=89965,Text='数量已经足够了，你确定要捐赠给我吗？',Speaker=6720,Option='{捐赠,46},{暂时不捐,45}',}",
  [89966] = "{id=89966,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6720,}",
  [89967] = "{id=89967,Text='谢谢你，有了这些食材，我们就可以顺利的举办比赛了！',Speaker=6720,}",
  [89968] = "{id=89968,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6720,}",
  [89969] = "{id=89969,Text='让我看看我们缺少哪种食材……',Speaker=6720,}",
  [89970] = "{id=89970,Text='唔……我们缺少[c][ffff00]盐[-][/c]，请你捐给我们一点吧！',Speaker=6720,}",
  [89971] = "{id=89971,Text='这么快就找到了我们需要的食材吗？真不愧是[c][ffff00][PlayerName][-][/c]！让我看看是不是收集足够了呢…',Speaker=6720,}",
  [89972] = "{id=89972,Text='数量已经足够了，你确定要捐赠给我吗？',Speaker=6720,Option='{捐赠,56},{暂时不捐,55}',}",
  [89973] = "{id=89973,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6720,}",
