  [90067] = "{id=90067,Text='唔……我们缺少[c][ffff00]竹林茄子[-][/c]，请你捐给我们一点吧！',Speaker=6723,}",
  [90068] = "{id=90068,Text='这么快就找到了我们需要的食材吗？真不愧是[c][ffff00][PlayerName][-][/c]！让我看看是不是收集足够了呢…',Speaker=6723,}",
  [90069] = "{id=90069,Text='数量已经足够了，你确定要捐赠给我吗？',Speaker=6723,Option='{捐赠,46},{暂时不捐,45}',}",
  [90070] = "{id=90070,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6723,}",
  [90071] = "{id=90071,Text='谢谢你，有了这些食材，我们就可以顺利的举办比赛了！',Speaker=6723,}",
  [90072] = "{id=90072,Text='嗯？好像数量不够哦，请找全食材以后再来找我哦！',Speaker=6723,}",
  [90100] = "{id=90100,Text='哦吼~是[c][ffff00][PlayerName][-][/c]啊，想不到你那么快就脱离菜鸟成为了一名了不起的冒险家了。',Speaker=1024,Emoji=7,}",
  [90101] = "{id=90101,Text='最近关于你的冒险传闻从斐扬到朱诺无人不知无人不晓。[c][ffff00]冒险者公会[-][/c]的众人都会铭记你所带来的荣耀。',Speaker=1024,Emoji=9,}",
  [90102] = "{id=90102,Text='想必你不会止步于此吧，嗯，是时候回去找你的职业导师聊聊了，说不定他会为你指明一条新的未来航路。',Speaker=1024,Emoji=7,}",
  [90103] = "{id=90103,Text='嗯！我的朋友，你已经成为一名能够独当一面的合格[c][ffff00]骑士[-][/c]了！为了守护大陆和人民你所付出的努力绝不会被遗忘！荣耀与骑士团同在！',Speaker=1101,Emoji=6,}",
  [90104] = "{id=90104,Text='该是你成为一名[c][ffff00]骑士领主[-][/c]的时候了。如果确定了就开始职业宣誓吧！',Speaker=1101,Option='{开始测试,0}{稍等,2}',Emoji=26,}",
  [90105] = "{id=90105,Text='嗯！很好！我的朋友！跟我来吧！荣耀的时刻！',Speaker=1101,Option='{是否接受转职,6}{还没准备好,5}',Emoji=23,}",
  [90106] = "{id=90106,Text='就让我们一起见证一名伟大的[c][ffff00]骑士领主[-][/c]的诞生吧！愿荣耀与骑士团同在！',Speaker=1101,Option='开始转职',Emoji=7,}",
  [90107] = "{id=90107,Text='是否要离开转职大厅？',Speaker=1101,Option='{离开这里,2}{稍等一下,1}',Emoji=8,}",
  [90108] = "{id=90108,Text='(看你的眼神明显变得尊敬起来)',Speaker=1102,Emoji=14,}",
  [90109] = "{id=90109,Text='呼呼呼，是[c][ffff00][PlayerName][-][/c]啊，魔导力量的渴求者，看来你在探索之路上已经有了很大的进展。',Speaker=1102,Emoji=25,}",
  [90110] = "{id=90110,Text='时机差不多也到了你该继续走向真相的那一步了，来成为[c][ffff00]超魔导士[-][/c]吧！',Speaker=1102,Emoji=11,}",
  [90111] = "{id=90111,Text='(杜赫塔开始咏唱奇怪的咒文，但是你开始尝试跟着读懂它们)',Speaker=1102,Option='{开始跟着咏唱,0}{稍等,2}',Emoji=14,}",
  [90112] = "{id=90112,Text='呼呼呼，我将精神力的魔导元素传达给你的触媒了，希望他能协助你成为达到真相的钥匙。接下来就让我们开始仪式吧。',Speaker=1102,Option='{是否接受转职,6}{还没准备好,5}',Emoji=25,}",
  [90113] = "{id=90113,Text='就让我们一起见证一名伟大的[c][ffff00]超魔导士[-][/c]的诞生吧！永远勿忘真理和正义！',Speaker=1102,Option='开始转职',Emoji=20,}",
  [90114] = "{id=90114,Text='是否要离开转职大厅？',Speaker=1102,Option='{离开这里,2}{稍等一下,1}',Emoji=8,}",
  [90115] = "{id=90115,Text='…真没想到，[c][ffff00][PlayerName][-][/c]，你居然还活着，并且还做了不少让我也觉得刮目相看的事啊~',Speaker=1103,Emoji=14,}",
  [90116] = "{id=90116,Text='哼哼哼…既然如此，想要成为[c][ffff00]十字刺客[-][/c]这点我会给予你最大的帮助的。',Speaker=1103,Emoji=14,}",
  [90117] = "{id=90117,Text='当然~前提是你依然坚持，即使会掉丢性命也要如此做的话。',Speaker=1103,Option='{开始测试,0}{稍等,2}',Emoji=5,}",
  [90118] = "{id=90118,Text='哼哼哼…看来这些你已近了如指掌了。不怕死就跟我来吧，这一路我都会继续好好看着你的呢。哼哼哼。',Speaker=1103,Option='{是否接受转职,6}{还没准备好,5}',Emoji=14,}",
  [90119] = "{id=90119,Text='这个人的生命已经与我们刺客联盟血脉联系在一起，是时候让他成为一名[c][ffff00]十字刺客[-][/c]了！',Speaker=1103,Option='开始转职',Emoji=11,}",
  [90120] = "{id=90120,Text='是否要离开转职大厅？',Speaker=1103,Option='{离开这里,2}{稍等一下,1}',Emoji=14,}",
  [90121] = "{id=90121,Text='哦呀~哦呀~看看是谁来了~这不是我们伟大的[c][ffff00][PlayerName][-][/c]嘛！',Speaker=1104,Emoji=2,}",
  [90122] = "{id=90122,Text='和公会的传闻一样，你已经成为一名合格的老猎人了呀~',Speaker=1104,Emoji=4,}",
  [90123] = "{id=90123,Text='你应该知道，这门技艺是没有终极的，下一步，该是你成为[c][ffff00]神射手[-][/c]的时候了呢，是不是已经期待很久了呀！嘻嘻嘻。',Speaker=1104,Emoji=27,}",
  [90124] = "{id=90124,Text='接下来只需填一下这张神射手的申请表就可以了呢！赶快吧！',Speaker=1104,Option='{开始测试,0}{稍等,2}',Emoji=21,}",
  [90125] = "{id=90125,Text='啊哈哈哈~今天真的是个值得纪念的日子呢~就让我们抬头挺胸高高兴兴地去进行转职仪式吧~',Speaker=1104,Option='{是否接受转职,6}{还没准备好,5}',Emoji=17,}",
  [90126] = "{id=90126,Text='就让我们一起见证一名伟大的 神射手 的诞生吧！他必将为公会带来更多的光荣！',Speaker=1104,Option='开始转职',Emoji=20,}",
  [90127] = "{id=90127,Text='是否要离开转职大厅？',Speaker=1104,Option='{离开这里,2}{稍等一下,1}',Emoji=3,}",
  [90128] = "{id=90128,Text='(修女带着微笑缓缓地抬起了头)',Speaker=1105,Emoji=11,}",
  [90129] = "{id=90129,Text='感谢主神，[c][ffff00][PlayerName][-][/c]，你所做的一切都为主神降临于人间的赐福增添了圣洁的光芒。',Speaker=1105,Emoji=6,}",
  [90130] = "{id=90130,Text='教会希望你能将这份光芒带给大陆上更多的人们，当然，是以[c][ffff00]神官[-][/c]的身份！',Speaker=1105,Emoji=30,}",
  [90131] = "{id=90131,Text='如果你已经拥有这份觉悟，便就此宣誓吧。',Speaker=1105,Option='{开始测试,0}{稍等,2}',Emoji=9,}",
  [90132] = "{id=90132,Text='赞美主神，让我们这就前往进行你[c][ffff00]神官[-][/c]的任职仪式吧。',Speaker=1105,Option='{是否接受转职,6}{还没准备好,5}',Emoji=30,}",
  [90133] = "{id=90133,Text='就让我们一起见证一名伟大的[c][ffff00]神官[-][/c]的诞生吧！愿主的光芒永远照耀你！',Speaker=1105,Option='开始转职',Emoji=30,}",
  [90134] = "{id=90134,Text='是否要离开转职大厅？',Speaker=1105,Option='{离开这里,2}{稍等一下,1}',Emoji=8,}",
  [91007] = "{id=91007,Text='欢迎你，冒险者！',Speaker=1008,}",
  [91064] = "{id=91064,Text='我为我弟弟自豪！',Speaker=1068,}",
  [91065] = "{id=91065,Text='马上要去依斯鲁得支援了。弟弟，保重啊！',Speaker=1068,}",
  [91114] = "{id=91114,Text='我的心上人很久都没回家了，你看到他能马上通知我吗？',Speaker=1002,}",
  [93000] = "{id=93000,Text='…',}",
  [93002] = "{id=93002,Text='期待您的再次光临！',Speaker=1015,Emoji=17,Action={actionid=34},}",
  [93003] = "{id=93003,Text='已经存储好了呢，谢谢您的使用！',Speaker=1015,Emoji=6,Action={actionid=34,num=1},}",
  [93004] = "{id=93004,Text='要打开仓库了呢，收费%sZeny，谢谢您的使用！',Speaker=1015,Option='{好的,2}{下次吧,1}',Emoji=6,Action={actionid=34,num=1},}",
  [93005] = "{id=93005,Text='你愿意与你心中的挚爱一起登上我们的爱情摩天轮吗？',Speaker=1182,Option='{Yes I do,2}{容我三思,1}',}",
  [93006] = "{id=93006,Text='Sorry~只有与你心爱的人组队才可以登上我们的爱情摩天轮哦~',Speaker=1182,Emoji=16,}",
  [93007] = "{id=93007,Text='Sorry~你确认你带对了你的另一半吗？',Speaker=1182,Emoji=25,}",
  [93008] = "{id=93008,Text='Sorry~登陆摩天轮需要消耗一张“爱的证明”哦！',Speaker=1182,Emoji=13,}",
  [93011] = "{id=93011,Text='吉芬的那些魔法师算什么，想要获得伟大的生灵力量的话，可以向我许愿哦，当然也可以找我来解除一些不喜欢的魔法效果，收费的哦！',Speaker=1345,Option='{赐予我力量吧,6}{解除魔法,29}',}",
  [93012] = "{id=93012,Text='恭喜你已经通过了试炼，赐予你力量！',Speaker=1345,}",
  [93013] = "{id=93013,Text='最后一步都无法坚持，赐你野猪之力，想要解除只需要找我认错即可。',Speaker=1345,}",
  [93014] = "{id=93014,Text='不是也是给我变！~要恢复记得找我认罪。',Speaker=1345,}",
  [93015] = "{id=93015,Text='本宝宝最讨厌半途而废的，不认罪就一直当猪吧~哼！',Speaker=1345,}",
  [93016] = "{id=93016,Text='恭喜你贯彻了神猪之路！',Speaker=1345,}",
  [93017] = "{id=93017,Text='晚了小野猪~哦呵呵呵呵呵~',Speaker=1345,}",
  [93018] = "{id=93018,Text='你居然想消灭人类？太可怕了，不来忏悔你就一直当猪吧！',Speaker=1345,}",
  [93019] = "{id=93019,Text='不喜欢波利也敢来找我？本宝宝不开心了，想要恢复请找我认罪。',Speaker=1345,}",
  [93020] = "{id=93020,Text='波利哪里不可爱了！魂淡去猪圈里忏悔吧！',Speaker=1345,}",
  [93021] = "{id=93021,Text='恭喜你通过考验，赐你本宝宝神力！',Speaker=1345,}",
  [93022] = "{id=93022,Text='没准备？你来找我干嘛？猪啊！',Speaker=1345,}",
  [93023] = "{id=93023,Text='既然你还没准备好，就继续你的“猪”生旅程吧！',Speaker=1345,}",
  [93024] = "{id=93024,Text='算了原谅你了~马里麻利哄！',Speaker=1345,}",
  [93025] = "{id=93025,Text='你要体验哪种摩天轮包间呢？',Speaker=1182,Option='{1号,10}{2号,11}',}",
  [93029] = "{id=93029,Text='你已经激活过本地图。',Speaker=1015,}",
  [93030] = "{id=93030,Text='你已经激活过本地图。',Speaker=1058,}",
  [93031] = "{id=93031,Text='此地的通信传送已被你激活了~很高兴为你服务。',Speaker=1058,}",
  [93034] = "{id=93034,Text='那真是太遗憾了…多好的伙伴啊！',Speaker=2122,}",
  [93038] = "{id=93038,Text='冒险家击败魔物解决危机，我研究魔物拯救人类。',Speaker=1166,Emoji=5,}",
  [93039] = "{id=93039,Text='此地的通信传送已被你激活了~很高兴为你服务。',Speaker=1015,}",
  [93044] = "{id=93044,Text='欢迎~伟大的资深冒险家，我们为[c][ffff00]“资深冒险家”[-][/c]追加了一批新头饰~希望你会喜欢~',Speaker=2077,}",
  [93045] = "{id=93045,Text='哇哦~~又到了追加新头饰的季节，我们为[c][ffff00]“王牌冒险家”[-][/c]追加了一批新头饰~希望你会喜欢~',Speaker=2078,}",
  [94010] = "{id=94010,Text='初次见面，尊贵的客人，我们是致力于为大陆人们带来幸福和快乐的结社组织：[c][ffff00]幻想马戏团[-][/c]。',Speaker=1182,Emoji=9,}",
  [94011] = "{id=94011,Text='而在下便是负责在此处魔法源泉搭建起这个[c][ffff00]梦幻摩天轮[-][/c]以供人们的娱乐的魔法建筑师：路德维希·西斯廷·巴特尔特。',Speaker=1182,Emoji=20,}",
  [94012] = "{id=94012,Text='没错，正如您所听到的传闻一样，能来到这里一起游玩过的男女两人都爱神所祝福呦。',Speaker=1182,Emoji=4,}",
  [94013] = "{id=94013,Text='啊哈~客人您只需要出示一张我们[c][ffff00]幻想马戏团[-][/c]特别提供的[c][ffff00]幻想马戏团门票[-][/c]便可带着你心仪之人进入游玩啦~',Speaker=1182,Emoji=2,}",
  [94014] = "{id=94014,Text='那么，想与你(妳)心中的挚爱一起登上我们的[c][ffff00]梦幻摩天轮[-][/c]吗？',Speaker=1182,Option='{Yes I do,2}{容我三思,1}',}",
  [94015] = "{id=94015,Text='哎呀呀呀~尊贵的客人，只有与你心爱的人组队才可以登上我们的[c][ffff00]梦幻摩天轮[-][/c]哦~、',Speaker=1182,}",
  [94016] = "{id=94016,Text='哎哎哎？！尊贵的客人，你确认你带对了你的另一半吗？！',Speaker=1182,}",
  [94017] = "{id=94017,Text='哦呀哦呀~尊贵的客人，想要游玩[c][ffff00]梦幻摩天轮[-][/c]需要消耗一张[c][ffff00]幻想马戏团特别邀请券[-][/c]哦~',Speaker=1182,}",
  [94018] = "{id=94018,Text='尊贵的客人，我们是致力于为大陆人们带来幸福和快乐的结社组织：[c][ffff00]幻想马戏团[-][/c]。',Speaker=1182,Emoji=17,}",
  [94043] = "{id=94043,Text='这附近似乎有时空裂隙出现，去找找看吧。',}",
  [94044] = "{id=94044,Text='这附近似乎有时空裂隙出现，去找找看吧。',}",
  [94045] = "{id=94045,Text='嗯？ 这是…',}",
  [94046] = "{id=94046,Text='这里是米德加尔特旅游协会，我们的海龟可是很海底旅游必备的哦！',Speaker=2129,}",
  [94061] = "{id=94061,Text='这里虽然很危险，但是也隐藏着无数好看的风景哦~~~',Speaker=2503,}",
  [95001] = "{id=95001,Text='普隆德拉是卢恩·米德加尔特王国的首都，周边是城墙所包围构成的城下街，以北便是普隆德拉王城。而城墙外枝叶繁茂，拥有各种丰富的自然生态。同时，这里也是冒险者们组队和接受各种冒险任务的主要城市。',Speaker=1015,}",
  [95002] = "{id=95002,Text='下水道位于普隆德拉的地下，潮湿、幽暗、脏乱的环境成为了魔物的隐僻之地，只有地下水道讨伐队才被允许进入。',Speaker=1058,}",
  [95003] = "{id=95003,Text='普隆德拉西门拥有枝叶繁茂的自然生态环境，并且是连接吉芬与普隆德拉的要道。',Speaker=1058,}",
  [95004] = "{id=95004,Text='迷藏森林分别由16块迷雾区域组成的迷阵，曾经有位传说级的冒险家说正确的行走路线应该是上下左右 下上左 上上左…(@д@)抱歉，我已经晕了！',Speaker=1058,}",
  [95005] = "{id=95005,Text='依斯鲁得是普隆德拉的卫星城，世界各地的冒险公会都喜欢在此地招募冒险家，你也是来寻找志同道合的冒险家公会吗？',Speaker=1015,}",
  [95006] = "{id=95006,Text='沉没之船位于依斯鲁得上方，据说每年来到沉船的勇者不计其数，然而进去后就查无音讯。',Speaker=1058,}",
  [95007] = "{id=95007,Text='柏伊亚岚岛是通过依斯鲁得坐船才能抵达，穿过柏伊亚岚岛，海底洞穴就会展现在眼前，那堆成山的金灿灿的被诅咒的宝藏就沉睡在海底。',Speaker=1058,}",
  [95008] = "{id=95008,Text='吉芬被称为『魔法之都』，传说在吉芬的地底下有一座古老的遗迹，它带着\"玛娜神力\"的力量，这么多年来，吸引着许多魔法师的到来。',Speaker=1015,}",
  [95009] = "{id=95009,Text='妙勒尼山脉，富饶而又神秘的环形山脉总是让冒险者在美丽的花丛中迷失方向，传说中在妙勒尼有一个古老的通道，与艾卡拉奇平原存在着某种联系。',Speaker=1058,}",
  [95010] = "{id=95010,Text='梦罗克被称为『沙漠之都』，一直以来，由于王国的力量无法影响到这里，整座城市为盗贼所支配，而传说中的盗贼导师也就隐匿在这里…',Speaker=1058,}",
  [95011] = "{id=95011,Text='在广袤的大沙漠中，坐落着鳞次栉比的金字塔，而在沙漠西北方位矗立着一座与众不同的金字塔，它气势威严、结构精巧、雕花的纹路清晰可见。',Speaker=1058,}",
  [95012] = "{id=95012,Text='斐扬南部地区是前往斐扬的必经之路，这里山林环绕，野兽横行，每年都有无数冒险者在此试炼成长。',Speaker=1058,}",
  [95013] = "{id=95013,Text='斐扬洞窟是斐扬地区有数的危险之地，洞窟中充斥着不死生物，但是仍然有无数冒险者前往这次寻找传说中洞窟中的秘宝。',Speaker=1058,}",
  [95014] = "{id=95014,Text='兽人村是神秘的兽人族领地，王国的力量无法支配这里，神秘却强大的兽人吸引了无数冒险者前来冒险。',Speaker=1058,}",
  [95015] = "{id=95015,Text='龙区是大陆上有数的神秘地区，生存了无数强大的生物，在冒险者们的齐心协力下，终于开始揭开了它神秘的面纱。',Speaker=1058,}",
  [95016] = "{id=95016,Text='吉芬城外的哥布灵森林是哥布灵一族的栖息地，哥布灵总是对外人保持警惕，但是这并不能阻止冒险者探索的脚步。',Speaker=1058,}",
  [95017] = "{id=95017,Text='犬妖森林，神秘且强大的犬妖们栖息的地方，胆敢闯入森林中的人都会被犬妖消灭，但也有不怕死的冒险者进入森林试炼。',Speaker=1058,}",
  [95018] = "{id=95018,Text='苏克拉特沙漠是前往沙漠之城梦罗克的必经之路，这里风沙遍地，魔兽横行，是个不折不扣的危险之地。',Speaker=1058,}",
  [95019] = "{id=95019,Text='斐扬树林是斐扬城外的一片危险之地，里面树林茂密，魔物横行，是斐扬地区有数的危险地区之一。',Speaker=1058,}",
  [95020] = "{id=95020,Text='兽人洞窟是兽人以前的住所，兽人被迫离开洞窟之后，洞窟中经常出现一些诡异而又神秘的兽人身影。',Speaker=1058,}",
  [95021] = "{id=95021,Text='古老而神秘的吉芬塔地下，隐藏这许多不为人知的秘密，这些秘密驱使着无数冒险者前往冒险。',Speaker=1058,}",
  [95022] = "{id=95022,Text='斐扬是隐藏在群山之中的山岳之城，与外面世界的隔绝，是的斐扬依然得以保留它的传统和地方特色，并未受到卢恩·米德加尔特王国的影响。',Speaker=1015,}",
  [95023] = "{id=95023,Text='幽灵船是伴随这沉没之船而出现的，里面的幽灵与骸骨让人毛骨悚然，但是这丝毫不影响冒险者们的探索。',Speaker=1058,}",
  [95024] = "{id=95024,Text='克特森林是犬妖的领地，这里充满了危险，你不知道犬妖和那些狂暴野猫会什么时候冲出来进攻你。',Speaker=1058,}",
  [95025] = "{id=95025,Text='古城郊外是一片生机盎然的森林草地，这里生活着大量龙类魔物，你可不要招惹它们哦，它们发起怒来很可怕！',Speaker=1058,}",
  [95027] = "{id=95027,Text='这里的魔物非常凶猛，不过不用担心，音乐精灵会在这里治愈你们的创伤的！',Speaker=1058,}",
  [95028] = "{id=95028,Text='潮湿肮脏的下水道充满了危险，但是有我在，我会用音乐给予你勇气与力量。',Speaker=1058,}",
  [95029] = "{id=95029,Text='这里是曾经克雷斯特汉姆王室训练强大的骑士的场所，现如今已经成为了黑暗魔物生活的乐土。',Speaker=1058,}",
  [95030] = "{id=95030,Text='这些不曾毁去的建筑诉说这昔日古城的强盛，但是现在，克雷斯特汉姆只剩下那些凶猛无比的黑暗魔物了。',Speaker=1058,}",
  [95037] = "{id=95037,Text='这里的气氛让我也有些不舒服了，不过只要有音乐的伴随，我就会有无限的勇气。',Speaker=1058,}",
  [96001] = "{id=96001,Text='嗨，[c][ffff00][PlayerName][-][/c]，你终于来啦！',Speaker=1050,}",
  [96002] = "{id=96002,Text='说好一起来[c][ffff00]报名乐园团[-][/c]的，结果让我先排队，自己却不见了…',Speaker=1050,Emoji=12,}",
  [96003] = "{id=96003,Text='还以为你遇到魔物了，没想到是在这晃悠发呆，做白日梦也得有个限度嘛，真是的…',Speaker=1050,}",
  [96004] = "{id=96004,Text='算啦，赶紧和边上的[c][ffff00]艾琳小姐[-][/c]打声招呼吧，她也在担心你呢。',Speaker=1050,Emoji=15,}",
  [96005] = "{id=96005,Text='赛尼亚，这是你的同伴[c][ffff00][PlayerName][-][/c]吗？',Speaker=1042,Emoji=26,}",
  [96006] = "{id=96006,Text='是哒，艾琳小姐。这家伙脑袋里经常会冒出些奇怪的事情，不知道在想什么，就知道瞎转和发呆…',Speaker=1050,Emoji=25,}",
  [96007] = "{id=96007,Text='[c][ffff00][PlayerName][-][/c]注意啦：在成为冒险者后可以接取各种类型的委托，在完成过程中有时会非常危险，尤其在和魔物战斗的时候可不能发呆哦！',Speaker=1042,}",
  [96008] = "{id=96008,Text='放心吧！这家伙虽然看起来呆呆的，战斗起来却出奇的敏捷，真不知道点了什么天赋。',Speaker=1050,Emoji=19,}",
  [96009] = "{id=96009,Text='那就好…我已经帮你们登记好了。不过想要加入乐园团，大家一般都会去找[c][ffff00]教官维琪[-][/c]进行考试审核。',Speaker=1042,}",
  [96010] = "{id=96010,Text='是[c][ffff00][PlayerName][-][/c]吗？看起来激情满满啊~来，让我确认下！',Speaker=1054,}",
  [96011] = "{id=96011,Text='嗯…没有替考，也没发现作弊工具。好的，检查完毕！接下来给你简单介绍下[c][ffff00]入团考试[-][/c]事项吧。',Speaker=1054,Emoji=26,}",
  [96012] = "{id=96012,Text='由于近期各地魔物事件激增，导致[c][ffff00]冒险者公会[-][/c]人手不足，于是[c][ffff00]乐园团[-][/c]也被纳为正规战斗组织了，所以人员挑选会变得严格些。',Speaker=1054,}",
  [96013] = "{id=96013,Text='接下来我先说下流程：一共有[c][ffff00]三个考试项目[-][/c]，你可以分别找我和边上的两位考官接取，全部完成后可以找我完成最后的入团手续！',Speaker=1054,Emoji=20,}",
  [96014] = "{id=96014,Text='当然也不用担心，为了协助大家更好地完成考试项目，我们会提供独特的新手装备给冒险者。待遇不错吧，想要现在领取吗？',Speaker=1054,Option='现在就要领！',}",
  [96015] = "{id=96015,Text='[c][ffff00][PlayerName][-][/c]，嗯~考试项目一，内容如下：[c][ffff00]波伊[-][/c]最近又调皮了，赶紧去了解下状况…',Speaker=1188,Option='有点迷糊…',}",
  [96016] = "{id=96016,Text='波伊经常在南门的西边玩耍，从这往左下方走应该能看到它。最近有路人反映波伊在偷偷捣鼓什么，你马上过去看看，可别出乱子。',Speaker=1188,Option='这就是考试？',Emoji=5,}",
  [96017] = "{id=96017,Text='啵咿~啵咿~你是伯尼专门派来找波伊玩的吗？',Speaker=1059,Option='波利会说话？',Emoji=11,}",
  [96018] = "{id=96018,Text='别吃惊嘛，人家本来是波利王子哟，受到魔王梦罗克的诅咒后，说的波利语就都转变成人类的语言了~啵~',Speaker=1059,}",
  [96019] = "{id=96019,Text='因为语言不通，没有波利陪波伊玩了，于是只好暂时离开波利岛，到处看看有没有破解诅咒的方法~啵咿~',Speaker=1059,Emoji=24,}",
  [96020] = "{id=96020,Text='嘛，还是聊点有趣的~昨天波伊遇到一支商队在运送很多货物，于是人家就捡了点好玩东西~啵~',Speaker=1059,Option='偷来的吧…',Emoji=17,}",
  [96021] = "{id=96021,Text='别这样说嘛，人家不小心撞到商队后从地上拾起来的~反正是好玩的东西，一起来玩吧~啵~',Speaker=1059,Option='[c][ffff00]枯树枝[-][/c]？！',}",
  [96022] = "{id=96022,Text='是哒！好激动哦！据说使用[c][ffff00]枯树枝[-][/c]后，会有好玩的事发生哦，快试试看！啵~',Speaker=1059,}",
  [96023] = "{id=96023,Text='竟然有魔物出现了！波伊吓了一跳呢，好刺激，再玩一次吧~啵~',Speaker=1059,Emoji=9,}",
  [96024] = "{id=96024,Text='哇哦~那些魔物看起来好强的啵~[c][ffff00]枯树枝[-][/c]果然很有趣啊，啵咿~',Speaker=1059,}",
  [96025] = "{id=96025,Text='这次玩得好尽兴！代我向伯尼问好~波伊抽空再去找点[c][ffff00]血迹树枝[-][/c]来玩~再见噜，下次记得找人家一起玩~啵咿~',Speaker=1059,Emoji=3,}",
  [96026] = "{id=96026,Text='完成得不错嘛，恭喜顺利通过考试项目一！竟然没被波伊坑到，这家伙运气真好！',Speaker=1188,Emoji=20,}",
  [96027] = "{id=96027,Text='是[c][ffff00][PlayerName][-][/c]啊，你是来继续考试的吧？[c][ffff00]邮递员班尼[-][/c]的宠物拉比丝走丢了，你去看看吧。',Speaker=1187,}",
  [96028] = "{id=96028,Text='呜呜呜…我最爱的[c][ffff00]拉比丝[-][/c]，你去哪里了啊？！',Speaker=1060,Option='什么情况？',Emoji=19,}",
  [96029] = "{id=96029,Text='是这样的：拉比丝是我的宠物，一只非常温顺的[c][ffff00]疯兔[-][/c]。我们从艾尔贝塔送信过来，但进入普隆德拉南门区域后，拉比丝突然变得有点奇怪。',Speaker=1060,Option='怎么奇怪？',}",
  [96030] = "{id=96030,Text='起初拉比丝有点不安，我就一路安抚它。',Speaker=1060,Option='我试着找下',}",
  [96031] = "{id=96031,Text='太感谢你了，听说下方不远处的[c][ffff00]绿叶草地[-][/c]是疯兔平时最爱聚集的地方，你可以去那找找。',Speaker=1060,}",
  [96032] = "{id=96032,Text='[c][ffff00]绿叶草地[-][/c]…在附近找找看吧！',}",
  [96033] = "{id=96033,Text='哇！有魔物出现！被包围了！',Emoji=1,}",
  [96034] = "{id=96034,Text='疯兔怎么都狂暴了？得仔细调查出原因才行！',}",
  [96035] = "{id=96035,Text='有一只体型巨大的疯兔冲过来了，不知道是不是拉比丝，看上去异变的情况很严重！',}",
  [96036] = "{id=96036,Text='呼，总算打退了…不知道是不是拉比丝，疯兔异变的情况很严重，得先回去通知[c][ffff00]班尼[-][/c]再商量下对策。',}",
  [96037] = "{id=96037,Text='体型巨大的疯兔？那一定是拉比丝~狂暴了？不，不可能的！',Speaker=1060,Emoji=1,}",
  [96038] = "{id=96038,Text='等等！还有个办法，请你帮帮我！这是拉比丝从小戴着的[c][ffff00]蝴蝶结[-][/c]，请拿给拉比丝看，它一定会认出来的！',Speaker=1060,}",
  [96039] = "{id=96039,Text='拉比丝？',Emoji=25,}",
  [96040] = "{id=96040,Text='…',Speaker=1064,Emoji=17,}",
  [96041] = "{id=96041,Text='看这体型应该是拉比丝！来，看看这是什么，班尼让我带给你看的哦~从小戴到大，一定记得起来的吧！',}",
  [96042] = "{id=96042,Text='拉比丝恢复平静了，体型也逐渐变回正常了，主人的信物还真管用呢！',}",
  [96043] = "{id=96043,Text='拉比丝，班尼很担心你，赶紧跟我一起回去吧！',}",
  [96044] = "{id=96044,Text='…',Speaker=1064,Emoji=26,}",
  [96045] = "{id=96045,Text='拉比丝！你终于回来了！我就知道你不会离开我的！爱你，么么哒！',Speaker=1060,Emoji=3,}",
  [96046] = "{id=96046,Text='…',Speaker=1064,Emoji=4,}",
  [96047] = "{id=96047,Text='谢谢你，冒险者！不过你是怎么知道它就是拉比丝的？',Speaker=1060,Emoji=19,}",
  [96048] = "{id=96048,Text='虽然拉比丝不会说话，但却能读懂它的表情。没想到[c][ffff00]表情[-][/c]也可以传达很多心意！',}",
  [96049] = "{id=96049,Text='给它展示蝴蝶结的那一刻，能感受到拉比丝因为害怕而恐惧的内心，它是怕控制不住自己伤害到你才出走的吧…',}",
  [96050] = "{id=96050,Text='我最心爱的拉比丝啊！太感谢你了，[c][ffff00][PlayerName][-][/c]！任务完成得非常出色，我会向乐园团表彰你的智慧！',Speaker=1060,}",
  [96051] = "{id=96051,Text='回来了啊，我已经收到班尼的表扬信了，恭喜你顺利完成考试项目二！',Speaker=1187,}",
  [96052] = "{id=96052,Text='可爱的个性头饰可是冒险者的终极追求之一，作为乐园团的成员可不能错过这份福利！来，送你[c][ffff00]头饰图纸，2选1[-][/c]哦！',Speaker=1054,Option='我还没入团',Emoji=29,}",
  [96053] = "{id=96053,Text='别客气啦，这是乐园团的小小心意，也算考试项目三，合格条件嘛~[c][ffff00]收集齐图纸上所需的材料[-][/c]，然后成功制作出头饰！来，选一张头饰制作图纸吧！',Speaker=1054,Option='{粉嫩的波利,2},{新手蛋壳帽,3}',}",
  [96054] = "{id=96054,Text='这么快就收集齐材料了啊…那就马上去找微笑小姐[c][ffff00]制作头饰[-][/c]吧！',Speaker=1054,}",
  [96055] = "{id=96055,Text='怎么样？头饰很萌吧！好啦，恭喜你顺利完成考试项目三！以后我们会逐步推出好多可爱帅气的个性头饰，敬请期待哦！',Speaker=1054,}",
  [96056] = "{id=96056,Text='考试内容都完成了吗？让我检查下：项目一，陪波伊玩耍枯树枝，完成！项目二，替班尼找回拉比丝，完成！项目三，收集材料制作头饰，完成！',Speaker=1054,}",
  [96057] = "{id=96057,Text='好样的！入团手续准备完毕了，你已经是正式的乐园团的一员了，当你准备好的时候，我会通知你正式加入冒险者公会，转职成为一名真正的冒险者！',Speaker=1054,Option='好哒！',}",
  [96058] = "{id=96058,Text='你是[c][ffff00][PlayerName][-][/c]吧！来得太及时了，最近运送物资路上屡次遭到魔物袭击，商队正忙着盘点货物。能麻烦你帮我们几个忙吗？',Speaker=1044,Option='没问题！',}",
  [96059] = "{id=96059,Text='最近，一向温顺老实的天使波利经常会袭击商队，所以我们想活捉一只看看到底是怎么回事。',Speaker=1044,}",
  [96060] = "{id=96060,Text='听说这方面[c][ffff00]宠物商人卡博尔[-][/c]挺有经验的，能过去帮我们询问下吗？',Speaker=1044,Option='这就出发！',}",
  [96061] = "{id=96061,Text='梦罗克商会委托你来的吧…[c][ffff00]捕捉天使波利[-][/c]啊…嗯…有点难度！',Speaker=1043,}",
  [96062] = "{id=96062,Text='天使波利…暂时没什么确定的方法可以捉到。不过我倒知道，天使波利经常会和一大群波利一起出现。',Speaker=1043,}",
  [96063] = "{id=96063,Text='如果用波利们最喜欢的[c][ffff00]浓缩果汁[-][/c]来吸引它们的话，说不定天使波利也会出现哦！',Speaker=1043,Option='那么简单？',Emoji=11,}",
  [96064] = "{id=96064,Text='可是要做苹果汁需要很多[c][ffff00]新鲜的苹果[-][/c]，[c][ffff00]波利[-][/c]身上就有许多[c][ffff00]新鲜的苹果[-][/c]哦。',Speaker=1043,}",
  [96065] = "{id=96065,Text='唔…很新鲜的苹果嘛，让我尝尝先…不错，很脆、水分也足，酸甜的口感刚刚好！',Speaker=1043,}",
  [96066] = "{id=96066,Text='马上制作[c][ffff00]超浓缩苹果汁[-][/c]！别看大叔我这样，年轻时可得到过“魔物最爱的三星厨师”称号哦！',Speaker=1043,Option='有这称号？',}",
  [96067] = "{id=96067,Text='我说有就有！嘿咻…完成啦！手艺还是那么好！用上这瓶[c][ffff00]超浓缩苹果汁[-][/c]，整个南门区域的波利都会来找你的，哈哈哈哈！快去吧，试试效果！',Speaker=1043,}",
  [96068] = "{id=96068,Text='好美味的苹果汁，那口感，那酸甜…呜哇~可恶的人类！你要干吗？！',Speaker=1055,Option='不会飞？！',}",
  [96069] = "{id=96069,Text='你看我的身材可以飞吗？！更何况人家只是戴了[c][ffff00]天使发圈[-][/c]而已，又不是天使波利，是不是认错啦！',Speaker=1055,Option='天使波利在哪？',}",
  [96070] = "{id=96070,Text='才不会告诉你~哼！你干嘛老盯着我头上的天使发圈看？看得人家怕怕的…',Speaker=1055,Option='借我戴戴？',}",
  [96071] = "{id=96071,Text='走开，不要以为胖子好欺负！苹果汁还是很美味的~再见啦，冒险者～',Speaker=1055,}",
  [96072] = "{id=96072,Text='唉~捕捉天使波利果然不是件容易的事。我们得再好好计划下。不管如何，还是要谢谢你了！',Speaker=1044,Option='别客气！',}",
  [96073] = "{id=96073,Text='虽然护送比较枯燥，但你还不知道吧，这次的货物是只特殊的魔物！',Speaker=1185,Option='护送魔物？',}",
  [96074] = "{id=96074,Text='是的！现在全国上下各个组织和公会都在研究魔物异变的原因，寻找让他们恢复正常的办法，我们[c][ffff00]梦罗克商会[-][/c]也不例外。',Speaker=1185,Emoji=28,}",
  [96075] = "{id=96075,Text='别小看这个小东西，它身上散发着一种奇特的粉尘，时不时还会吸引其他魔物呢！',Speaker=1185,}",
  [96076] = "{id=96076,Text='这只魔物需要尽快送给[c][ffff00]宠物商人卡博尔[-][/c]进行更深入的研究…路上小心！',Speaker=1185,Option='马上出发！',}",
  [96077] = "{id=96077,Text='有什么东西过来了！',Emoji=19,}",
  [96078] = "{id=96078,Text='好像还有魔物！',Emoji=1,}",
  [96079] = "{id=96079,Text='总算送到了，接下来一段时间我会对它们进行检查和调研，应该就能了解这只魔物身上奇怪的现象了',Speaker=1043,}",
  [96080] = "{id=96080,Text='魔物最近异变比较频繁，我得好好研究一番，暂时请大家不要饲养魔物！',Speaker=1043,}",
  [96081] = "{id=96081,Text='回来了啊！护送完成得很出色嘛！相信卡博尔会尽早把宠物相关问题解决的！谢谢你啦！',Speaker=1185,}",
  [96082] = "{id=96082,Text='终于有人来帮忙了，太好了！我这边还要盘点商队的货物，实在走不开。',Speaker=1186,}",
  [96083] = "{id=96083,Text='是这样的，[c][ffff00]商队护卫比尔[-][/c]之前被派到跨海大桥附近采集些材料，到现在还没回来，能帮我去看看怎么回事吗？',Speaker=1186,Option='我这就去！',}",
  [96084] = "{id=96084,Text='很抱歉让巴德操心了，你来得正好，我女儿第一次从梦罗克随我到这，一路风景太美…',Speaker=1053,}",
  [96085] = "{id=96085,Text='真的想多陪陪女儿，平时都不在她身边…但我又有任务在身，你能帮我从绿棉虫身上收集一些棉毛吗？',Speaker=1053,Option='没问题！',}",
  [96086] = "{id=96086,Text='太感谢你了！这座跨海大桥依旧那么美，想当年我和孩子她妈在这还合过影…我想为我女儿拍一张照片作为留念~',Speaker=1053,Option='好哒！',}",
  [96087] = "{id=96087,Text='我从小生活在沙漠之都，第一次看到那么美的景色…',Speaker=2139,Emoji=2,}",
  [96088] = "{id=96088,Text='是吗？她也喜欢这里吗，替我转告巴德，我带女儿再转一会就回来~',Speaker=1053,}",
  [96089] = "{id=96089,Text='谢谢你了，比尔没事就好。商队常年在外奔波，确实挺不容易的，和家人聚少离多，让他们父女再好好逛逛吧。',Speaker=1186,Emoji=6,}",
  [96090] = "{id=96090,Text='谢谢！帮了我们几个那么多忙，这是感谢信，请替我转交给维琪，我一定要表彰你，勇敢的冒险者…',Speaker=1044,Option='别客气！',}",
  [96091] = "{id=96091,Text='我这有两只来自商队的[c][ffff00]坐骑[-][/c]，你可以选一只骑乘赶路，希望没有耽搁你太久。',Speaker=1044,}",
  [96092] = "{id=96092,Text='它们就在边上，一只叫[c][ffff00]呆呆[-][/c]，一只叫[c][ffff00]萌萌[-][/c]，你[c][ffff00]选一个[-][/c]用来赶路吧。',Speaker=1044,Option='{选择呆呆,100},{选择萌萌,101}',}",
  [96093] = "{id=96093,Text='噢？商队的感谢信，你可真是厉害，快去交给维琪教官吧！',Speaker=1050,Emoji=19,}",
  [96094] = "{id=96094,Text='赛尼亚，[c][ffff00][PlayerName][-][/c]前面帮助了不少人呢。解决各种事件、快乐地成长为冒险家，正是我们乐园团成员的使命！',Speaker=1054,}",
  [96095] = "{id=96095,Text='[c][ffff00][PlayerName][-][/c]、赛尼亚，恭喜你们[c][ffff00]通过所有考试项目[-][/c]，手续都已办妥。从现在起你们已经是乐园团的正式团员了！',Speaker=1054,Option='太棒啦！',Emoji=20,}",
  [96096] = "{id=96096,Text='太好了，我已经迫不及待了呢！',Speaker=1050,Emoji=9,}",
  [96097] = "{id=96097,Text='赶快启程吧，我已经把你们推荐到转职大厅了。赶快去[c][ffff00]普隆德拉[-][/c]进行[c][ffff00]转职[-][/c]吧！',Speaker=1054,Emoji=21,}",
  [96098] = "{id=96098,Text='伟大剑士伊格尼建·赛尼亚闪亮登场！伟大的冒险旅程即将展开啦！！！',Speaker=1050,Option='加油！！！',Emoji=17,}",
  [96102] = "{id=96102,Text='看来旅行大嘴鸟很喜欢你。',Speaker=1069,Option='骑上大嘴鸟',}",
  [96106] = "{id=96106,Text='奥斯汀会让你了解伊米尔之心的故事。',Speaker=1067,}",
  [96112] = "{id=96112,Voice='Npc/vox_emo_male_gentle_joy_01',Text='无论是人类还是魔物，过量吸收粉尘都会狂暴化，感谢你，勇敢的冒险者。',Speaker=1412,}",
  [96129] = "{id=96129,Voice='Npc/Thanatos_Task_2',Text='欢迎你们来到我的皇宫，你就做我的王后吧。',Speaker=1425,}",
  [96130] = "{id=96130,Voice='Npc/utopiafolks_female_8',Text='我才不要呢！',Speaker=1427,}",
  [96131] = "{id=96131,Voice='Npc/Thanatos_Task_4',Text='希尔斯！~不！！！！',Speaker=1426,}",
  [96132] = "{id=96132,Voice='Npc/Thanatos_Task_5',Text='我要彻底消灭这些魔物！我要彻底消灭这些魔物！我要彻底消灭这些魔物！啊啊啊啊。',Speaker=1426,}",
  [96133] = "{id=96133,Text='之后达纳托斯使用了禁忌的力量和魔王梦罗克在尔迈斯高原上大战十个昼夜，最后用魔法与魔剑将魔王切成7份碎片封印在世界各地。',Speaker=1413,}",
  [96134] = "{id=96134,Text='魔王不甘心失败于是对梦罗克城下了禁咒，自此海上的季风就再也吹不到那里，梦罗克城也就变成了荒漠。',Speaker=1413,}",
  [96135] = "{id=96135,Text='达纳托斯自己的灵魂被魔剑与魔王侵染而变得邪恶。',Speaker=1413,}",
  [96139] = "{id=96139,Text='孩子，也请献出你的力量来拯救这个世界吧。',Speaker=1067,}",
  [96140] = "{id=96140,Text='乐园团的各种设施和便利服务已经都向你们开放了，非常期待你们的表现哦！',Speaker=1054,Emoji=17,}",
  [96141] = "{id=96141,Text='完成得不错嘛，恭喜顺利通过考试项目一！竟然没被波伊坑到，运气真好！',Speaker=1188,Emoji=17,}",
  [96142] = "{id=96142,Text='提升冒险等级需要缴纳[UpAdvLvCost]哦。',Speaker=1024,Option='{我有钱,2},{要钱没有,3}',}",
  [96143] = "{id=96143,Text='您的钱包需要增肥了。',Speaker=1024,}",
  [96144] = "{id=96144,Text='恭喜你冒险家。',Speaker=1024,}",
  [96145] = "{id=96145,Text='没错！冒险者的日常就是在探索世界的同时应对各种突发情况完成各种委托，形式多种多样…赶紧去吧！',Speaker=1188,Emoji=5,}",
  [96146] = "{id=96146,Text='你好~我是 [c][ffff00]音乐精灵[-][/c] [c][ffff00]艾莉儿[-][/c] ，世界第一美少女偶像！为了回馈大家的厚爱，我会用 [c][ffff00]爱的魔法为您治疗[-][/c]哦！在冒险中受到伤害的话，记得来找我呦，我会努力来治愈你的身心！',Speaker=1058,Emoji=2,}",
  [96147] = "{id=96147,Text='迷路了吗？跟着魔法的指引，可以找到你的伙伴…',Speaker=1058,Option='谢谢',Emoji=4,}",
  [96148] = "{id=96148,Text='你来得正好，冒险者！讨伐队急需人手，下水道的情况仍然在恶化！',Speaker=1068,Option='怎么回事？',Emoji=6,}",
  [96149] = "{id=96149,Text='下水道作为城市地下管道的汇集地，常年阴暗潮湿，平时只需定时清理下即可。不过最近生活在下水道的魔物变得很不安分，所以才组织了讨伐队来解决问题以防事态升级。',Speaker=1068,}",
  [96150] = "{id=96150,Text='由于近阶段全国上下魔物事件激增，虽然有志愿者报名，但讨伐队的人手依旧非常紧张。偏偏下水道是首都的地下重要设施，不赶紧把魔物清理掉的话可是会影响居民正常生活的。',Speaker=1068,}",
  [96151] = "{id=96151,Text='你先准备下吧，一会可以找我或边上的[c][ffff00]莫戈沙[-][/c]再了解下，说不定能帮上很多，我们已经忙不过来了…',Speaker=1068,Option='好的！',}",
  [96152] = "{id=96152,Text='不错，干劲十足的样子啊！那就马上开工吧！我刚统计下水道工作人员名单，发现[c][ffff00]修理工彼得[-][/c]还没回站点，不知道是不是过来路上遇见危险了，能帮忙去找下吗？',Speaker=1068,Option='没问题！',}",
  [96153] = "{id=96153,Text='总算有人来了！好多魔物！怎么办！得立刻离开这个鬼地方！',Speaker=1122,Option='别害怕',Emoji=24,}",
  [96154] = "{id=96154,Text='收到反映有很多管道堵塞，结果过来一看，管道并没问题，原来是魔物数量过多在管道里乱窜导致的。不过清理魔物可不在我们修理工的工作范围内…',Speaker=1122,}",
  [96155] = "{id=96155,Text='虽然有些魔物本身就在下水道里栖居，但现在不仅变得体型庞大而且还有狂暴的倾向，真伤脑筋。看！一波[c][ffff00]魔化的盗虫[-][/c]过来了！',Speaker=1122,Option='交给我吧！',}",
  [96156] = "{id=96156,Text='呼！太惊险了！想起来了！给，这是雷根公司新研发的[c][ffff00]诱鼠喷雾[-][/c]，使用后会引诱白鼠过来，清理完应该能暂时缓解下附近管道堵塞的状况。',Speaker=1122,Option='这就开始',}",
  [96157] = "{id=96157,Text='太好了！还想起件事，这是我之前无聊抓到的几只白鼠，本来想带回去当宠物的！现在看来这些小家伙对你们比较有帮助，作为活体样本带给[c][ffff00]拉姆[-][/c]好好研究下，说不定能发现些什么。',Speaker=1122,}",
  [96158] = "{id=96158,Text='见到拉姆替我报声平安。我把附近的管道最后检查一遍就回去…你自己一路小心，带着魔物回去可能会有危险…',Speaker=1122,Option='好哒！',}",
  [96159] = "{id=96159,Text='白鼠的吱吱声引来了同类的攻击…',}",
  [96160] = "{id=96160,Text='白鼠的吱吱声再次引来了同类的攻击…',}",
  [96161] = "{id=96161,Text='彼得没事就好，谢谢你带回这些[c][ffff00]白鼠[-][/c]，一会就送到魔物研究院去检查下，应该会发现一些线索…',Speaker=1121,}",
  [96162] = "{id=96162,Text='哟，太好了！总算来人帮忙了！下水道的魔物数量激增，靠我们这点人手完全不够。能帮忙一起先将清理下[c][ffff00]白鼠[-][/c]吗？',Speaker=1121,Option='没问题！',}",
  [96163] = "{id=96163,Text='呼，似乎数量少了点~悄悄告诉你哦，其实我很害怕小型魔物，尤其是[c][ffff00]白鼠[-][/c]。有次梦见它们在我身上乱爬，最后还蹿出一只[c][ffff00]蓝鼠[-][/c]，一下子就把我吓醒了，还失眠了好几天！',Speaker=1121,}",
  [96164] = "{id=96164,Text='这样下去可不是办法…如果能采集一些魔物身上的样本进行研究，或许就能查出原因了，要不就从白鼠开始！',Speaker=1121,}",
  [96165] = "{id=96165,Text='这些[c][ffff00]白鼠[-][/c]可能带有病毒！我需要采样一些它们的[c][ffff00]牙齿[-][/c]带回去做研究~我在这继续统计下水道的环境变化，你能帮我这个忙吗？',Speaker=1121,Option='包在我身上！',}",
  [96166] = "{id=96166,Text='谢谢你的帮助！果然有点异常，得好好研究下找找原因。拉姆好像有事找你，赶紧去看看吧~',Speaker=1121,Option='好哒！',Emoji=6,}",
  [96184] = "{id=96184,Text='有了活体样本白鼠和它的牙齿标本，相信魔物研究院那边很快就会有调查结果了。',Speaker=1068,}",
  [96185] = "{id=96185,Text='对了，之前修理工波兹在咕哝着什么黄金的事，现在人也没影了，能麻烦你帮忙找下吗？',Speaker=1068,Option='没问题！',Emoji=4,}",
  [96186] = "{id=96186,Text='啊~可恶的盗虫！不要过来…冒险者，你来得太及时了，赶紧帮我消灭一些[c][ffff00]盗虫[-][/c]吧！',Speaker=1123,Option='交给我吧！',Emoji=1,}",
  [96187] = "{id=96187,Text='看在你帮忙的份上，告诉你个好事！我最近发现盗虫非常喜欢聚集在这，路过留心观察了附近，竟然发现管道里有金灿灿的亮光，估计是金块，和拉姆说了但他竟然不信！',Speaker=1123,}",
  [96188] = "{id=96188,Text='哈哈哈！看到那团亮光没，好大的金块！我[c][ffff00]波兹[-][/c]的好日子总算要来了！咦？好像卡住了。帮我把好兄弟彼得叫来帮忙吧，完事后我们三个人平分！',Speaker=1123,Option='我这就去！',Emoji=17,}",
  [96189] = "{id=96189,Text='哇哦，发现金块了！竟然有这样的好事，[c][ffff00]波兹[-][/c]的运气可真好啊！赶紧过去看看！',Speaker=1122,Emoji=13,}",
  [96190] = "{id=96190,Text='你们总算来啦！我刚看了，金块在管道里面卡住了一部分…得找工具疏通下，然后把它搬出来！前面不远处有维修备用的铲子，马上过去拿吧！',Speaker=1123,}",
  [96191] = "{id=96191,Text='一人一把！很好，赶紧回去挖金块！',Speaker=1123,}",
  [96192] = "{id=96192,Text='开始吧！太激动人心了！！快快快！！！',Speaker=1123,Option='加油！',Emoji=27,}",
  [96193] = "{id=96193,Text='哇！这金灿灿的光太让人陶醉了！',Speaker=1123,Emoji=13,}",
  [96194] = "{id=96194,Text='哈哈哈！快出来了，继续努力挖！',Speaker=1122,}",
  [96195] = "{id=96195,Text='等一下！有问题啊！！怎么金块看起来有点像巨大的昆虫后腿啊！！！莫非…',Speaker=1122,Emoji=19,}",
  [96196] = "{id=96196,Text='天哪！不是金块！！是传说中的[c][ffff00]黄金虫[-][/c]！！！',Speaker=1123,Emoji=1,}",
  [96197] = "{id=96197,Text='怎么会这样！赶紧逃啊！我们得马上去找拉姆报告下，好端端的下水道怎么会有黄金虫啊！',Speaker=1123,Option='我来带路！',Emoji=18,}",
  [96198] = "{id=96198,Text='竟然连黄金虫都出现了，看来事态有点严重，我马上和骑士团反映下情况。你们几个没事就好。',Speaker=1068,}",
  [96199] = "{id=96199,Text='呜呜呜…我的金子啊…',Speaker=1123,}",
  [96200] = "{id=96200,Text='好了啦，波兹，能捡回一条命已经不错了。看来还是勤劳工作靠谱点，哈哈！',Speaker=1122,Emoji=25,}",
  [96201] = "{id=96201,Text='[c][ffff00][PlayerName][-][/c]，你的同伴赛尼亚也来下水道支援了。不过作为新手女剑士，她一个人行动，我还是蛮担心的。要不你去找她看看，毕竟黄金虫都出现了，有点危险…',Speaker=1068,Option='我这就去！',}",
  [96202] = "{id=96202,Text='喂~喂~喂，[c][ffff00][PlayerName][-][/c]，有什么好担心的？看看清楚，我可是一个潜力不凡的剑士啊！',Speaker=1050,Emoji=17,}",
  [96203] = "{id=96203,Text='说正事，别楞在那里了，我接到任务来确认摄影师里奥的安全并把他带回站点。但我在来的路上撞见一只巨大魔菇，在那边扭啊扭的，把路都挡住了。',Speaker=1050,}",
  [96204] = "{id=96204,Text='我和里奥还有点事要商量。帮我个忙，去把这碍事的扭扭魔菇赶走。看它样子应该很厉害，不过没关系，你可以组上其他冒险者一起战斗，人多力量大。',Speaker=1050,Option='出发！',}",
  [96205] = "{id=96205,Text='哟，不错嘛。我和里奥也谈得差不多了，总算掌握了一些自拍角度和采光取景的诀窍，以后拍出来一定会更萌萌哒…',Speaker=1050,Emoji=29,}",
  [96206] = "{id=96206,Text='里奥好像有事找你，赶紧去问下吧。我得先试试刚学的自拍技巧~',Speaker=1050,}",
  [96207] = "{id=96207,Text='你们不用太担心我的安全。魔物异常，正好是摄影的绝佳机会啊！要知道，平时还有专职的战地摄影师给《国家地理》提供优质作品呢！这可是我努力的方向啊！',Speaker=1124,}",
  [96208] = "{id=96208,Text='不过一路上发现很多异变的魔菇，一个个都发疯似的在那里扭摆，赶都赶不走，害我很多地方都没取好景。我正好要检查路上的随拍照，你去帮我清理下附近的魔菇吧…',Speaker=1124,Option='没问题！',}",
  [96209] = "{id=96209,Text='太好了！一会回去路上又能拍摄很多照片了！虽然下水道比较阴暗，但对我的取景拍照技术来说应该不成问题！',Speaker=1124,}",
  [96210] = "{id=96210,Text='给你们看张照片！刚开始的时候我也吓一跳呢！简直不敢相信自己的眼睛，这下应该可以上《国家地理》头条了！',Speaker=1124,Option='接过照片',Emoji=17,}",
  [96211] = "{id=96211,Text='这是…人鱼？！',Speaker=1050,}",
  [96212] = "{id=96212,Text='很罕见吧！在下水道里竟然有两条人鱼，大的那条好像挺不好惹，所以我只在远处偷拍了几张照片，没敢靠近…',Speaker=1124,Emoji=5,}",
  [96213] = "{id=96213,Text='虽然很不甘心没拍到近景，但今天收获够多的，我理理东西先回去了。人鱼就在前面不远处，你们过去的话注意安全！',Speaker=1124,Option='好哒！',}",
  [96214] = "{id=96214,Text='吼！吼！！！离我们远点，不要过来，人类！',Speaker=1126,Emoji=1,}",
  [96215] = "{id=96215,Text='别害怕，我们是冒险者不是坏人！你们需要帮助吗？',Speaker=1050,}",
  [96216] = "{id=96216,Text='别装了，就是你们人类惹的祸！人类擅自将粗长的管道接通了大海，我们才会被卷入这肮脏不堪的下水道！海神会惩罚你们的！',Speaker=1126,Emoji=12,}",
  [96217] = "{id=96217,Text='呀！小人鱼好像受了伤，得马上治疗！之前听说讨伐队自备了些曼特疗伤药，不过被下水道的魔菇偷走了…',Speaker=1050,}",
  [96218] = "{id=96218,Text='走开！我宁死也不要人类治疗！水源的污染已经害死了我的家人和我的同胞！我们和人类势不两立！',Speaker=1126,}",
  [96219] = "{id=96219,Text='好吧，你可以不接受…但你的孩子也受了伤，她的生命力可没那么顽强！你作为母亲，得为孩子多考虑吧！',Speaker=1050,}",
  [96220] = "{id=96220,Text='(转眼看着小小的卢西娅)',Speaker=1126,}",
  [96221] = "{id=96221,Text='…[c][ffff00]卢西娅[-][/c]，我最心爱的孩子！好吧！但如果你们想加害于她，我一定拼死让你们付出代价的！',Speaker=1126,Emoji=19,}",
  [96222] = "{id=96222,Text='[c][ffff00][PlayerName][-][/c]，我在这守着人鱼母女，你去教训下魔菇把[c][ffff00]曼特疗伤药[-][/c]找回来吧！',Speaker=1050,Option='好哒！',}",
  [96223] = "{id=96223,Text='对卢西娅使用曼特疗伤药。',Speaker=1050,}",
  [96224] = "{id=96224,Text='好可爱的小人鱼，那么小还不太会说话。别担心，我们会治愈好你，然后送你们回海洋，一切都会好起来的…',Speaker=1050,}",
  [96225] = "{id=96225,Text='卢西娅…好像稍微好点了…别指望我会感谢你们！因为这一切都是你们人类造成的！',Speaker=1126,Emoji=14,}",
  [96226] = "{id=96226,Text='[c][ffff00][PlayerName][-][/c]，我在这照顾人鱼，有件事要拜托你。附近的盗虫很不安分，老是来骚扰我们，能帮忙清理下吗？',Speaker=1050,Option='没问题！',}",
  [96227] = "{id=96227,Text='这回可不会再被盗虫攻击了吧…',Speaker=1050,Emoji=25,}",
  [96228] = "{id=96228,Text='总算安全了，还好有我们在。接下来得想想办法怎么送人鱼回家…',Speaker=1050,}",
  [96229] = "{id=96229,Text='我们现在就送你们回去，在下水道越久对你们伤害越大…而且万一你们被讨伐队的人看到，可就真的麻烦了…',Speaker=1050,}",
  [96230] = "{id=96230,Text='[c][ffff00][PlayerName][-][/c]，你先去前面调查一下，找到前往大海的通道…',Speaker=1050,}",
  [96231] = "{id=96231,Text='查看管道入口。',Speaker=1050,}",
  [96232] = "{id=96232,Text='冒险者，你来通往海底洞穴的入口干吗？最近常有危险的魔物出现，多注意安全！',Speaker=1129,Option='迷路而已',}",
  [96233] = "{id=96233,Text='不过请放心，讨伐队已经有线索了，队员们已经寻着踪迹追过去了…',Speaker=1129,Option='得赶紧回去',}",
  [96234] = "{id=96234,Text='冒险者，靠后退！这只狂暴的海底魔物非常危险！让我们来对付它！',Speaker=1128,}",
  [96235] = "{id=96235,Text='可恶的人类！你们难道还没有认识到自己的罪行吗？！',Speaker=1126,Emoji=12,}",
  [96236] = "{id=96236,Text='冒险者，赶快离开那里！',Speaker=1128,Emoji=1,}",
  [96237] = "{id=96237,Text='卢西沙发出了一声极其刺耳的尖叫声…悲鸣而壮烈…',}",
  [96238] = "{id=96238,Text='“啊！怎么回事，头好晕啊！”',Speaker=1128,}",
  [96239] = "{id=96239,Text='快，带着卢西娅先走，让她活下去！',Speaker=1126,}",
  [96240] = "{id=96240,Text='什么意思？！[c][ffff00]卢西沙[-][/c]，那你怎么办呢？！',Speaker=1050,}",
  [96241] = "{id=96241,Text='我的伤太重了，刚才用尽力气吟唱后，体内好像有些异常的东西在滋生！快走啊！等卢西娅长大后告诉她，她的母亲很爱她！',Speaker=1126,Emoji=24,}",
  [96242] = "{id=96242,Text='不行！要走一起走啊！',Speaker=1050,}",
  [96243] = "{id=96243,Text='走吧！赛尼亚！卫兵快要恢复意识了！再不走，连卢西娅都有危险了！',}",
  [96244] = "{id=96244,Text='糟糕！还有卫兵，实在没办法了。我来吸引他们注意力，你找机会打晕他们吧！',Speaker=1050,Option='交给我吧！',}",
  [96245] = "{id=96245,Text='等一下，危险！',Speaker=1050,Emoji=1,}",
  [96246] = "{id=96246,Text='可恶！偏偏在这个时候…',Speaker=1050,}",
  [96247] = "{id=96247,Text='[c][ffff00][PlayerName][-][/c]，你带着小人鱼卢西娅先走，我来把它们引开！',Speaker=1050,Option='赛尼亚！！',Emoji=14,}",
  [96248] = "{id=96248,Text='卢西娅，我们只能送到你这里了，你一定要好好活下去！后会有期！',Emoji=24,}",
  [96249] = "{id=96249,Text='安全送卢西娅回到海底了，得赶快回去看看卢西沙的状况…还有赛尼亚，不知道安全回去了吗…',}",
  [96250] = "{id=96250,Text='冒险者，你没事吧。小人鱼消失了，大人鱼开始彻底狂暴了！小心点！',Speaker=1128,}",
  [96251] = "{id=96251,Text='消灭我！请你们快消灭我！！我体内的黑暗物质在膨胀，我快控制不住自己了！记得保护好卢西娅…啊！！！脑袋好痛！吼！！！',Speaker=1126,}",
  [96252] = "{id=96252,Text='危险！冒险者，这只人鱼完全暴走了！看来是异变狂暴了！不过还得赶快击败它，不然它会承受更痛苦的伤害。',Speaker=1128,}",
  [96253] = "{id=96253,Text='对不起，[c][ffff00]卢西沙[-][/c]！我不得不…真的对不起…',Emoji=19,}",
  [96254] = "{id=96254,Text='赛尼亚！太好了！你没事吧！',}",
  [96255] = "{id=96255,Text='我可是堂堂剑士赛尼亚，当然没事！说来也怪，黄金虫并没有攻击我，只是把我引到了下水道深处，似乎想告诉我些什么…',Speaker=1050,Option='没事就好',}",
  [96256] = "{id=96256,Text='冒险者，感谢你们的帮助！请先回普隆德拉，找到集英馆的艾里克向他说明下水道的情况。',Speaker=1128,}",
  [96257] = "{id=96257,Text='我们继续清理下水道了。最近全国很多地方的魔物都变得异常狂暴，你们一路小心！',Speaker=1128,Option='再见',}",
  [96258] = "{id=96258,Text='[c][ffff00][PlayerName][-][/c]，下水道的任务完成的非常好！普隆德拉终于有了一名像样的英雄，人民会感激你的！',Speaker=1118,}",
  [96259] = "{id=96259,Text='你似乎不太高兴，我不清楚在下水道发生了什么事情，但是冒险者，这都是你成长的经历。',Speaker=1118,}",
  [96260] = "{id=96260,Text='这是你成为冒险家路上，第一件值得记录并传颂的事迹，请把它好好地记录在你的冒险手册上吧！',Speaker=1118,}",
  [96261] = "{id=96261,Text='承接冒险者手册引导任务。',Speaker=1118,}",
  [96262] = "{id=96262,Text='这里就是下水道吗？…是艾里克把我送来的！',}",
  [96363] = "{id=96363,Text='圣光照耀着你，来选择一把喜欢的武器吧！',Speaker=1307,Option='{锤,2},{法杖,3}',}",
  [96364] = "{id=96364,Text='只要我有，只要你要，我都愿意给你，不过得拿乐园币来换哦！',Speaker=1262,}",
  [96365] = "{id=96365,Text='魔王的力量仍旧残存于普勒花园里。',Speaker=1398,}",
  [96371] = "{id=96371,Text='只有牵着心爱之人的手，才可以让艾卡拉奇的植物生长。',Speaker=1398,}",
  [96381] = "{id=96381,Emoji=4,}",
  [96382] = "{id=96382,Text='去吧，用你们的爱意来唤醒那些植物吧！',Speaker=1398,}",
  [96432] = "{id=96432,Text='欢迎光临！',Speaker=2140,}",
  [96433] = "{id=96433,Text='欢迎光临！',Speaker=2141,}",
  [96434] = "{id=96434,Text='欢迎光临！',Speaker=2142,}",
  [96435] = "{id=96435,Text='欢迎光临！',Speaker=2143,}",
  [96438] = "{id=96438,Text='欢迎光临！',Speaker=2146,}",
  [96439] = "{id=96439,Text='欢迎光临！',Speaker=2147,}",
  [96440] = "{id=96440,Text='欢迎光临！',Speaker=2148,}",
  [96441] = "{id=96441,Text='欢迎光临！',Speaker=2149,}",
  [96442] = "{id=96442,Text='欢迎光临！',Speaker=2150,}",
  [96443] = "{id=96443,Text='欢迎光临！',Speaker=2151,}",
  [96450] = "{id=96450,Text='深海中居然有着如此巨大的神殿…他的主人到底是谁呢？',Speaker=2503,}",
  [96454] = "{id=96454,Text='我们不想再失去任何一个伙伴，请保证自己的安全，冒险者。',Speaker=1195,}",
  [96455] = "{id=96455,Text='魔物的狂暴已经深入到了普隆德拉的下水道二层，请尽快前往那里，避免皇城深陷危机。',Speaker=1016,}",
  [96456] = "{id=96456,Text='虽然北部森林容易让人迷路，但我们也绝不允许那里滋生太多的狂暴魔物。',Speaker=1016,}",
  [96457] = "{id=96457,Text='幽灵船的浮现让依斯鲁得的居民身陷危机，请尽快出发。',Speaker=1016,}",
  [96458] = "{id=96458,Text='海底洞穴的建筑群也是探险队常去的地方，请清理那里的魔物保证安全。',Speaker=1016,}",
  [96459] = "{id=96459,Text='传说中女神居住的地方，请帮助吉芬的法师抗击山脉的魔物。',Speaker=1016,}",
  [96460] = "{id=96460,Text='蚂蚁洞穴的危机深深的影响着梦罗克城的安全，请尽快抗击洞穴内的魔物。',Speaker=1016,}",
  [96461] = "{id=96461,Text='斐扬森林的魔物骚乱一直没停止过，这一次威胁到了斐扬城的安全了，请去削减那里魔物的数量。',Speaker=1016,}",
  [96462] = "{id=96462,Text='金字塔内封印者魔王的一部分，请肃清金字塔内狂暴的魔物，防止封印的进一步削弱。',Speaker=1016,}",
  [96463] = "{id=96463,Text='可怕的斐扬洞穴，至今我忘记不了那里阴森的气息，请阻止那里狂暴的魔物。',Speaker=1016,}",
  [96464] = "{id=96464,Text='龙区已经非常接近克雷斯特汉姆古城，请立刻出发前往那里镇压魔物。',Speaker=1016,}",
  [96465] = "{id=96465,Text='古城的魔物骚乱只是噩梦的开始，无乱如何请镇压那里的狂暴魔物。',Speaker=1016,}",
  [96466] = "{id=96466,Text='古城修道院的魔物非常的强悍，前往镇压的时候请一定要小心。',Speaker=1016,}",
  [96467] = "{id=96467,Text='就连最强悍的普隆德拉骑士团在镇压古城骑士团时也损失惨重，冒险者，一切都拜托你了。',Speaker=1016,}",
  [96489] = "{id=96489,Text='看上去很有精神啊，年轻人。',Speaker=1553,}",
  [96490] = "{id=96490,Text='巴风特一定会在金字塔的魔王封印处出现，普隆德拉的支援军已经在那里埋伏好了。',Speaker=1553,}",
  [96491] = "{id=96491,Text='只是魔物的狂暴和不断出现的裂隙让梦罗克城深陷危机。',Speaker=1553,}",
  [96492] = "{id=96492,Text='这次不会再让巴风特轻易得逞。',Speaker=1553,}",
  [96493] = "{id=96493,Text='赌上大陆卫队的荣耀，也必须要把金字塔的封印守下来。',Speaker=1553,}",
  [96494] = "{id=96494,Text='因为“魔王的最终封印”就在我们这座梦罗克城之下，大陆卫队已经派出了分队在城外的入口处加强防御。',Speaker=1553,}",
  [96495] = "{id=96495,Text='替我转告他们，巴风特就快现身了，请加强警惕，尤其是那些被即将苏醒的魔王召唤而来的异世界魔物。',Speaker=1553,}",
  [96509] = "{id=96509,Text='谢谢，我感觉好多了。',Speaker=1568,}",
  [96590] = "{id=96590,Text='我给你最后的忠告，[c][ffff00]请谨慎使用[-][/c]，一不小心你的小命都可能会丢。',Speaker=1552,}",
  [96610] = "{id=96610,Text='哈哈，想打开封印之间？没那么简单！',Speaker=1307,}",
  [96614] = "{id=96614,Text='一股惊人的怨念从祭坛上的蛇女之眼中散发而去……',Speaker=1307,}",
  [96615] = "{id=96615,Text='是谁，在伤害我的子民！',Speaker=1307,}",
  [96616] = "{id=96616,Text='你来得正好，现在[c][ffff00]封印之间[-][/c]的情况怎么样？',Speaker=1221,}",
  [96617] = "{id=96617,Text='封印之间已经开启，我现在进去阻拦巴风特，你们要在做好准备，不要让巴风特跑了。',}",
  [96618] = "{id=96618,Text='包在我们身上！',Speaker=1221,}",
  [96619] = "{id=96619,Text='愚蠢！就凭你也想阻止我？',Speaker=2202,}",
  [96620] = "{id=96620,Text='实力不错，不过想打败我还远远不够！梦罗克城的封印之间才是封印梦罗克本体的地方，被我耍着玩的滋味不好受吧？',Speaker=2202,Option='什么？',}",
  [96621] = "{id=96621,Text='对！就是这个表情！真是让我心情舒畅啊，唔….看来梦罗克城那里差不多了。蝼蚁，就让我的分身陪你玩玩吧，哈哈哈哈……',Speaker=2202,}",
  [96633] = "{id=96633,Text='今天也是充满诗意的一天呢。今天你想听谁的故事呢？',Speaker=1582,}",
  [96638] = "{id=96638,Text='今天击败了很多魔物呢，明天再来吧…',Speaker=1195,}",
  [96639] = "{id=96639,Text='你需要先提升你的等级…',Speaker=1195,}",
  [96668] = "{id=96668,Text='哦，是要去柏伊亚岚吧，那你可找对人了！虽然这小岛不大，不过却有通向海底洞穴的入口。我平时就靠运输货物来回往返于依斯鲁得和柏伊亚岚。',Speaker=1098,}",
  [96669] = "{id=96669,Text='据说柏伊亚岚之前被海盗长期占据，在海底埋了不少宝藏。好多冒险者都过去探索想发一笔横财，不过还没人成功，海底风景倒是很迷人~',Speaker=1098,Emoji=13,}",
  [97000] = "{id=97000,Text='异世界魔物不断的受到魔王的召唤涌入我们的世界。',Speaker=2211,}",
  [97001] = "{id=97001,Text='如果魔王真的就此苏醒，这个世界还会有英雄出现吗！？',Speaker=2211,}",
  [97002] = "{id=97002,Text='冒险者，这里交给我，剩下的就拜托给你了！',Speaker=2211,Option='交给我吧！',}",
  [97003] = "{id=97003,Text='可恶，城墙都坍塌了，只能从另一个入口走了！',}",
  [97004] = "{id=97004,Text='异世界的魔物撕开时空裂缝…',Speaker=1307,}",
  [97005] = "{id=97005,Text='冒险者！！梦罗克城被突破了，我们决定与邪恶殊死一搏！',Speaker=2212,}",
  [97006] = "{id=97006,Text='羊角恶魔就在城下的封印之间，这里封印着梦罗克的本体，当年为了以防万一，在城内有一个入口，快去阻止巴风特！',Speaker=2212,}",
  [97007] = "{id=97007,Text='我相信，每当危机降临，一定会有英雄出现！',Speaker=2212,}",
  [97008] = "{id=97008,Text='我们的部队撑不了多久了，只要阻止巴风特我们就有办法用更强大的封印将魔王封印在无尽的黑暗之中！',Speaker=2213,Option='新的封印？',}",
  [97009] = "{id=97009,Text='是的，远古的封印已经被巴风特轻易的破坏了，魔法师们早已经准备好了更强大的封印法术，而这一切的关键只在于击败巴风特！',Speaker=2213,}",
  [97010] = "{id=97010,Text='快走吧冒险者，这里交给我们，有更重要的事情等待着你去做。',Speaker=2213,}",
  [97011] = "{id=97011,Text='年轻人，我在你身上感受到了一股不一样的气息！',Speaker=2214,Option='怎么了？',}",
  [97012] = "{id=97012,Text='我之前就有注意到了，我对它很熟悉，那块冒着虹色光芒的碎片。',Speaker=2214,}",
  [97013] = "{id=97013,Text='伊米尔之心碎片，如果现在不是特殊时刻我一定会收走它，它会给你力量，同时也会摧毁你，年轻人，不到万不得已千万不要使用它！',Speaker=2214,}",
  [97014] = "{id=97014,Text='以你的身躯是无法承受这股巨大力量的吞噬的！',Speaker=2214,Option='我会的',}",
  [97015] = "{id=97015,Text='可恶，源源不断！',}",
  [97016] = "{id=97016,Text='别担心，你并不是一个人孤军奋战！',Speaker=2214,}",
  [97017] = "{id=97017,Text='冒险女王及时赶到！',Speaker=2215,}",
  [97018] = "{id=97018,Text='快走吧，这里交给我了！',Speaker=2215,}",
  [97019] = "{id=97019,Text='赛尼亚！！…',}",
  [97020] = "{id=97020,Text='商会从未有过如此大的损伤，朋友们一个接一个倒在了我的面前，我们将誓死保卫梦罗克！',Speaker=2216,}",
  [97021] = "{id=97021,Text='哈沃德给予你的武器附魔曾经帮助过这个世界上最强大的战士击败过恶魔，而如今他再次将附魔给予世人，年轻人，我们相信你能成为拯救我们的英雄。',Speaker=2216,}",
  [97022] = "{id=97022,Text='不过我想我得给你个忠告，在使用附魔时刻不能过度，当力量达到临界点时，人类便无法驾驭住手中的武器，除非是超越人类的存在，切记，最后祝你好运！',Speaker=2216,}",
  [97023] = "{id=97023,Text='这强大的附魔果然不能长时间使用，我的手都有些麻痹了…',}",
  [97024] = "{id=97024,Text='我不能在这里就倒下，再用一次！',}",
  [97025] = "{id=97025,Text='这么快就筋疲力尽了？',Speaker=1393,}",
  [97026] = "{id=97026,Text='上次见到你的时候你可没这么狼狈哦…',Speaker=1393,}",
  [97027] = "{id=97027,Text='难道是？',}",
  [97028] = "{id=97028,Text='怎么了？嫌我们来晚了吗？',Speaker=2218,}",
  [97029] = "{id=97029,Text='你做的非常好，冒险者，平息了吉芬地下的骚乱后我们就赶来了…',Speaker=2217,}",
  [97030] = "{id=97030,Text='去吧孩子，这里就交给我们了…',Speaker=2217,}",
  [97031] = "{id=97031,Text='传送门已经准备好了，不过看来我们有麻烦了…',Speaker=2219,}",
  [97032] = "{id=97032,Text='我来击退他们！',}",
  [97033] = "{id=97033,Text='慎用这些力量，不过看来“麻烦”还不止这些…',Speaker=2219,}",
  [97034] = "{id=97034,Text='剩下的交给我们把，快进入传送门！',Speaker=2219,}",
  [97035] = "{id=97035,Text='这些魔物异常强大，我来帮助你们！',}",
  [97036] = "{id=97036,Text='哈哈哈哈，你就留些力气把，巴风特就交给你了！',Speaker=2219,}",
  [97037] = "{id=97037,Text='可是这些魔物太强大了…',}",
  [97038] = "{id=97038,Text='你怎么总是这么磨磨蹭蹭的？',Speaker=1393,}",
  [97039] = "{id=97039,Text='这声音…难道是？',}",
  [97040] = "{id=97040,Text='哼，多管闲事…',Speaker=2219,}",
  [97041] = "{id=97041,Text='我可没有说需要你的帮助。',Speaker=2219,}",
  [97042] = "{id=97042,Text='嘿嘿，我可没说我是来救你的，不过你公会的那些孩子可没你强啊…',Speaker=2223,}",
  [97043] = "{id=97043,Text='别愣在那里了~赶快进入封印之间！',Speaker=2223,}",
  [97044] = "{id=97044,Text='这一次，世界由我来守护！！',}",
  [97045] = "{id=97045,Text='看来只能放手一搏了！',}",
  [97046] = "{id=97046,Text='你终于来了，巴风特突然出现，对这里进行了闪电般的突袭！',Speaker=2249,}",
  [97047] = "{id=97047,Text='普隆德拉的援军赶到时，我们已经失守了',Speaker=2249,Option='我去解决它',}",
  [97048] = "{id=97048,Text='看起来我和海陆曼遇到了些麻烦…',Speaker=2250,}",
  [97049] = "{id=97049,Text='冒险者，巴风特张开了结界，我们无法靠近…',Speaker=2251,}",
  [97050] = "{id=97050,Text='而眼前的敌人也比想象中的强大的多。',Speaker=2251,}",
  [97051] = "{id=97051,Text='他们身上散发着异常强大的力量！',Speaker=2250,}",
  [97052] = "{id=97052,Text='是伊米尔之心的碎片使得他们如此狂暴！',Speaker=2251,}",
  [97053] = "{id=97053,Text='巴风特就在眼前了，破坏结界，阻止他吧，冒险者！',Speaker=2251,}",
  [97054] = "{id=97054,Text='强大的结界没有任何异样',Speaker=1307,}",
  [97055] = "{id=97055,Text='可恶的巴风特，只能使用武器附魔了！',}",
  [97056] = "{id=97056,Text='没办法了！只好用到“它”了',}",
  [97057] = "{id=97057,Text='有时候孤军奋战可不是一个好的选择哟～',Speaker=2257,}",
  [97058] = "{id=97058,Text='导师们！',}",
  [97059] = "{id=97059,Text='我们接到国王的密令，赶过来给我们的小英雄提供援助。',Speaker=2253,}",
  [97060] = "{id=97060,Text='无名居然不在这里，真让我感到意外～',Speaker=2255,}",
  [97061] = "{id=97061,Text='从你踏入转职大厅的那一刻，我就知道你会成为一个值得依靠的人～',Speaker=2257,}",
  [97062] = "{id=97062,Text='我好久没有外出狩猎了，我也很喜欢收集山羊胡须哦～',Speaker=2256,}",
  [97063] = "{id=97063,Text='你手中是哈沃德的杰作吧，要小心处理这些附魔哦，过量使用后你将无法控制你的武器！',Speaker=2258,}",
  [97064] = "{id=97064,Text='这种结界是古代魔法，巴风特怎么会有如此强大的力量！',Speaker=2254,}",
  [97065] = "{id=97065,Text='现在可不是闲聊的时候，一起来破坏者结界吧',Speaker=2253,}",
  [97066] = "{id=97066,Text='谁在打扰我？！',Speaker=2259,}",
  [97067] = "{id=97067,Text='停止仪式吧，魔王苏醒会毁灭这个世界，包括你',}",
  [97068] = "{id=97068,Text='停止你的愚蠢作为吧，你已经没有胜算了',Speaker=2253,}",
  [97069] = "{id=97069,Text='哈哈哈哈哈哈，你们在和我开玩笑嘛？',Speaker=2259,}",
  [97070] = "{id=97070,Text='碍眼的人类！让你们看看这些巨人碎片的力量！',Speaker=2259,}",
  [97071] = "{id=97071,Text='危险！！',Speaker=2254,}",
  [97072] = "{id=97072,Text='消失吧！',Speaker=2259,}",
  [97073] = "{id=97073,Text='快离开这里，这里快坍塌了！',Speaker=2250,}",
  [97074] = "{id=97074,Text='我来传送大家，[c][ffff00][PlayerName][-][/c]靠近我！',Speaker=2257,}",
  [97075] = "{id=97075,Text='凡人，既然你放弃了最后一次生存的机会，那我就成全你！',Speaker=2259,}",
  [97076] = "{id=97076,Text='恶魔！尝尝人类的厉害吧！',}",
  [97077] = "{id=97077,Text='啧啧啧，好可怜的力量。',Speaker=2259,}",
  [97078] = "{id=97078,Text='你这是自寻死路！',Speaker=2259,}",
  [97079] = "{id=97079,Text='附魔力量使用过度，人类已经无法驾驭自己的武器…',Speaker=1307,}",
  [97080] = "{id=97080,Text='不！！！',}",
  [97081] = "{id=97081,Text='蝼蚁的演出结束了？？',Speaker=2259,}",
  [97082] = "{id=97082,Text='哈哈哈哈哈哈哈哈哈哈，真是可笑！',Speaker=2259,}",
  [97083] = "{id=97083,Text='很可笑是吗？',}",
  [97084] = "{id=97084,Text='今天，在这里，我一定要击败你！恶魔！',Option='拿出碎片',}",
  [97085] = "{id=97085,Text='[c][ffff00]伊米尔之心的碎片[-][/c]？？！！不可能，你居然有碎片！！',Speaker=2259,}",
  [97086] = "{id=97086,Voice='Npc/Baphomet_1',Text='愚蠢的人类，你别忘了！连你所信奉的神都不敢面对巴风特！',Speaker=2259,}",
  [97087] = "{id=97087,Text='这一次，世界由我来守护！',}",
  [97088] = "{id=97088,Text='我感觉有一些困……',}",
  [97089] = "{id=97089,Text='不！！！[c][ffff00][PlayerName][-][/c]，我们来晚了……',Speaker=2260,}",
  [97090] = "{id=97090,Text='古代曾有预言，每当世界陷入危机，这个世界自然会孕育出一位英雄去拯救它。',Speaker=2262,}",
  [97091] = "{id=97091,Text='这位勇敢的冒险者击败了恶魔，他曾为了荣誉之战，也曾为了梦罗克而战！',Speaker=2261,}",
  [97092] = "{id=97092,Text='艾尔克，我想这个结局你已经猜到了，你是来拯救这位冒险者的吗？',Speaker=2262,}",
  [97093] = "{id=97093,Text='没错，女神之泪又被称为生命之泉，原本是用来拯救梦罗克这片沙漠的，而现在它有了更为重要的作用！',Speaker=2261,}",
  [97094] = "{id=97094,Text='而这女神之泪正是这位冒险者为我送来，与其说是我们拯救了冒险者，不如说是他拯救了自己……',Speaker=2261,}",
  [97095] = "{id=97095,Text='太好了！',Speaker=2260,}",
  [97096] = "{id=97096,Text='快醒来吧，我们有很多话想和你说……',Speaker=2261,}",
  [97097] = "{id=97097,Text='为了心中的爱！！！',}",
  [97098] = "{id=97098,Text='骑士的荣耀！',Speaker=2253,}",
  [97099] = "{id=97099,Text='魔法的力量！',Speaker=2254,}",
  [97100] = "{id=97100,Text='万能的神明，请赐予我力量消灭眼前的邪恶之源！',Speaker=2257,}",
  [97101] = "{id=97101,Text='黑暗，永远存在…',Speaker=2255,}",
  [97102] = "{id=97102,Text='灵动的风，展现出你伟大的力量吧！',Speaker=2256,}",
  [97103] = "{id=97103,Text='创造是人类最宝贵的财富……',Speaker=2258,}",
  [97104] = "{id=97104,Text='可能是吧…',}",
  [97105] = "{id=97105,Text='如果可以的话我还想再回到家乡…',}",
  [97106] = "{id=97106,Text='回到普隆德拉城外看着大家的笑容…',}",
  [97107] = "{id=97107,Text='你以为你能驾驭这种力量？！',Speaker=2259,}",
  [97108] = "{id=97108,Text='终于要面对巴风特了！',}",
  [97113] = "{id=97113,Text='斐扬是隐藏在群山之中的山岳之城，与外面世界的隔绝。斐扬依然得以保留它的传统和地方特色，并未受到卢恩·米德加尔特王国的影响。',Speaker=1058,}",
  [100011] = "{id=100011,Text='快去吧！种子干掉就全完了！',Speaker=1355,}",
  [100015] = "{id=100015,Text='小心点，贵客，那些毒液很危险！',Speaker=1353,}",
  [100016] = "{id=100016,Text='不明白吧？这可是我们哥布灵所创造的伟大技术！',Speaker=1353,}",
  [100023] = "{id=100023,Text='一张人体实验的图纸，似乎是置身研究所内。',}",
  [100024] = "{id=100024,Text='桌面上凌乱的摆放着各种可怕的实验方案。',}",
  [100025] = "{id=100025,Text='救...救救我们…我们好痛苦…',Speaker=5721,}",
  [100026] = "{id=100026,Text='情况看来不太妙，继续向前探索看看',}",
  [100027] = "{id=100027,Text='喝了这个，我真的能够变强吗？',Speaker=5724,}",
  [100028] = "{id=100028,Text='是的，你的家人都会为你自豪的。',Speaker=5722,}",
  [100029] = "{id=100029,Text='最重要的是，你自愿作为实验体，我们会给予你丰厚的酬金！',Speaker=5723,}",
  [100030] = "{id=100030,Text='好吧，那我就…',Speaker=5724,}",
  [100031] = "{id=100031,Text='记忆幻影中的男子，将手中试管里的绿色液体一饮而尽。',}",
  [100032] = "{id=100032,Text='我感觉…身体有些热…',Speaker=5724,}",
  [100033] = "{id=100033,Text='咳咳咳...咳咳',Speaker=5724,}",
  [100034] = "{id=100034,Text='男子的脸上露出了狰狞痛苦的表情。',Speaker=5724,}",
  [100035] = "{id=100035,Text='“嘭”的一声，试管掉在了地上砸了一地的碎片。',Speaker=5724,}",
  [100036] = "{id=100036,Text='咳咳咳...我好像…',Speaker=5724,}",
  [100037] = "{id=100037,Text='没...办法...讲...话咳咳咳...呼吸…',Speaker=5724,}",
  [100038] = "{id=100038,Text='看样子我们成功了，哈哈哈哈。',Speaker=5723,}",
  [100039] = "{id=100039,Text='别高兴的太早，该死的它好像又是只不能说话的。',Speaker=5722,}",
  [100040] = "{id=100040,Text='唔…唔！！！',Speaker=5755,}",
  [100041] = "{id=100041,Text='这可是第一个保留人形态的实验体，就给他起名叫索斯吧。',Speaker=5723,}",
  [100042] = "{id=100042,Text='相信那位大人也一定会喜欢他的。',Speaker=5723,}",
  [100043] = "{id=100043,Text='唔啊啊啊啊！！！！',Speaker=5755,}",
  [100044] = "{id=100044,Text='魔物发出了激烈的嘶吼声。',}",
  [100045] = "{id=100045,Text='伴随着索斯的悲鸣，自己的意识似乎也开始飞走',}",
  [100046] = "{id=100046,Text='这时耳边突然传来一阵熟悉的声音。',}",
  [100047] = "{id=100047,Text='[c][ffff00][PlayerName][-][/c]！！快寻找出路，你在实验舱里待太久了！！',Speaker=5754,}",
  [100048] = "{id=100048,Text='是赛尼亚！！',}",
  [100049] = "{id=100049,Text='冒险者！！快出来！！！保持清醒！！寻找出口！',Speaker=5754,}",
  [100050] = "{id=100050,Text='快！！你没有时间了！！保持清醒！！',Speaker=5754,}",
  [100053] = "{id=100053,Text='你连强大和弱小都分不清吗？这样的你可没办法通过我的考验。',Speaker=5063,}",
  [100054] = "{id=100054,Text='你连人类和魔物都分不清吗？这样的你可没办法通过我的考验。',Speaker=5064,}",
  [100055] = "{id=100055,Text='你连红色着装的物体都分不清吗？这样的你可没办法通过我的考验。',Speaker=5065,}",
  [100074] = "{id=100074,Text='在静谧又安宁的夜晚，不知你是否愿意抬起头看看月亮。',Speaker=7824,Option='什么',}",
  [100075] = "{id=100075,Text='或许你曾经听过月神沐恩的故事。',Speaker=7824,}",
  [100076] = "{id=100076,Text='每当人类进入梦乡之时，月神沐恩就会驾驭月亮从天空中划过，在天黑时为人类点亮大地。而如今，月神沐恩已经消失很久了。',Speaker=7824,}",
  [100077] = "{id=100077,Text='如果你有空的话，可以去斐扬寻找月神沐恩的信徒洛伊奥，他似乎有些话想说。',Speaker=7824,Option='{我愿意,3},{我不愿意,4}',}",
  [100078] = "{id=100078,Text='好吧，如果你改变主意了，随时可以来找我。',Speaker=7824,}",
  [100079] = "{id=100079,Text='很多年后的今天，月神沐恩的故事已然变成了一段过往。',Speaker=7083,}",
  [100080] = "{id=100080,Text='因为巨狼哈提的存在，被月神所眷顾的人类，终将会忘却月神的存在。',Speaker=7083,Option='什么',}",
  [100081] = "{id=100081,Text='你好，冒险者，我叫洛伊奥，是月神沐恩忠实的信徒。',Speaker=7083,}",
  [100082] = "{id=100082,Text='我已经知道你来找我的目的了，一定与月神沐恩有关吧。',Speaker=7083,Option='是的',}",
  [100083] = "{id=100083,Text='这些年来，我执着地寻找月神沐恩所留下的痕迹。',Speaker=7083,}",
  [100084] = "{id=100084,Text='我总能感受到一丝丝微弱的气息从南边传来，是月神沐恩的气息！',Speaker=7083,}",
  [100085] = "{id=100085,Text='只是伴随着月神的气息，我同时感受到了强烈的不安。',Speaker=7083,}",
  [100086] = "{id=100086,Text='就在斐扬南部，冒险者，你愿意帮我去调查一下吗？',Speaker=7083,Option='好的',}",
  [100087] = "{id=100087,Text='你回来了，冒险者，你有什么发现吗？',Speaker=7083,Option='恶狼',}",
  [100088] = "{id=100088,Text='什么？恶狼？难道是……我明白了！',Speaker=7083,Emoji=1,}",
  [100089] = "{id=100089,Text='它们一定是巨狼哈提的随从！',Speaker=7083,}",
  [100090] = "{id=100090,Text='我早该想到的，巨狼哈提一定不会放过任何一丝月神的气息。',Speaker=7083,}",
  [100091] = "{id=100091,Text='冒险者，让你陷入危险，真是抱歉。',Speaker=7083,Option='没事',}",
  [100092] = "{id=100092,Text='还好你已经击杀了那些恶狼，看来暂时不会有危险了。',Speaker=7083,}",
  [100093] = "{id=100093,Text='就在你刚刚去过的地方，似乎有什么东西，去把它们带回来吧，这可有着大用处。',Speaker=7083,}",
  [100094] = "{id=100094,Text='这是……皓月之辉！这是月神沐恩留给我们的神器！',Speaker=7083,}",
  [100095] = "{id=100095,Text='只是这似乎破碎了，也许我可以尝试着修复这象征着月神力量的神器。',Speaker=7083,}",
  [100096] = "{id=100096,Text='当然这些是远远不够的，巨狼哈提没有除去之前，我们不得不做好防备。',Speaker=7083,}",
  [100097] = "{id=100097,Text='在梦罗克，有一位智慧的长者维斯德姆，一些关于巨狼哈提的消息，他知道的或许比我还多。',Speaker=7083,}",
  [100098] = "{id=100098,Text='是洛伊奥让你来的？',Speaker=7084,Option='是的',}",
  [100099] = "{id=100099,Text='你想知道些什么？',Speaker=7084,Option='关于哈提',}",
  [100100] = "{id=100100,Text='哈提……真是我不愿提起的一段往事。',Speaker=7084,}",
  [100101] = "{id=100101,Text='在我很小很小的时候，邪恶的巨狼哈提妄图吞噬天空中的月亮和月神沐恩。',Speaker=7084,}",
  [100102] = "{id=100102,Text='地上的人类为了拯救沐恩，彻夜击鼓奏乐，赶走了贪婪的哈提。',Speaker=7084,}",
  [100103] = "{id=100103,Text='可是狡猾的哈提因此记恨上了人类，在白天月神无法现身的时候，哈提集合他的随从一起偷偷的袭击人类。',Speaker=7084,}",
  [100104] = "{id=100104,Text='沐恩不愿见到人们受到哈提的欺侮，于是便借用了月亮的力量重创了哈提。',Speaker=7084,}",
  [100105] = "{id=100105,Text='但沐恩也因此耗尽了自己的精力，他身上的缕缕月光变成了破碎的皎月之辉。',Speaker=7084,}",
  [100106] = "{id=100106,Text='而后，他便匆匆离开了他一直所守护的人们。',Speaker=7084,}",
  [100107] = "{id=100107,Text='我相信总有一天，月神沐恩会回到我们的身边，但是最近……巨狼哈提似乎渐渐恢复了他的力量。',Speaker=7084,Option='哈提在哪',}",
  [100108] = "{id=100108,Text='你要去找哈提？',Speaker=7084,}",
  [100109] = "{id=100109,Text='冒险者，我佩服你的勇气，但是这可不是闹着玩的，哈提的力量不是我们人类能比的。',Speaker=7084,}",
  [100110] = "{id=100110,Text='你真的要去找哈提吗？',Speaker=7084,Option='是的',}",
  [100111] = "{id=100111,Text='既然你坚持……那么我便告诉你吧，巨狼哈提和他的随从们就藏在斐扬洞窟，你可千万要小心些。',Speaker=7084,}",
  [100112] = "{id=100112,Text='你竟然能找到这里，无知的人类。',Speaker=7086,}",
  [100113] = "{id=100113,Text='快把皓月之辉交出来！不然我就把你撕碎！',Speaker=7086,Option='拒绝',}",
  [100114] = "{id=100114,Text='哈……追随月神沐恩的人类，都该死！',Speaker=7086,}",
  [100115] = "{id=100115,Text='真没想到……你竟然真的杀死了巨狼哈提。',Speaker=7083,}",
  [100116] = "{id=100116,Text='也只有你，能够有资格支配这皓月之辉的力量。',Speaker=7083,}",
  [100117] = "{id=100117,Text='这修复好的皓月之辉我便交给你了，它可以为你驱赶黑暗与痛苦，带来月亮的辉光照亮前行的道路。',Speaker=7083,}",
  [100118] = "{id=100118,Text='而我，要在这里等待月神的归来，我相信总有一天，月神会重新回到这个世界上。',Speaker=7083,Option='好的',}",
  [100119] = "{id=100119,Text='皓月之辉么……',Speaker=7824,}",
  [100120] = "{id=100120,Text='真是不可思议，没想到你竟然能得到这件神器！',Speaker=7824,}",
  [100121] = "{id=100121,Text='让我来研究一下，说不定能改造地更适合你，让它发挥出更大的力量。',Speaker=7824,}",
  [100122] = "{id=100122,Text='你就放心的看着吧！',Speaker=7824,}",
  [100179] = "{id=100179,Text='嗯？通过迷宫的你意外获得了一个【古老机器人的躯干】。',}",
  [100180] = "{id=100180,Text='嗯？通过迷宫的你意外获得了一个【古老机器人的四肢】。',}",
  [100181] = "{id=100181,Text='嗯？通过迷宫的你意外获得了一个【古老机器人的头】。',}",
  [100195] = "{id=100195,Text='我认识一个少女，她似乎不是人类。',Speaker=7824,}",
  [100196] = "{id=100196,Text='我能感受到她身上拥有的强大力量，但她似乎并不能控制住自己的力量，也许你能够帮助她。',Speaker=7824,}",
  [100197] = "{id=100197,Text='这个少女似乎与一个传说中的神器皎月之弦有关。',Speaker=7824,}",
  [100198] = "{id=100198,Text='她叫卢娜，就在艾尔帕兰，你可以去找她。',Speaker=7824,Option='{我愿意,3},{我不愿意,4}',}",
  [100199] = "{id=100199,Text='那你可真是错过了一个很大的机遇呢。',Speaker=7824,}",
  [100200] = "{id=100200,Text='快去吧，祝你好运！',Speaker=7824,}",
  [100201] = "{id=100201,Text='又来了一个，真是让人烦透了。',Speaker=7087,}",
  [100202] = "{id=100202,Text='如果你是为了我身上的秘密而来，那你还是回去吧，我不想随随便便的把自己的秘密告诉一个陌生人。',Speaker=7087,Option='不是',}",
  [100203] = "{id=100203,Text='哦？不是吗？那你来找我做什么？',Speaker=7087,Option='解释',}",
  [100204] = "{id=100204,Text='帮助我控制自己的力量？我不认为你能帮助到我。',Speaker=7087,}",
  [100205] = "{id=100205,Text='有一位智慧的学者，叫做赛比恩斯，没有人比他更能了解神器了。',Speaker=7087,}",
  [100206] = "{id=100206,Text='所有人都可以去回答他的三个问题，答对的人会得到他的信物。',Speaker=7087,}",
  [100207] = "{id=100207,Text='我想，除非你过了他那关，我才能认为你有可能帮助到我。',Speaker=7087,}",
  [100208] = "{id=100208,Text='赛比恩斯就在普隆德拉北部，快去快去！',Speaker=7087,Emoji=5,}",
  [100209] = "{id=100209,Text='你好，冒险者，我是专门研究神器的智慧学者赛比恩斯。',Speaker=7088,}",
  [100210] = "{id=100210,Text='非常欢迎你来挑战我，你愿意回答我三个问题吗？',Speaker=7088,Option='好的',}",
  [100211] = "{id=100211,Text='第一个问题，有一把剑无比锋利，却又噬主，每代剑主人都不得善终，你知道它的名字吗？',Speaker=7088,Option='{永恒之枪,3},{提尔锋,2},{万神的注视,3}',}",
  [100212] = "{id=100212,Text='看来你对神器的了解还是太少了，等你了解了再来找我吧。',Speaker=7088,Emoji=31,}",
  [100213] = "{id=100213,Text='不错，那你知道神器万神的注视被拔起之时会引来什么魔物吗？',Speaker=7088,Option='{贪心的巫婆,4},{贪婪的恶狼,3},{贪玩的幽灵,3}',}",
  [100214] = "{id=100214,Text='最后一个问题，召唤凛冬结晶温特的咒语最后一句是什么？',Speaker=7088,Option='{凛冬钻石,3},{冰晶结晶,3},{凛冬结晶,5}',}",
  [100215] = "{id=100215,Text='哈哈哈，没想到你对神器竟然如此了解！',Speaker=7088,}",
  [100216] = "{id=100216,Text='这是我的信物，你已经获得了我的认可。',Speaker=7088,}",
  [100217] = "{id=100217,Text='真不错，你竟然这么快便能获得赛比恩斯的认可，也许你真的能帮到我。',Speaker=7087,}",
  [100218] = "{id=100218,Text='或许你已经看出来了吧，我并不是人类。',Speaker=7087,Option='是的',}",
  [100219] = "{id=100219,Text='但你一定想不到，我就是神器皎月之弦。',Speaker=7087,}",
  [100220] = "{id=100220,Text='我常年伴随月神沐恩左右，早已经有了自己的智慧。',Speaker=7087,}",
  [100221] = "{id=100221,Text='几百年过去了，我一直以这种独特的方式而存在，只是近些年来，月神的消失让我渐渐难以控制自己身上的月神之力。',Speaker=7087,}",
  [100222] = "{id=100222,Text='迷藏森林有一种蓝萤草，它似乎可以压制我身上的力量，去帮我摘10株过来吧。',Speaker=7087,}",
  [100223] = "{id=100223,Text='我想你应该能够辨认的出。',Speaker=7087,}",
  [100224] = "{id=100224,Text='没错，这就是蓝萤草，但愿这会有用，让我来试试看吧。',Speaker=7087,}",
  [100225] = "{id=100225,Text='不……我似乎哪里不对劲……',Speaker=7087,}",
  [100226] = "{id=100226,Text='啊！！！！！',Speaker=7087,}",
  [100227] = "{id=100227,Text='对不起……我刚刚没有办法控制自己的力量。',Speaker=7087,Option='没关系',}",
  [100228] = "{id=100228,Text='不过以后却不会了，那草药虽然一度使我失控，但你打败了魔化的我，最终还是抑制住了我身上力量。',Speaker=7087,}",
  [100229] = "{id=100229,Text='没能达到月神大人的期望，是我的失职。',Speaker=7087,Option='月神大人？',}",
  [100230] = "{id=100230,Text='我陪伴在月神沐恩身边已经几百年了，七十五年前，月神沐恩与巨狼哈提一战，月神大人最终负伤离开。',Speaker=7087,}",
  [100231] = "{id=100231,Text='他让我留在这里，等待一个可以代替他守护人类的人，并把自己的力量交给他。',Speaker=7087,}",
  [100232] = "{id=100232,Text='我不明白，这世上怎么会有第二个像月神大人一样的人。',Speaker=7087,}",
  [100233] = "{id=100233,Text='于是我终日压抑自己的力量，不与他人打交道，我想等待月神大人的归来，却没想到有一天，我竟无法控制自己的力量。',Speaker=7087,}",
  [100234] = "{id=100234,Text='直到遇到了你，冒险者，是你拯救了我，达到了月神大人的期许。',Speaker=7087,Option='我吗',}",
  [100235] = "{id=100235,Text='这一刻，我也才真正明白月神大人的用意。',Speaker=7087,}",
  [100236] = "{id=100236,Text='你不用谦虚，冒险者，你有足够的力量可以拥有并支配皎月之弦！',Speaker=7087,Emoji=26,}",
  [100237] = "{id=100237,Text='我会追随你的步伐，记住，你一定要用自己的力量代替月神大人守护人类，在人们黑暗的时候给予他们辉光，照亮他们前行的道路！',Speaker=7087,}",
  [100238] = "{id=100238,Text='原来卢娜就是皎月之弦，这可真让人意想不到。',Speaker=7824,}",
  [100239] = "{id=100239,Text='更让人想不到的是，她竟然认可了你。',Speaker=7824,}",
  [100240] = "{id=100240,Text='不过你也的确拥有这样的实力呢！既然皎月之弦认可了你，那么你可要完成月神沐恩的使命啊！',Speaker=7824,}",
  [100241] = "{id=100241,Text='这名字里，藏着主人对我的爱呢。',}",
  [100242] = "{id=100242,Text='如果你喜欢的话，我没什么意见咯~',}",
  [100243] = "{id=100243,Text='听上去和本小姐很相称呢~',}",
  [100244] = "{id=100244,Text='嘻嘻，主人果然还是离不开我吧？',}",
  [100245] = "{id=100245,Text='哈欠~魔力已经补满了呢~',}",
  [100246] = "{id=100246,Text='哇哈哈哈~魔焰降临！',}",
  [100247] = "{id=100247,Text='我们之间越来越默契了呢~主人~',}",
  [100248] = "{id=100248,Text='用爱的魔法把我们链接在一起吧，嘿呀~',}",
  [100249] = "{id=100249,Text='主人是我在世界上最最最喜欢的人类~',}",
  [100253] = "{id=100253,Text='这就是人类的公会啊~不知道防火性能如何，嘻嘻嘻~~',}",
  [100254] = "{id=100254,Text='好多人类在盯着我呢，可以把他们的眉毛烧掉么，主人？',}",
  [100255] = "{id=100255,Text='我是这里最“火”力四射的焦点呢，主人~',}",
  [100265] = "{id=100265,Text='我感觉体内的魔力在增长!',}",
  [100266] = "{id=100266,Text='这样离大魔女这个目标就更近一步了呢。',}",
  [100267] = "{id=100267,Text='哇，主人快看看我是不是又长大了一点了？',}",
  [100268] = "{id=100268,Text='没想到会在这里...倒下....',}",
  [100269] = "{id=100269,Text='看来我的魔法，还不够强大...呜！',}",
  [100270] = "{id=100270,Text='我的火焰竟然...熄灭了...',}",
  [100271] = "{id=100271,Text='可以清楚的感受到主人的温暖呢~',}",
  [100272] = "{id=100272,Text='幸福持续升温中~我好想一直陪在你身边~',}",
  [100273] = "{id=100273,Text='呜~不要把人家当作小孩子啦！',}",
  [100274] = "{id=100274,Text='再吃下去要变胖女巫了啦！',}",
  [100275] = "{id=100275,Text='不吃不吃！本魔女现在没胃口。',}",
  [100276] = "{id=100276,Text='现在不需要新的贡品~',}",
  [100277] = "{id=100277,Text='主人不在的时候，我可没有乱烧东西哟,真的没有啦，嘻嘻~~',}",
  [100278] = "{id=100278,Text='在召唤魔法里加入思念，主人一下就出现啦~',}",
  [100279] = "{id=100279,Text='我对主人的思念之火已经熊熊燃烧了唷！',}",
  [100280] = "{id=100280,Text='让我看到帅气的一面吧~主人！',}",
  [100281] = "{id=100281,Text='在主人的力量面前变成灰烬吧~~~',}",
  [100282] = "{id=100282,Text='你将学会畏惧小魔女的火焰~',}",
  [100283] = "{id=100283,Text='mini魔物什么的，一下就烧完了~',}",
  [100284] = "{id=100284,Text='给主人放个魔法大烟火庆祝胜利~',}",
  [100285] = "{id=100285,Text='我有好好用魔法帮助主人唷~这次有本小姐的一份功劳呢！',}",
  [100289] = "{id=100289,Text='呐~呐~主人，我可以自己骑着扫帚去飞一圈么？',}",
  [100290] = "{id=100290,Text='主人不理我的时候小魔女会很寂寞的...',}",
  [100291] = "{id=100291,Text='玩火的女孩子才是最热辣哒！',}",
  [100292] = "{id=100292,Text='主人的火焰烧的更旺了呢~',}",
  [100293] = "{id=100293,Text='再加把劲就可以追上我咯~主人~',}",
  [100294] = "{id=100294,Text='小魔女会见证主人的成长哒~~',}",
  [100298] = "{id=100298,Text='啊~我好想用时间停止魔法永远留住这份幸福~~',}",
  [100299] = "{id=100299,Text='唔呼呼~我感觉自己在升温~~！',}",
  [100300] = "{id=100300,Text='主人的疼爱比火焰更让我温暖~~',}",
  [100301] = "{id=100301,Text='呜呼呜呼~魔女也是要靠食物补充魔法的呀',}",
  [100302] = "{id=100302,Text='这么好吃的食物，真的不是加了魔法么？',}",
  [100303] = "{id=100303,Text='呜呜~本小姐竟然被人类的食物征服了~~',}",
  [100304] = "{id=100304,Text='喂喂！你这家伙可别死啊！',}",
  [100305] = "{id=100305,Text='主人撑住！我马上就用魔法支援你~~',}",
  [100306] = "{id=100306,Text='主人，别大意啊！背包里的药水呢？',}",
  [100307] = "{id=100307,Text='哼哼哼~我穿什么都很可爱呢~',}",
  [100308] = "{id=100308,Text='下次再给我穿童装的话，我会把你烤焦唷，主人。',}",
  [100309] = "{id=100309,Text='只有这样的华丽装备才配得上我魔女的身份~',}",
  [100313] = "{id=100313,Text='小魔女也是女孩子啊，需要被疼爱的时候，主人就要好好宠我~',}",
  [100314] = "{id=100314,Text='主人我好像发烧了，快摸摸我额头~',}",
  [100315] = "{id=100315,Text='我听鬼女说被主人摸头可以长高呢！快试试，主人~',}",
  [100316] = "{id=100316,Text='饿肚子的话，我可长不大啊，主人！',}",
  [100317] = "{id=100317,Text='越厉害的魔女就需要越美味的贡品！',}",
  [100318] = "{id=100318,Text='主人...饿得摸的到自己的良心了啦...',}",
  [100319] = "{id=100319,Text='这可是我用魔法编织出的珍品唷，主人要好好珍惜啊。',}",
  [100320] = "{id=100320,Text='加了一些些魔法，和很多很多对主人的爱~',}",
  [100321] = "{id=100321,Text='哟呼~小魔女出品，必属精品~',}",
  [100328] = "{id=100328,Text='走开走开，现在是小魔女的下午茶时间~',}",
  [100335] = "{id=100335,Text='是！在下以后就叫这个名字了！',}",
  [100336] = "{id=100336,Text='真是个响亮的名字！',}",
  [100337] = "{id=100337,Text='主人亲自取的吗？在下感激不尽！',}",
  [100338] = "{id=100338,Text='整装完毕！随时待命！',}",
  [100339] = "{id=100339,Text='我的枪是不是忘在蛋里了？',}",
  [100340] = "{id=100340,Text='玩具士兵时刻准备着！',}",
  [100341] = "{id=100341,Text='在下与主人的情谊在战斗中越发牢固！',}",
  [100342] = "{id=100342,Text='战友情升级！',}",
  [100343] = "{id=100343,Text='在战斗中积累的情感是不可替代的！',}",
  [100347] = "{id=100347,Text='这里就是我军的大本营了吧！',}",
  [100348] = "{id=100348,Text='公会里的战友们似乎对在下颇有赏识呢！',}",
  [100349] = "{id=100349,Text='进入工会！收腹、挺胸、抬头、目视前方，两肩向后张！',}",
  [100359] = "{id=100359,Text='在下变得更强了，哇哈哈哈！',}",
  [100360] = "{id=100360,Text='主人，在下会迈着大步追赶你的背影！',}",
  [100361] = "{id=100361,Text='军衔提升!',}",
  [100362] = "{id=100362,Text='像士兵一样光荣的倒下...',}",
  [100363] = "{id=100363,Text='主人，在下算烈士么？',}",
  [100364] = "{id=100364,Text='一个玩具士兵倒下了，还有主人会给在下报仇！',}",
  [100365] = "{id=100365,Text='在下想起了曾经还是玩具时的幸福时光...',}",
  [100366] = "{id=100366,Text='有可以依赖的人果然很棒！',}",
  [100367] = "{id=100367,Text='主人的手上战略视野宽阔！',}",
  [100368] = "{id=100368,Text='肚子沉甸甸的话~没有办法自如作战！',}",
  [100369] = "{id=100369,Text='在下...再也吃不下了，嗝~',}",
  [100370] = "{id=100370,Text='在下是士兵！不是饭桶！',}",
  [100371] = "{id=100371,Text='主人不在的时候，在下也没有松懈自身的锻炼！',}",
  [100372] = "{id=100372,Text='玩具士兵随时待命！',}",
  [100373] = "{id=100373,Text='今天也要和主人一起冒险！',}",
  [100374] = "{id=100374,Text='瞄准！射击！',}",
  [100375] = "{id=100375,Text='等待你们的只有铁与血！',}",
  [100376] = "{id=100376,Text='吃在下一发玩具意大利炮！',}",
  [100377] = "{id=100377,Text='主人的实力不容置疑！',}",
  [100378] = "{id=100378,Text='只用刮胡子的功夫就解决了！',}",
  [100379] = "{id=100379,Text='一颗子弹的事儿，不行就两颗！',}",
  [100383] = "{id=100383,Text='咳咳！在下可不是木头士兵！',}",
  [100384] = "{id=100384,Text='主人是在交流作战情报么？',}",
  [100385] = "{id=100385,Text='战机不可失啊，主人。',}",
  [100386] = "{id=100386,Text='主人变得更强壮了呢。',}",
  [100387] = "{id=100387,Text='感觉主人的火力更上了一层楼！',}",
  [100388] = "{id=100388,Text='主人越来越有强者的气息了！',}",
  [100392] = "{id=100392,Text='要想玩的好，玩具士兵不可少。',}",
  [100393] = "{id=100393,Text='被人心疼的感觉真好~',}",
  [100394] = "{id=100394,Text='主人的抚摸就像荒漠中出现的绿洲！',}",
  [100395] = "{id=100395,Text='这可比行军罐头好吃太多了，啊呜~',}",
  [100396] = "{id=100396,Text='只有吃饱了才能全力战斗！啊呜~',}",
  [100397] = "{id=100397,Text='男人就应该默默的吃干净！啊呜~',}",
  [100398] = "{id=100398,Text='坚持住，主人！',}",
  [100399] = "{id=100399,Text='主人！你负伤啦，赶紧喝口药水！',}",
  [100400] = "{id=100400,Text='医疗兵！医疗兵在哪里？？',}",
  [100401] = "{id=100401,Text='这是对在下的军功的嘉奖么，主人？',}",
  [100402] = "{id=100402,Text='真是精良的装备啊。',}",
  [100403] = "{id=100403,Text='胡子？那是男人的浪漫！',}",
  [100407] = "{id=100407,Text='在下是玩具！当然需要主人的宠爱！',}",
  [100408] = "{id=100408,Text='被捧在主人的手心是每个玩具的渴望！我也不例外！',}",
  [100409] = "{id=100409,Text='主人！到了举高高训练的时间啦~',}",
  [100410] = "{id=100410,Text='人是铁，饭是钢，玩具士兵饿得慌！',}",
  [100411] = "{id=100411,Text='在下好像听到了吃饭的集结号！',}",
  [100412] = "{id=100412,Text='在下的胡子都饿得失去了光泽...',}",
  [100413] = "{id=100413,Text='虽然在下手笨，但会努力做出主人喜欢的头饰！',}",
  [100414] = "{id=100414,Text='头饰？在下更喜欢勋章。',}",
  [100415] = "{id=100415,Text='精工出细活。',}",
  [100422] = "{id=100422,Text='在下要去巡逻了~没工夫理你唷~',}",
  [100429] = "{id=100429,Text='就是你的专属小熊啦！',}",
  [100430] = "{id=100430,Text='熊熊好喜欢主人这样叫我~',}",
  [100431] = "{id=100431,Text='这名字是我属于你的证明！',}",
  [100432] = "{id=100432,Text='主人~主人~熊熊好想你呀~',}",
  [100433] = "{id=100433,Text='终于从黑不溜秋的宠物蛋里溜出来啦！ ',}",
  [100434] = "{id=100434,Text='玩具熊应该呆在宽敞舒适的礼盒里！而不是蛋！',}",
  [100435] = "{id=100435,Text='无论时间怎么变，玩具熊对主人的爱不会变！~',}",
  [100436] = "{id=100436,Text='我的“熊生”有你才完整。',}",
  [100437] = "{id=100437,Text='一天一天想你到无可救药~',}",
  [100441] = "{id=100441,Text='这就是主人的公会嘛？好热闹吖~',}",
  [100442] = "{id=100442,Text='人群之中，只有主人是我唯一的爱！',}",
  [100443] = "{id=100443,Text='我是不是公会里最可爱的熊？',}",
  [100453] = "{id=100453,Text='升级以后我摸起来更软了唷。',}",
  [100454] = "{id=100454,Text='熊熊变的更加无人可挡！',}",
  [100455] = "{id=100455,Text='玩具熊进化！超可爱的玩具熊！',}",
  [100456] = "{id=100456,Text='我的发条停止了...',}",
  [100457] = "{id=100457,Text='好困呀，主人越来越模糊了...',}",
  [100458] = "{id=100458,Text='主人要记得把熊熊修好...',}",
  [100459] = "{id=100459,Text='你的双手，是我的心之所向，梦之所属。',}",
  [100460] = "{id=100460,Text='这时候熊熊深深感受到生而为熊的幸福~',}",
  [100461] = "{id=100461,Text='我需要时你会抱着我，你需要时，我当然也会抱住你。',}",
  [100462] = "{id=100462,Text='再吃的话，我的肚子会变成皮球的！',}",
  [100463] = "{id=100463,Text='吃不下了！熊熊的缝合线要撑开了！',}",
  [100464] = "{id=100464,Text='不能吃了，熊熊要滚着跑地图了！',}",
  [100465] = "{id=100465,Text='主人回来啦！给你一个正宗熊抱~',}",
  [100466] = "{id=100466,Text='主人不在的每一天，熊熊都有很认真的想你！',}",
  [100467] = "{id=100467,Text='没有熊熊的日子里，主人是抱着枕头睡的么？',}",
  [100468] = "{id=100468,Text='妨碍主人的家伙都会被我打扁！',}",
  [100469] = "{id=100469,Text='吃我一发熊霸天下拳！',}",
  [100470] = "{id=100470,Text='永远不要惹一只有主的玩具熊！',}",
  [100471] = "{id=100471,Text='主人的大胜利！熊抱伺候~',}",
  [100472] = "{id=100472,Text='我一熊掌就拍死一只mini怪！',}",
  [100473] = "{id=100473,Text='我们会不会留下英勇的传说呀，主人？',}",
  [100477] = "{id=100477,Text='玩具熊是最好的听众唷。',}",
  [100478] = "{id=100478,Text='熊熊教你聊天吧，对喜欢的人一定要说多喝热水~',}",
  [100479] = "{id=100479,Text='是我，是我先，明明都是我先来的...聊天也好！牵手也好！',}",
  [100480] = "{id=100480,Text='主人和我一起成长了~',}",
  [100481] = "{id=100481,Text='主人变得更可靠了。',}",
  [100482] = "{id=100482,Text='无论什么等级，主人都要记得带着熊熊一起冒险唷。',}",
  [100486] = "{id=100486,Text='果然我是为了被主人疼爱才出生的。',}",
  [100487] = "{id=100487,Text='主人的怀抱永远是玩具熊的天堂！！~',}",
  [100488] = "{id=100488,Text='当你拥抱着我的时候，你就是世界。',}",
  [100489] = "{id=100489,Text='好满足，熊熊的肚皮圆鼓鼓了。',}",
  [100490] = "{id=100490,Text='主人是世界第一的玩具熊饲养员，耶！',}",
  [100491] = "{id=100491,Text='吃饱了的熊熊抱起来更舒服唷~',}",
  [100492] = "{id=100492,Text='主人肿了一个大包，熊熊好心疼！',}",
  [100493] = "{id=100493,Text='主人疼么？熊熊给你揉揉~',}",
  [100494] = "{id=100494,Text='主人伤在身上，熊熊疼在心里！',}",
  [100495] = "{id=100495,Text='熊装上阵！',}",
  [100496] = "{id=100496,Text='主人把我宠上天啦~',}",
  [100497] = "{id=100497,Text='熊熊原来的样子还不够可爱嘛？',}",
  [100501] = "{id=100501,Text='主人，快来试试我的手感~软乎乎~',}",
  [100502] = "{id=100502,Text='被主人抱抱摸摸举高高才是玩具熊的本职工作~',}",
  [100503] = "{id=100503,Text='据说摸摸玩具熊会带来好运唷。',}",
  [100504] = "{id=100504,Text='饿得快把肚子里的棉花消化了...',}",
  [100505] = "{id=100505,Text='玩具熊吃饱了会更柔软唷。',}",
  [100506] = "{id=100506,Text='再不吃饭我就要饿成纸片熊啦！',}",
  [100507] = "{id=100507,Text='我是一只心灵手巧的玩具熊！',}",
  [100508] = "{id=100508,Text='要我说，熊耳朵是最可爱的头饰。',}",
  [100509] = "{id=100509,Text='你是要戴着它去参加舞会么，主人？',}",
  [100516] = "{id=100516,Text='小熊留，小熊走，小熊喜欢与否~',}",
  [100526] = "{id=100526,Text='索斯居然没有反击。',Speaker=5713,}",
  [100541] = "{id=100541,Text='唔啊啊啊啊啊！！！',Speaker=5753,}",
  [100586] = "{id=100586,Text='[c][ffff00][PlayerName][-][/c]，塞壬，首先恭喜你们顺利解读了我给你们传达的暗号。',Speaker=5809,}",
  [100587] = "{id=100587,Text='成功的抵达——秘密之翼的总部。',Speaker=5809,Option='秘密之翼',}",
  [100588] = "{id=100588,Text='接下来我要说的话，是建立在对你们百分之百的信任和肯定的基础上。',Speaker=5809,}",
  [100589] = "{id=100589,Text='我能信任你们吗？你们能信任我吗？',Speaker=5809,}",
  [100590] = "{id=100590,Text='誓死捍卫总统阁下！',Speaker=5800,}",
  [100591] = "{id=100591,Text='好，跟我来。',Speaker=5809,}",
  [100592] = "{id=100592,Text='我虽然身为朱诺的大总统，表面上掌握政治商业与军事。',Speaker=5809,}",
  [100593] = "{id=100593,Text='但遗憾的是，我的手上并没有太多实权。',Speaker=5809,}",
  [100594] = "{id=100594,Text='因为雷根贝勒公司的势力太过强大，已经基本垄断了朱诺的商业命脉。',Speaker=5809,Option='什么',}",
  [100595] = "{id=100595,Text='不仅仅是商业！',Speaker=5809,}",
  [100596] = "{id=100596,Text='还有一半以上的兵权被暗握在雷根贝勒公司手中。',Speaker=5809,}",
  [100597] = "{id=100597,Text='但经过我多年的调查，发现这个公司并没有我们想像的那么简单。',Speaker=5809,Option='哦？',}",
  [100598] = "{id=100598,Text='我发现其中有许多阴谋和黑暗深不见底。',Speaker=5809,}",
  [100599] = "{id=100599,Text='朱诺人民光明的未来不能毁在这个阴暗的公司手中！',Speaker=5809,}",
  [100600] = "{id=100600,Text='所以我成立了反抗雷根贝勒公司的秘密组织——秘密之翼。',Speaker=5809,}",
  [100601] = "{id=100601,Text='我联合了卢恩王国和共和国内优秀的精英冒险者们。',Speaker=5809,}",
  [100602] = "{id=100602,Text='我怀疑，这次魔物袭击水晶的事件，以及你们所说的生化魔物。',Speaker=5809,}",
  [100603] = "{id=100603,Text='都和雷根贝勒脱不了干系！',Speaker=5809,Option='是嘛',}",
  [100604] = "{id=100604,Text='但我的权力受到压制，无法直接出面，所以只能派出秘密之翼来帮助你们！',Speaker=5809,}",
  [100605] = "{id=100605,Text='当然，其中还包括你认识的人，冒险者。',Speaker=5809,}",
  [100606] = "{id=100606,Text='是赛依连以及他的小队！',}",
  [100607] = "{id=100607,Text='他们都是秘密之翼的成员。',Speaker=5809,Option='原来如此',}",
  [100608] = "{id=100608,Text='赛依连以及他的小队正在四个地点执行任务。',Speaker=5809,}",
  [100609] = "{id=100609,Text='这里是我亲笔书写的秘密文书。',Speaker=5809,}",
  [100610] = "{id=100610,Text='带着这份文书将六人紧急召回！',Speaker=5809,}",
  [100611] = "{id=100611,Text='我不能离开总统府太久，接下来的事情就全权交给卫斯理。',Speaker=5809,}",
  [100612] = "{id=100612,Text='我需要离开了！',Speaker=5809,}",
  [100660] = "{id=100660,Text='冒险者，你知道这世上最强大的守护之力是什么吗？',Speaker=7824,Option='什么',}",
  [100661] = "{id=100661,Text='是爱。',Speaker=7824,}",
  [100662] = "{id=100662,Text='爱的守护足以抵挡世间任何邪恶的力量。',Speaker=7824,}",
  [100663] = "{id=100663,Text='你去古城找一位叫做皮弗拉的年轻人吧，他仿佛有事需要帮助。',Speaker=7824,Option='{我愿意,3},{我不愿意,4}',}",
  [100664] = "{id=100664,Text='也许你去帮助他一下会比较好，不过我尊重你的决定。',Speaker=7824,}",
  [100665] = "{id=100665,Text='很好，你的善良会指引你走向最正确的道路。',Speaker=7824,}",
  [100666] = "{id=100666,Text='你可算来了，冒险者！',Speaker=7090,Option='发生了什么',}",
  [100667] = "{id=100667,Text='准确地说，是我的朋友需要帮助，你先听我慢慢解释。',Speaker=7090,}",
  [100668] = "{id=100668,Text='很多人都知道，我的朋友迪芬达是星河之盾的守护者，他有着伟大的使命在身上，必须保护星河之盾不被邪恶力量所掌控。',Speaker=7090,}",
  [100669] = "{id=100669,Text='邪恶的女巫希勒斯一直妄图窃取星河之盾，提取其中的星河之力来增强她自己的邪恶魔法。',Speaker=7090,}",
  [100670] = "{id=100670,Text='原本迪芬达可以保护好星河之盾，但是邪恶女巫希勒斯竟然捉走了迪芬达的爱人可姆莉丝。',Speaker=7090,}",
  [100671] = "{id=100671,Text='你快去帮帮迪芬达吧！我们一定会好好感谢你的！',Speaker=7090,}",
  [100672] = "{id=100672,Text='他已经朝着妙勒尼山脉出发了，你现在过去，应该还来得及。',Speaker=7090,}",
  [100673] = "{id=100673,Text='冒险者，不要打扰我，我正在做一件重要的事。',Speaker=7091,Option='解释',}",
  [100674] = "{id=100674,Text='你是来帮助我的？',Speaker=7091,Option='是的',}",
  [100675] = "{id=100675,Text='这真是太好了，或许有了你的帮助，我们能够彻底战胜希勒斯，救回可姆莉丝！',Speaker=7091,}",
  [100676] = "{id=100676,Text='我正在追踪希勒斯的气息，冒险者，我在这边搜寻，请你去南边调查看看。',Speaker=7091,}",
  [100677] = "{id=100677,Text='怎么样，冒险者，你有什么发现吗？',Speaker=7091,Option='拦路的魔物',}",
  [100678] = "{id=100678,Text='我也遇到了这些拦路的魔物，看来邪恶女巫希勒斯就在这附近。',Speaker=7091,}",
  [100679] = "{id=100679,Text='这些魔物的强横似乎超过了我的想象，没想到希勒斯的能力竟然如此厉害。',Speaker=7091,}",
  [100680] = "{id=100680,Text='冒险者，请你把这个消息告诉我的朋友皮弗拉，让我帮我再做些准备。',Speaker=7091,}",
  [100681] = "{id=100681,Text='什么，希勒斯竟然有如此强大的力量？',Speaker=7090,}",
  [100682] = "{id=100682,Text='这真让人想不到，如要让她得到了星河之盾，那可就没人能够打败她了。',Speaker=7090,}",
  [100683] = "{id=100683,Text='我们必须帮助迪芬达打败邪恶女巫，一起守护星河之盾。',Speaker=7090,Option='好的',}",
  [100684] = "{id=100684,Text='让我想想……邪恶女巫似乎很惧怕一种毒蘑菇制成的药水，把药水洒到她的身上，或许你们战胜她更有把握一些。',Speaker=7090,}",
  [100685] = "{id=100685,Text='快去哥布灵森林采集10个毒蘑菇吧，然后再来找我，我来准备一下制作药水的工具。',Speaker=7090,}",
  [100686] = "{id=100686,Text='太棒了，我要准备制作药水了，你可要当心点，可别被药水溅到了！',Speaker=7090,Option='好的',}",
  [100687] = "{id=100687,Text='成功了！这个毒蘑菇药水我就交给你了，拿它对付希勒斯再好不过了。',Speaker=7090,}",
  [100688] = "{id=100688,Text='赶紧去找迪芬达吧！但愿没有耽误太多时间。',Speaker=7090,}",
  [100689] = "{id=100689,Text='哈哈哈哈哈！我终于击败了迪芬达，星河之盾马上就要属于我了！',Speaker=7092,}",
  [100690] = "{id=100690,Text='你又是谁？难道你是迪芬达叫来的帮手吗？',Speaker=7092,Option='没错',}",
  [100691] = "{id=100691,Text='就凭你？哈哈哈！等我打败了你再去夺取星河之盾！',Speaker=7092,}",
  [100692] = "{id=100692,Text='不……这药水……我要杀了你！！！',Speaker=7092,}",
  [100693] = "{id=100693,Text='多亏了你，冒险者，可姆莉丝得救了，星河之盾也能免遭邪恶力量的侵蚀。',Speaker=7091,Option='没事就好',}",
  [100694] = "{id=100694,Text='或许你不知道，这星河之盾本身便是星之女神为了保护她的爱人才制作的，可惜我却没有发挥出它的作用。',Speaker=7091,}",
  [100695] = "{id=100695,Text='我想我已经没有资格使用并守护它了，要不是你的出现，只怕会酿成更大的错误。',Speaker=7091,}",
  [100696] = "{id=100696,Text='冒险者，我认为，你有资格拥有星河之盾，我想把它交给你来守护。',Speaker=7091,}",
  [100697] = "{id=100697,Text='而我，余下的日子，只想和可姆莉丝找一个安静的村庄，好好地生活下去。',Speaker=7091,}",
  [100698] = "{id=100698,Text='这个沉重而又伟大的责任可就交给你了，你一定不会令我失望的！',Speaker=7091,}",
  [100699] = "{id=100699,Text='星河之盾啊……这可真是难得一见的神器啊……',Speaker=7824,}",
  [100700] = "{id=100700,Text='得到星河之盾守护者的认可，你可真是了不起。',Speaker=7824,}",
  [100701] = "{id=100701,Text='拥有了这个神器以后，你可不能乱来，记住，要用爱的力量哦~',Speaker=7824,}",
  [100702] = "{id=100702,Text='你也是来找星辰之盔的？',Speaker=7824,Option='是的',}",
  [100703] = "{id=100703,Text='最近想打探星辰之盔消息的人可真多。',Speaker=7824,}",
  [100704] = "{id=100704,Text='可是头盔只有一个，想要得到它的人必须要具备拥有它的资格。',Speaker=7824,Option='？',}",
  [100705] = "{id=100705,Text='如果你能打动它，它会主动认领你这个主人的哦~',Speaker=7824,Option='什么？',}",
  [100706] = "{id=100706,Text='（转过身去）你现在去找一个叫莫莉的小女孩吧，接下来的事情，我也不能跟你透露哦~',Speaker=7824,Option='她在哪？',}",
  [100707] = "{id=100707,Text='告诉你可以，不过你要回答我一个问题。',Speaker=7824,Option='好的',}",
  [100708] = "{id=100708,Text='你知道神器可以怎样使用吗？',Speaker=7824,Option='{只能一个人用,2},{公会共享神器,3},{只能使用一次,4}',}",
  [100709] = "{id=100709,Text='不会吧！这种送分题你都会选错！你让我怎么帮你啊！',Speaker=7824,}",
  [100710] = "{id=100710,Text='就算告诉你莫莉在哪儿你也会走错路吧！',Speaker=7824,Emoji=15,}",
  [100711] = "{id=100711,Text='看来你还不笨，莫莉在兽人村那里，你去找找看吧。',Speaker=7824,}",
  [100712] = "{id=100712,Text='你是来帮我哥哥的吗？',Speaker=5072,Option='哥哥？',}",
  [100713] = "{id=100713,Text='看来你不是。',Speaker=5072,Emoji=24,}",
  [100714] = "{id=100714,Text='（哭着说）哥哥被讨厌的克拉奈抓起来了，他们那帮可恶的兽人抢走了我们的东西，还要抓走哥哥！',Speaker=5072,Option='为什么？',}",
  [100715] = "{id=100715,Text='我跟哥哥每天去各个地方运送自己种的新鲜蔬菜，拿到集市上去赚点零花钱。',Speaker=5072,}",
  [100716] = "{id=100716,Text='可是今天路过兽人村他们不让我们过去，而且还要扣下我们的蔬菜。',Speaker=5072,}",
  [100717] = "{id=100717,Text='哥哥很生气跟他们大吵了一架，他们就把哥哥抓起来了。',Speaker=5072,Option='真过分！',Emoji=24,}",
  [100718] = "{id=100718,Text='我现在只想哥哥能平安的回来。',Speaker=5072,Option='我帮你',}",
  [100719] = "{id=100719,Text='真的吗？我现在也不知道克拉奈把哥哥绑去了哪里，你帮我找找好吗？',Speaker=5072,Option='好的',}",
  [100720] = "{id=100720,Text='（拍拍莫莉肩膀让她放心。）',}",
  [100721] = "{id=100721,Text='地上有一些不属于兽人的脚印。',}",
  [100722] = "{id=100722,Text='这里地上有一些散碎的蔬菜叶。',}",
  [100723] = "{id=100723,Text='莫莉的哥哥应该就在前面。',}",
  [100724] = "{id=100724,Text='懦弱的人类少多管闲事！',Speaker=5074,Option='放了他！',}",
  [100725] = "{id=100725,Text='看来你根本没把我放在眼里啊，你这小混混！',Speaker=5074,}",
  [100726] = "{id=100726,Text='我没听错吧，这家伙竟然说我是小混混？',}",
  [100727] = "{id=100727,Text='（捂住脸）你这个小混混竟然打我！',Speaker=5074,}",
  [100728] = "{id=100728,Text='你好，冒险者。我叫罗恩，是莫莉的哥哥，谢谢你救了我。',Speaker=5073,}",
  [100729] = "{id=100729,Text='不过即便你救了我，如果你是来打星辰之盔的主意就不要想了。',Speaker=5073,Option='！！？',}",
  [100730] = "{id=100730,Text='你别装了，你肯定也知道莫莉是打开星辰宝盒的钥匙，而那宝盒里放的就是万人所求的星辰之盔！',Speaker=5073,Option='我不知道',}",
  [100731] = "{id=100731,Text='我不管你知不知道，我不会让莫莉离开我的，你们这群自私的人！',Speaker=5073,Option='……',}",
  [100732] = "{id=100732,Text='原来你都知道了哥哥，既然你知道，为什么还要一直守在我身边。',Speaker=5072,}",
  [100733] = "{id=100733,Text='终究有一天我还是会离开你的啊，我的使命就是为星辰宝盒找到合适的主人。',Speaker=5072,}",
  [100734] = "{id=100734,Text='莫莉你这个小傻瓜，只要我们兄妹两过得快乐，为什么要管那么多本不归于我们的使命。',Speaker=5073,}",
  [100735] = "{id=100735,Text='难道星辰宝盒没有你就永远打不开吗？',Speaker=5073,}",
  [100736] = "{id=100736,Text='就算打不开那又怎么样！就因为它我就要失去你吗？！',Speaker=5073,}",
  [100737] = "{id=100737,Text='我还怕你们走了，既然没走那就一个都别想离开了。',Speaker=5074,}",
  [100738] = "{id=100738,Text='敢打我兄弟，你们是胆子不小啊！',Speaker=5075,}",
  [100739] = "{id=100739,Text='人类！是不是太不把我们兽人放在眼里了。',Speaker=5076,}",
  [100740] = "{id=100740,Text='哼！算你小子厉害。',Speaker=5074,}",
  [100741] = "{id=100741,Text='谢谢你又救了我们，看到哥哥平安我真的很开心。',Speaker=5072,}",
  [100742] = "{id=100742,Text='我跟哥哥虽然不是亲兄妹，但我们一直形影不离，罗恩待我像亲妹妹一样体贴。',Speaker=5072,}",
  [100743] = "{id=100743,Text='（含泪微笑）今天遇到你，我既欣慰又难过，终于为星辰宝盒找到合适的主人了，我的使命完成了。',Speaker=5072,}",
  [100744] = "{id=100744,Text='哥哥，我要离开了。',Speaker=5072,}",
  [100745] = "{id=100745,Text='（抽泣）莫莉不能违抗自己的使命，这是莫莉存在的理由。',Speaker=5072,}",
  [100746] = "{id=100746,Text='（闭上眼睛）你要好好照顾自己，莫莉永远为你祈福。',Speaker=5072,}",
  [100747] = "{id=100747,Text='罗恩在一边哽咽的说不出话来。',}",
  [100748] = "{id=100748,Text='哥哥，替莫莉照顾好你自己，别难过。',Speaker=5072,}",
  [100749] = "{id=100749,Text='（莫莉在空中消散成一团金色粉尘，粉尘汇聚成一把金光闪闪的钥匙缓缓落到了你的手上。）',}",
  [100750] = "{id=100750,Text='不！！！',Speaker=5073,}",
  [100751] = "{id=100751,Text='[c][ffff00][PlayerName][-][/c]，你的神情为何有点沉重呢？',Speaker=7824,Option='你该知道',}",
  [100752] = "{id=100752,Text='总之既然你是莫莉选定的人，星辰之盔是你的了。',Speaker=7824,}",
  [100758] = "{id=100758,Text='太阳头盔了解一下~',Speaker=7824,Option='好的',}",
  [100759] = "{id=100759,Text='太阳背饰了解一下~',Speaker=7824,Option='好的',}",
  [100775] = "{id=100775,Text='好的，你确定支付[c][ffff00]1280000Zeny[-][/c]租用符文骑士龙吗？',Speaker=5996,Option='{确定支付,6},{我再想想,7}',}",
  [100789] = "{id=100789,Text='传闻焰耀头盔是一位崇拜太阳的侏儒炼制而成的，因其富含太阳神力而得名，冒险者，现在我就把这头盔赠予你吧，希望你能发挥出它最大的威力。',Speaker=7824,}",
  [100799] = "{id=100799,Text='你知道太阳女神的传说么，冒险家？',Speaker=7824,Option='太阳女神？',}",
  [100800] = "{id=100800,Text='在传说中，太阳女神娑尔负责驾驭由两匹神驹拉着的太阳马车在天空驰骋，为人们带来光明。',Speaker=7824,}",
  [100801] = "{id=100801,Text='神驹的名字叫奥瓦可与奥斯温。',Speaker=7824,}",
  [100802] = "{id=100802,Text='而魔狼芬里尔的子嗣—斯库尔，则不停的追逐着太阳马车，妄图吞下太阳。',Speaker=7824,}",
  [100803] = "{id=100803,Text='女神娑尔的金色头冠，名为炎阳之拥，蕴藏着有来自太阳的强大力量。',Speaker=7824,Option='好酷！',}",
  [100804] = "{id=100804,Text='冒险者，你渴望得到神器的力量么？',Speaker=7824,Option='{当然,3},{我还没准备好,4}',}",
  [100805] = "{id=100805,Text='当你做好准备再回来找我吧。',Speaker=7824,}",
  [100806] = "{id=100806,Text='我想你已经做好了准备。',Speaker=7824,}",
  [100807] = "{id=100807,Text='在依斯鲁得的港口有一对信奉太阳女神的神官姐妹，去问问她们吧。',Speaker=7824,}",
  [100808] = "{id=100808,Text='赞美女神，愿阳光永远照耀着你。',Speaker=5077,Option='关于炎阳之拥',}",
  [100809] = "{id=100809,Text='是海德薇尔告诉你的么？',Speaker=5077,Option='嗯',}",
  [100810] = "{id=100810,Text='既然是海德薇尔认可的人，我可以放心的把关于神器的事告诉你了。',Speaker=5077,}",
  [100811] = "{id=100811,Text='在西比尔预言书中，诸神黄昏降临之时',Speaker=5077,}",
  [100812] = "{id=100812,Text='太阳与拉着太阳的两匹神驹最终无法逃离被斯库尔吞噬的命运。',Speaker=5077,}",
  [100813] = "{id=100813,Text='但女神娑尔却选择了守护太阳马车离开，独自留下战斗。',Speaker=5077,}",
  [100814] = "{id=100814,Text='女神娑尔与斯库尔在缠斗中，一同坠入大海。',Speaker=5077,}",
  [100815] = "{id=100815,Text='最终以牺牲自己的代价把魔狼斯库尔封印在海底神殿。',Speaker=5077,Option='值得尊敬',}",
  [100816] = "{id=100816,Text='想要让太阳之拥重现于世，你需要得到娑尔遗物的力量',Speaker=5077,Option='怎么做？',}",
  [100817] = "{id=100817,Text='海族将娑尔带有太阳神力的遗物供奉在海底神殿中，以加强斯库尔的封印。',Speaker=5077,}",
  [100818] = "{id=100818,Text='被选中之人，请前往海底神殿深处，寻找太阳女神娑尔的遗物交给我。',Speaker=5077,Option='我出发了！',}",
  [100819] = "{id=100819,Text='要平安归来阿，受太阳眷顾之人。',Speaker=5077,}",
  [100820] = "{id=100820,Text='欲取得太阳神力者，必踏上被魔狼追逐之路。',Speaker=5077,}",
  [100821] = "{id=100821,Text='你找到女神的遗物啦。',Speaker=5077,}",
  [100822] = "{id=100822,Text='一但女神的遗物离开海底神殿，斯库尔的封印就会减弱。',Speaker=5077,Option='什么？！',}",
  [100823] = "{id=100823,Text='放心，它出不来。',Speaker=5077,Option='呼~',}",
  [100824] = "{id=100824,Text='但是它能制造出自身的幻影四处作恶。',Speaker=5077,Option='那怎么办？',}",
  [100825] = "{id=100825,Text='所以能拜托你去海底神殿深处击败斯库尔的幻影么？',Speaker=5077,Option='没问题！',}",
  [100826] = "{id=100826,Text='一股强大的黑暗气息出现了！',}",
  [100827] = "{id=100827,Text='我，斯库尔！我即是白昼尽头的恶梦，吞噬太阳的魔狼！',Speaker=5079,}",
  [100828] = "{id=100828,Text='你身上有太阳的气息，斯库尔饿了！！！',Speaker=5079,}",
  [100829] = "{id=100829,Text='浓郁的黑暗气息退散了。',}",
  [100830] = "{id=100830,Text='赞美女神，你平安回来了!',Speaker=5077,Option='斯库尔…',}",
  [100831] = "{id=100831,Text='被斯库尔阻挠了么？这是想得到炎阳之拥者不可逃避的命运。',Speaker=5077,Option='{你早就知道？,2},{你到底是谁？,2}',}",
  [100832] = "{id=100832,Text='我会把一切告诉你的，但不是现在。',Speaker=5077,Option='好吧',}",
  [100833] = "{id=100833,Text='去和我的妹妹斯温娜谈谈吧，她会告诉你下一步该怎么做。',Speaker=5077,}",
  [100834] = "{id=100834,Text='赞美女神，愿阳光永远照耀着你。',Speaker=5078,}",
  [100835] = "{id=100835,Text='你终于完成我姐姐的任务啦，被选中的冒险家！',Speaker=5078,}",
  [100836] = "{id=100836,Text='别高兴的太早，得到了太阳女神遗物的力量还不足以唤醒炎阳之拥。',Speaker=5078,Option='还需要什么？！',}",
  [100837] = "{id=100837,Text='还需要强大的魔力作为唤醒神器的钥匙。',Speaker=5078,Option='怎么做？',}",
  [100838] = "{id=100838,Text='我听说在艾尔帕兰钟楼里出现的黑魔女拥有强大的魔力。',Speaker=5078,}",
  [100839] = "{id=100839,Text='能否请你从黑魔女身上收集30个无光水晶交给我？',Speaker=5078,Option='没问题!',}",
  [100840] = "{id=100840,Text='你收集齐了吗？',Speaker=5078,Option='{收集齐了,3},{没有,2}',}",
  [100841] = "{id=100841,Text='好像还不够，请再加把劲！',Speaker=5078,}",
  [100842] = "{id=100842,Text='你成功了！我马上开启你与炎阳之拥的联接！',Speaker=5078,}",
  [100843] = "{id=100843,Text='脑海中出现了一个温暖的女声...似乎在呼唤着两个名字...',}",
  [100844] = "{id=100844,Text='奥瓦可...奥斯温...是你们么？',}",
  [100845] = "{id=100845,Text='你听见女神的声音了么？',Speaker=5077,}",
  [100846] = "{id=100846,Text='聪明的冒险家啊，你应该猜到我们姐妹和娑尔的关系了吧？',Speaker=5077,}",
  [100847] = "{id=100847,Text='我们是娑尔的...',Speaker=5077,Option='{女儿！,2},{神驹！,3},{女粉丝！,4}',}",
  [100848] = "{id=100848,Text='很抱歉，你猜错啦。',Speaker=5077,}",
  [100849] = "{id=100849,Text='……',Speaker=5077,}",
  [100850] = "{id=100850,Text='你猜对啦，我和姐姐就是娑尔的两匹神驹的化身。',Speaker=5078,}",
  [100851] = "{id=100851,Text='我们姐妹是神驹——奥瓦可，奥斯温的化身。',Speaker=5078,Option='果然',}",
  [100852] = "{id=100852,Text='因为斯库尔散发的黑暗力量，我们无法接近海底',Speaker=5078,Option='嗯',}",
  [100853] = "{id=100853,Text='所以只能在悠久的岁月中徘徊在依斯鲁得，默默等待着。',Speaker=5078,}",
  [100854] = "{id=100854,Text='等待一个能为我们深入海底神殿，击败斯库尔的幻影，取回女神遗物的人',Speaker=5078,}",
  [100855] = "{id=100855,Text='等待一个被太阳眷顾，值得我们交付炎阳之拥的人。',Speaker=5078,Option='嘻嘻',}",
  [100856] = "{id=100856,Text='现在我们终于等到你的出现，唤醒炎阳之拥最后的材料是我们姐妹的金发。',Speaker=5078,}",
  [100857] = "{id=100857,Text='好好运用炎阳之拥的能力吧，冒险家',Speaker=5078,}",
  [100858] = "{id=100858,Text='我们该回到女神身边了，祝福你！',Speaker=5078,Option='再见啦',}",
  [100859] = "{id=100859,Text='辛苦了，冒险者！',Speaker=5743,}",
  [100860] = "{id=100860,Text='剩下的交给我吧！',Speaker=5743,}",
  [100895] = "{id=100895,Text='你知道黎明之卫的传说么，冒险家？',Speaker=7824,Option='黎明之卫？',}",
  [100896] = "{id=100896,Text='在传说中，太阳女神娑尔有一面神盾，名叫黎明之卫。',Speaker=7824,}",
  [100897] = "{id=100897,Text='诸神黄昏降临，她在与魔狼的战斗中，将黎明之卫遗落在米德加尔特。',Speaker=7824,}",
  [100898] = "{id=100898,Text='传说中神器黎明之卫拥有抵挡一切黑暗的力量。',Speaker=7824,}",
  [100899] = "{id=100899,Text='冒险者，你渴望得到神器的力量么？',Speaker=7824,Option='{当然,3},{我还没准备好,4}',}",
  [100900] = "{id=100900,Text='当你做好准备再回来找我吧。',Speaker=7824,}",
  [100901] = "{id=100901,Text='我想你已经做好了准备。',Speaker=7824,}",
  [100902] = "{id=100902,Text='在梦罗克的流氓公会总部有一位情报贩子，去向他打听一下吧。',Speaker=7824,}",
  [100903] = "{id=100903,Text='哟~冒险家你是来打听的情报的吧？',Speaker=5081,Option='没错',}",
  [100904] = "{id=100904,Text='好~神器的情报10000zeny怎么样？',Speaker=5081,Option='没问题',}",
  [100905] = "{id=100905,Text='这么爽快？那就付我1000000zeny吧！',Speaker=5081,}",
  [100906] = "{id=100906,Text='市场总是瞬息万变的，啊哈哈哈！',Speaker=5081,Option='抢劫？',Emoji=5,}",
  [100907] = "{id=100907,Text='好吧，好吧，不开玩笑了~',Speaker=5081,Option='玩笑？',}",
  [100908] = "{id=100908,Text='关于黎明之卫的情报是免费的~',Speaker=5081,Option='真善变',}",
  [100909] = "{id=100909,Text='咳咳，因为出发去寻找黎明之卫的人没一个回来……',Speaker=5081,Option='……',}",
  [100910] = "{id=100910,Text='你还决定要去嘛？',Speaker=5081,Option='{当然,7},{我再考虑一下,6}',}",
  [100911] = "{id=100911,Text='好吧，我随时等你哟',Speaker=5081,}",
  [100912] = "{id=100912,Text='据说在金字塔1F，突然出现了一个诡异的石碑。',Speaker=5081,}",
  [100913] = "{id=100913,Text='根据我的情报，石碑上有四句古老的预言与黎明之卫的封印有关。',Speaker=5081,}",
  [100914] = "{id=100914,Text='去调查一下石碑吧！',Speaker=5081,}",
  [100915] = "{id=100915,Text='这就是苏比利特说的石碑吧！？',}",
  [100916] = "{id=100916,Text='石碑上好像模糊写着一行字。',}",
  [100917] = "{id=100917,Text='金字塔底，太阳之瞳，炼狱之蛇，黑暗之眼',Speaker=5082,}",
  [100918] = "{id=100918,Text='我想我应该把这行字记下来。',Option='{记住了,3},{没记住,4}',}",
  [100919] = "{id=100919,Text='这么快就回来啦？',Speaker=5081,Option='小菜一碟！',}",
  [100920] = "{id=100920,Text='快，告诉我石碑上的预言！',Speaker=5081,}",
  [100921] = "{id=100921,Text='第一句是？',Speaker=5081,Option='{金字塔下,6},{金字塔底,7},{金字塔尖,6},{金字塔上,6}',}",
  [100922] = "{id=100922,Text='第二句是？',Speaker=5081,Option='{太阳之眼,8},{阳光之眼,8},{圣光之瞳,8},{太阳之瞳,9}',}",
  [100923] = "{id=100923,Text='第三句是？',Speaker=5081,Option='{炼狱之蛇,11},{地狱之蛇,10},{魔狱之蛇,10},{黑暗之蛇,10}',}",
  [100924] = "{id=100924,Text='第四句是？',Speaker=5081,Option='{地狱之瞳,12},{黑暗之瞳,12},{炼狱之眼,12},{黑暗之眼,13}',}",
  [100925] = "{id=100925,Text='真的吗？我很怀疑啊。',Speaker=5081,}",
  [100926] = "{id=100926,Text='等等，我好像可以把线索拼在一起了！',Speaker=5081,}",
  [100927] = "{id=100927,Text='预言中说的金字塔底应该是位置。',Speaker=5081,}",
  [100928] = "{id=100928,Text='太阳之瞳说的肯定是黎明之卫！',Speaker=5081,Option='你确定？',}",
  [100929] = "{id=100929,Text='当然，我的朋友，那炼狱之蛇，是指黑暗大蛇阿波菲斯。',Speaker=5081,Option='黑暗大蛇？',}",
  [100930] = "{id=100930,Text='比魔王梦罗克更古老的混沌魔神……',Speaker=5081,Option='魔神！？',}",
  [100931] = "{id=100931,Text='阿波菲斯是邪恶中的邪恶！',Speaker=5081,}",
  [100932] = "{id=100932,Text='别怕，黑暗大蛇早就被众神封印了。',Speaker=5081,Option='呼……',}",
  [100933] = "{id=100933,Text='传说阿波菲斯的封印就在金字塔下，',Speaker=5081,Option='……',}",
  [100934] = "{id=100934,Text='黎明之卫一定就藏在大蛇的封印附近呢。',Speaker=5081,}",
  [100935] = "{id=100935,Text='冒险家，去金字塔的深处调查大蛇的封印吧！',Speaker=5081,Option='好的',}",
  [100936] = "{id=100936,Text='在传说中，大蛇的女儿至今仍在守着封印，你要小心哟。',Speaker=5081,}",
  [100937] = "{id=100937,Text='迷途的人类啊，这里不是你该来的地方。',Speaker=5083,Option='你是谁？',}",
  [100938] = "{id=100938,Text='吾乃阿波菲斯之女——魔眼伊碧佩斯。',Speaker=5083,Option='{攻击她,2},{尝试交谈,3}',}",
  [100939] = "{id=100939,Text='我在守护我父亲阿波菲斯的封印。',Speaker=5083,}",
  [100940] = "{id=100940,Text='愚蠢的人类啊，贪婪蒙蔽了你的双眼。',Speaker=5083,Option='神器呢？',}",
  [100941] = "{id=100941,Text='我守着封印千年，从没听说什么太阳神盾。',Speaker=5083,Option='太阳之瞳？',}",
  [100942] = "{id=100942,Text='石碑预言中的太阳之瞳，说的是金字塔守护神的右眼。',Speaker=5083,}",
  [100943] = "{id=100943,Text='我的父亲千年前一直窥觊着他象征太阳的右眼。',Speaker=5083,Option='……',}",
  [100944] = "{id=100944,Text='最后也因为贪婪，被众神封印在此处。',Speaker=5083,Option='我的情报',}",
  [100945] = "{id=100945,Text='你的情报是假的，你被人愚弄了！',Speaker=5083,Option='我不信！',}",
  [100946] = "{id=100946,Text='你可以回去告诉给你情报的人，你找到了太阳神盾。',Speaker=5083,}",
  [100947] = "{id=100947,Text='看他的反应你就会明白了。',Speaker=5083,Option='……',}",
  [100948] = "{id=100948,Text='我在这里守着父亲的封印，千年不曾离开。',Speaker=5083,}",
  [100949] = "{id=100949,Text='若我骗你，你可以回来找我算账。',Speaker=5083,Option='好吧',}",
  [100950] = "{id=100950,Text='一定有人在背后搞鬼！',Speaker=5083,Option='我去试试',}",
  [100951] = "{id=100951,Text='你活着回来了？',Speaker=5081,Emoji=1,}",
  [100952] = "{id=100952,Text='你找到黎明之卫了么？',Speaker=5081,Option='拿到了',}",
  [100953] = "{id=100953,Text='什，什，什么？？？',Speaker=5081,Emoji=1,}",
  [100954] = "{id=100954,Text='这不可能！！！',Speaker=5081,Option='为什么？',}",
  [100955] = "{id=100955,Text='因为！因为！',Speaker=5081,Option='你骗我？',}",
  [100956] = "{id=100956,Text='哼，你竟然发现了……',Speaker=5081,Option='为什么？',}",
  [100957] = "{id=100957,Text='只有利益是永远的朋友！',Speaker=5081,}",
  [100958] = "{id=100958,Text='我在梦罗克的沙漠中找到了黎明之卫，但是我一直无法唤醒它！',Speaker=5081,}",
  [100959] = "{id=100959,Text='大家来问我关于神器的线索，我怎么可能让别人得到它！',Speaker=5081,Option='所以你就？',}",
  [100960] = "{id=100960,Text='对，故意让他们去金字塔找大蛇的封印送死！',Speaker=5081,Option='你疯了!',}",
  [100961] = "{id=100961,Text='哼哼，放心吧，你和他们一样死定了！',Speaker=5081,}",
  [100962] = "{id=100962,Text='只有内心磊落之人，方可持起这守护光明之盾。',}",
  [101011] = "{id=101011,Text='艾丝菲尔开始吟唱精灵语，声音如天使与清泉一般动听。',}",
  [101012] = "{id=101012,Text='大地再次震动，似乎有什么被唤醒了。',}",
  [101013] = "{id=101013,Text='呷呷呷呷~~',Speaker=5087,}",
  [101014] = "{id=101014,Text='神圣的召唤仪式不容这样的不洁来玷污！！',Speaker=5086,}",
  [101163] = "{id=101163,Text='给的食物不对，丽丽安似乎生气了…',}",
  [101164] = "{id=101164,Text='丽丽安似乎很满足的吃饱了~',}",
  [101178] = "{id=101178,Text='[c][ffff00][PlayerName][-][/c]为我们带来了耐热披风！',Speaker=5825,}",
  [101179] = "{id=101179,Text='大家听好了，这次行动的计划是这样的！',Speaker=5825,}",
  [101180] = "{id=101180,Text='赛依连将与他的小队前去熔岩洞穴一层营救被困冒险者！',Speaker=5825,Option='了解',}",
  [101181] = "{id=101181,Text='我将率领曙光小队一起去熔岩洞穴二层营救被困冒险者！',Speaker=5825,}",
  [101182] = "{id=101182,Text='赛尼亚会在门口接应！',Speaker=5825,}",
  [101183] = "{id=101183,Text='你们准备好了吗！',Speaker=5825,}",
  [101184] = "{id=101184,Text='准备就绪！',Speaker=5845,}",
  [101185] = "{id=101185,Text='支援就交给你了！',Speaker=5825,}",
  [101191] = "{id=101191,Text='准备攻击！',Speaker=5851,}",
  [101192] = "{id=101192,Text='前面就是被困的冒险者！',Speaker=5851,}",
  [101193] = "{id=101193,Text='又是一道拦阻，但似乎没有上锁。',Speaker=5851,}",
  [101194] = "{id=101194,Text='试试拉一下那盏木机关。',Speaker=5851,}",
  [101195] = "{id=101195,Text='拉下机关',Speaker=5846,Option='拉下',}",
  [101196] = "{id=101196,Text='随着一阵轰鸣声，第二道铁栏杆也缓缓降下。',}",
  [101197] = "{id=101197,Text='是来救我们的，对吗。',Speaker=5852,Option='是的',}",
  [101198] = "{id=101198,Text='太好了…',Speaker=5852,}",
  [101199] = "{id=101199,Text='实在是惭愧，竟然这么轻易被抓到这种地方来。',Speaker=5852,Emoji=18,}",
  [101200] = "{id=101200,Text='这儿实在太热了，我们出去再说吧！',Speaker=5851,}",
  [101276] = "{id=101276,Text='想知道后面的故事么，请拍一张塞壬曾经住所的照片给我吧！',Speaker=1598,Option='好吧',}",
  [101318] = "{id=101318,Text='也是塞壬作为传奇战士开端的第一句话。（作废）',Speaker=1598,}",
  [101359] = "{id=101359,Speaker=5944,}",
  [101369] = "{id=101369,Text='他将把朱诺的海姆达水晶从沉睡中唤醒！',Speaker=5944,}",
  [101371] = "{id=101371,Text='请告诉总统阁下，水晶已成功唤醒！',Speaker=5948,}",
  [101387] = "{id=101387,Text='请告诉总统阁下，已成功完成对水晶的第二次修复！',Speaker=5949,}",
  [101392] = "{id=101392,Text='你确定要把背包里的全部时装更改为男性穿戴吗？这样需要消耗1000000Zeny哦~',Speaker=1724,Option='{确定,4},{取消,5}',}",
  [101397] = "{id=101397,Text='你确定要把背包里的全部时装更改为女性穿戴吗？这样需要消耗1000000Zeny哦~',Speaker=1724,Option='{确定,8},{取消,9}',}",
  [101426] = "{id=101426,Text='从你的内心里，我读到了渴望，读到了热爱，也读到了从一而终的单纯喜欢，那正是我想看到的。',Speaker=5096,}",
  [101427] = "{id=101427,Text='冒险者，恭喜你通过了我的考验。',Speaker=5096,}",
  [101439] = "{id=101439,Text='从你的行为中，我看到了理性，看到了果决，也看到了不屈服于阴暗世俗的坚定，那正是我想看到的。',Speaker=5097,}",
  [101502] = "{id=101502,Text='冒险者，你想变得更强大吗？阿萨神碑的力量已经完全觉醒了，试着利用这些力量壮大自己吧。',Speaker=5099,}",
  [101546] = "{id=101546,Text='那真是太遗憾了！',Speaker=1598,}",
  [101574] = "{id=101574,Text='很遗憾，看来你并没有领会这场考验的真谛啊。',Speaker=5097,}",
  [101576] = "{id=101576,Text='呦吼~你好呀冒险家~你听说过天空之城朱诺嘛？',Speaker=9504,Option='{当然,2},{那是啥,3}',}",
  [101577] = "{id=101577,Text='太好了，你能帮得上我的忙。',Speaker=9504,Emoji=9,}",
  [101578] = "{id=101578,Text='你的脚步已经跟不上版本了哟...',Speaker=9504,Emoji=10,}",
  [101579] = "{id=101579,Text='朱诺城中央的有一颗海姆达水晶你见过了么？',Speaker=9504,}",
  [101580] = "{id=101580,Text='据说海姆达水晶与神的遗迹有关，一直以来都是朱诺的骄傲呢。',Speaker=9504,}",
  [101581] = "{id=101581,Text='弄得本宝宝相当好奇啊。',Speaker=9504,}",
  [101582] = "{id=101582,Text='你可以拍一张海姆达水晶的照片让我看看么？',Speaker=9504,Option='{没问题,5},{我很忙,6}',}",
  [101583] = "{id=101583,Text='人家这么可爱，你真的忍心拒绝人家么？',Speaker=9504,Emoji=24,}",
  [101584] = "{id=101584,Text='太好了！不过记得要整个拍进去哦！',Speaker=9504,}",
  [101585] = "{id=101585,Text='哇，名不虚传的壮观呢，朱诺城还是有~点东西的嘛！',Speaker=9504,}",
  [101586] = "{id=101586,Text='你在朱诺的冒险之旅还顺利么？',Speaker=9504,Option='顺利',}",
  [101587] = "{id=101587,Text='你去参观过朱诺的贤者学院了吗？',Speaker=9504,Option='{去过了,2},{还没有,3}',}",
  [101588] = "{id=101588,Text='不像高高在上的朱诺大总统府，贤者学院欢迎一切渴求知识的人呢。',Speaker=9504,Option='真棒！',}",
  [101589] = "{id=101589,Text='不过现任的贤者学院院长西芙这个人......',Speaker=9504,Option='他怎么了？',Emoji=10,}",
  [101590] = "{id=101590,Text='你见到他应该就会明白了......',Speaker=9504,Option='？？？',}",
  [101591] = "{id=101591,Text='西芙似乎在想什么心事，嘴里念念有词。',Option='您......',}",
  [101592] = "{id=101592,Text='嘘……',Speaker=5999,Option='啊？',}",
  [101593] = "{id=101593,Text='安静。',Speaker=5999,Option='我是…',}",
  [101594] = "{id=101594,Text='嘘！',Speaker=5999,Option='请问.......',}",
  [101596] = "{id=101596,Text='真是个怪人！还是走吧...',}",
  [101597] = "{id=101597,Text='西芙突然开口缓缓地说道。',}",
  [101598] = "{id=101598,Text='朱诺是所有渴求知识之人的圣地，希望你能在这里找到你想要的答案。',Speaker=5999,Option='谢谢您',}",
  [101599] = "{id=101599,Text='对了，你是哪位？',Speaker=5999,Option='？？？',}",
  [101600] = "{id=101600,Text='西芙有回应你嘛？',Speaker=9504,Option='算是吧。',}",
  [101601] = "{id=101601,Text='我大概猜到了....',Speaker=9504,Emoji=5,}",
  [101602] = "{id=101602,Text='不好了，[c][ffff00][PlayerName][-][/c]',Speaker=9504,Option='怎么啦？',}",
  [101603] = "{id=101603,Text='去朱诺的必经之路有一种邪恶的魔物叫做鸟人哈比。',Speaker=9504,Option='鸟人哈比？',}",
  [101604] = "{id=101604,Text='鸟人哈比们身材曼妙，声音甜美，最擅长魅惑冒险家并将他们玩弄于股掌之中。',Speaker=9504,}",
  [101605] = "{id=101605,Text='刚有消息说一位新人冒险家在国境被一只不一样鸟人哈比带走了！',Speaker=9504,Option='糟糕！',}",
  [101606] = "{id=101606,Text='这事刻不容缓，拜托你去把他救出来吧！',Speaker=9504,Option='没问题！',}",
  [101607] = "{id=101607,Text='千万别被鸟人哈比迷惑！',Speaker=9504,}",
  [101608] = "{id=101608,Text='又一只小羔羊，你也在我的歌声里快乐的死去吧！',Speaker=9505,}",
  [101609] = "{id=101609,Text='啦啦啦，啦啦！在我的歌声里起舞吧！',Speaker=9505,}",
  [101610] = "{id=101610,Text='真是动听的歌声啊......',Speaker=9506,Option='捂住耳朵',Emoji=1,}",
  [101611] = "{id=101611,Text='可恶的人类，竟然有所防备！',Speaker=9505,}",
  [101612] = "{id=101612,Text='我这是在哪儿啊？你能把我送回普隆德拉么，拜托！',Speaker=9506,Option='好吧',Emoji=24,}",
  [101613] = "{id=101613,Text='哇，你把他救出来啦！',Speaker=9504,}",
  [101614] = "{id=101614,Text='谢谢你啦，我可不敢再乱闯朱诺了。',Speaker=9506,}",
  [101615] = "{id=101615,Text='面对朱诺的新魔物时，千万别轻敌啊！',Speaker=9504,}",
  [101616] = "{id=101616,Text='冒险者大人，您知道朱诺最缺什么东西嘛？',Speaker=9504,Option='{爱？,3},{勇气！,3},{福利！,3},{材料…,2}',}",
  [101617] = "{id=101617,Text='你想的太多了啦！~',Speaker=9504,Emoji=5,}",
  [101618] = "{id=101618,Text='对，是实验素材！',Speaker=9504,Option='又来！',}",
  [101619] = "{id=101619,Text='无论是雷根贝勒公司还是贤者学院，都需要大量的素材进行研究实验。',Speaker=9504,Option='哦....',}",
  [101620] = "{id=101620,Text='可以拜托你收集9999个...',Speaker=9504,}",
  [101621] = "{id=101621,Text='喂喂喂！别假死了，给本小姐起来！',Speaker=9504,Emoji=12,}",
  [101622] = "{id=101622,Text='收集材料太痛苦了？',Speaker=9504,Option='嗯....',}",
  [101623] = "{id=101623,Text='好吧，真受不了你！',Speaker=9504,}",
  [101624] = "{id=101624,Text='和人家猜拳，只要你能赢3局，就放过你！',Speaker=9504,Option='太好了！',}",
  [101625] = "{id=101625,Text='那么我们开始吧！',Speaker=9504,}",
  [101626] = "{id=101626,Text='出拳吧！',Speaker=9504,Option='{拳头,10},{剪刀,20},{布,30}',}",
  [101627] = "{id=101627,Text='人总会偶尔走一次运的嘛！',Speaker=9504,Option='{拳头,40},{剪刀,50},{布,60}',}",
  [101628] = "{id=101628,Text='没想到你这家伙运气还挺好的嘛！',Speaker=9504,Option='{拳头,70},{剪刀,80},{布,90}',}",
  [101629] = "{id=101629,Text='哼！可别太得意！你运气好而已！',Speaker=9504,}",
  [101630] = "{id=101630,Text='这次就放过你了，下次可没这样的福利任务！',Speaker=9504,}",
  [101631] = "{id=101631,Text='你还是洗个手再来挑战本小姐吧！',Speaker=9504,}",
  [101632] = "{id=101632,Text='通过这几天的任务，你已经对朱诺有一定了解了吧~',Speaker=9504,Option='是的',}",
  [101633] = "{id=101633,Text='那人家可以考考你么，答对有很棒的奖励噢~',Speaker=9504,Option='{放马过来,2},{等等,3}',}",
  [101634] = "{id=101634,Text='开始咯！第一题：共和国大总统的名字是？',Speaker=9504,Option='{卡特,5},{卡拉,5},{卡尔,6}',}",
  [101635] = "{id=101635,Text='你到底有没有去过朱诺啊，不会是在吹牛吧？',Speaker=9504,Emoji=19,}",
  [101636] = "{id=101636,Text='朱诺城中心的海姆达水晶周围有几个小水晶？',Speaker=9504,Option='{3,8},{4,9},{5,8}',}",
  [101637] = "{id=101637,Text='你懒到连照片都不看一眼嘛？',Speaker=9504,Emoji=12,}",
  [101638] = "{id=101638,Text='最后一题：是什么力量让朱诺漂浮在空中的呢？',Speaker=9504,Option='{贤者的魔法,12},{伊米尔之心,13},{B格猫神力,12}',}",
  [101639] = "{id=101639,Text='你已经差不多算半个朱诺通了嘛~',Speaker=9504,}",
  [101640] = "{id=101640,Text='把你的奖励拿去吧，在朱诺还有很多新的冒险等着你哟~！（爱心）',Speaker=9504,Emoji=1,}",
  [101641] = "{id=101641,Text='怪不得你身上多了点学院派的感觉~',Speaker=9504,}",
  [101642] = "{id=101642,Text='你真应该去里面好好转转！',Speaker=9504,}",
  [101646] = "{id=101646,Text='你是在讲什么冷笑话。',Speaker=9504,Emoji=10,}",
  [101648] = "{id=101648,Text='冒险者，怎么带着座狼过来了？',Speaker=5947,}",
  [101649] = "{id=101649,Text='卡仑难道满足不了你？',Speaker=5947,}",
  [101651] = "{id=101651,Text='好吧，虽然我觉得很麻烦。不过你需要支付30000Zeny，你的卡仑在我这呆着可不是免费帮你看管。',Speaker=5947,Option='{好的,2},{我再想想,3}',}",
  [101654] = "{id=101654,Text='没问题，不过需要支付20000Zeny帮你看管座狼的费用哦！',Speaker=5994,Option='{好的,2},{我再想想,3}',}",
  [101656] = "{id=101656,Text='冒险者，注意了！每天20:00到22:00，通往万恶之域的大门将打开，届时，我将带领有星星记号的魔物入侵到这片区域。击败我们，你将会获得丰厚的奖励，更有几率获得稀有材料，但要是不能击败我们，那就等着被我们统治吧！',Speaker=5768,}",
  [101657] = "{id=101657,Text='冒险者，注意了！每天20:00到22:00，通往万恶之域的大门将打开，届时，我将带领有星星记号的魔物入侵到这片区域。击败我们，你将会获得丰厚的奖励，更有几率获得稀有材料，但要是不能击败我们，那就等着被我们统治吧！',Speaker=5769,}",
  [101658] = "{id=101658,Text='冒险者，注意了！每天20:00到22:00，通往万恶之域的大门将打开，届时，我将带领有星星记号的魔物入侵到这片区域。击败我们，你将会获得丰厚的奖励，更有几率获得稀有材料，但要是不能击败我们，那就等着被我们统治吧！',Speaker=5770,}",
  [101661] = "{id=101661,Text='很抱歉，你的Zeny不够哦，带够了再来找我吧。',Speaker=5994,}",
  [101663] = "{id=101663,Text='每位冒险者只能坐骑一只伙伴，你已经有一只伙伴了，暂时不能找租借卡仑。',Speaker=5947,}",
  [101664] = "{id=101664,Text='我可是从天空之城朱诺来的美少女大使哟！',Speaker=9504,}",
  [101665] = "{id=101665,Text='你听说天空之城朱诺即将开放的消息了嘛？',Speaker=9504,Option='{当然,2},{那是啥,3}',}",
  [101666] = "{id=101666,Text='你的消息还挺灵通的嘛。',Speaker=9504,Emoji=9,}",
  [101667] = "{id=101667,Text='你们卢恩王国的消息这么落后啊？',Speaker=9504,Emoji=10,}",
  [101668] = "{id=101668,Text='我听说普隆德拉的皇宫和我们朱诺的总统府一样气派，是真的嘛？',Speaker=9504,Option='当然',}",
  [101669] = "{id=101669,Text='眼见为实，能拍一张普隆德拉皇宫的照片给我么？',Speaker=9504,Option='{当然,5},{我很忙,6}',}",
  [101670] = "{id=101670,Text='这就是你们卢恩王国的待客之道么？',Speaker=9504,Emoji=12,}",
  [101671] = "{id=101671,Text='没想到普隆德拉的皇宫还是有点东西的嘛！',Speaker=9504,}",
  [101672] = "{id=101672,Text='谢谢你啦，这是我从朱诺带来的礼物，感恩的收下吧！',Speaker=9504,}",
  [101673] = "{id=101673,Text='你听说职业转职的新消息了嘛？',Speaker=9504,Option='{当然,2},{不知道,3}',}",
  [101674] = "{id=101674,Text='那本小姐可以考考你关于新的职业内容么？',Speaker=9504,Option='可以',}",
  [101675] = "{id=101675,Text='你这个家伙真是消息闭塞！多关注一下我们世界的最新动态再来找我！',Speaker=9504,}",
  [101676] = "{id=101676,Text='答对就能拿到今天的奖励噢。',Speaker=9504,Option='放马过来',}",
  [101677] = "{id=101677,Text='开始咯！第一题：下面哪个是正确的骑士三转名称？',Speaker=9504,Option='{飞龙骑士,5},{黑喵骑士,5},{符文骑士,6}',}",
  [101678] = "{id=101678,Text='这题已经算容易的了吧，你真的知道新内容嘛？',Speaker=9504,Emoji=19,}",
  [101679] = "{id=101679,Text='下面哪种不是新增加的坐骑之一？ ',Speaker=9504,Option='{地龙,8},{大嘴鸟,9},{座狼,8}',}",
  [101680] = "{id=101680,Text='你到底有没有仔细看清题目啊？',Speaker=9504,Emoji=12,}",
  [101681] = "{id=101681,Text='最后一个问题，工匠们的福利，你知道是什么吗?',Speaker=9504,Option='{机甲,11},{金斧,12},{新式手推车,12}',}",
  [101682] = "{id=101682,Text='你是在讲冷笑话么。',Speaker=9504,Emoji=10,}",
  [101683] = "{id=101683,Text='看来你已经期待很久了嘛，知道的很详细呢。',Speaker=9504,}",
  [101684] = "{id=101684,Text='把今天的奖励拿去吧~',Speaker=9504,}",
  [101685] = "{id=101685,Text='唉，不知道为什么，自从来到普隆德拉以后，总感觉自己吃不饱。',Speaker=9504,}",
  [101686] = "{id=101686,Text='你说这是不是传说中的水土不服啊？',Speaker=9504,Option='肯定不是！ ',}",
  [101687] = "{id=101687,Text='咕咕咕！！！ ',Speaker=9504,Emoji=1,}",
  [101688] = "{id=101688,Text='这奇怪的声音是什么啊？',Speaker=9504,Option='{鸽子,4},{你的肚子,5}',}",
  [101689] = "{id=101689,Text='哪里来的鸽子啊，我怎么没看见？',Speaker=9504,Option='没问题',}",
  [101690] = "{id=101690,Text='咕咕咕咕咕！！！',Speaker=9504,}",
  [101691] = "{id=101691,Text='天呐，真的是我的肚子在咕咕叫！',Speaker=9504,}",
  [101692] = "{id=101692,Text='时间过得很快呢，我就快要回到朱诺了。',Speaker=9504,}",
  [101693] = "{id=101693,Text='我没想到普隆德拉之行会留下这么有趣的回忆。',Speaker=9504,Option='嘻嘻',}",
  [101694] = "{id=101694,Text='回去以后本小姐才不会想起你呢！',Speaker=9504,Option='死傲娇',}",
  [101695] = "{id=101695,Text='等到朱诺正式开放，你要记得来朱诺城找我玩噢！',Speaker=9504,Option='一定',}",
  [101696] = "{id=101696,Text='我给你的最后一个任务就是和我拍一张合影。',Speaker=9504,}",
  [101697] = "{id=101697,Text='记得要把本小姐拍得好看些！',Speaker=9504,}",
  [101698] = "{id=101698,Text='唔，这拍照技术，算你合格吧。',Speaker=9504,Option='哼',}",
  [101699] = "{id=101699,Text='你可别忘了我们的约定啊。',Speaker=9504,}",
  [101700] = "{id=101700,Text='你是把料理丢在路上了么?',Speaker=9504,}",
  [101701] = "{id=101701,Text='本小姐都忘记饿肚子的话它会抗议这件事了！ ',Speaker=9504,Option='这是常识',}",
  [101702] = "{id=101702,Text='听说有种叫做暖身料理的东西很管饱，你能带给我一个么？',Speaker=9504,Option='没问题',}",
  [101703] = "{id=101703,Text='快点！我的肚子它快撑不住啦！',Speaker=9504,Emoji=24,}",
  [101704] = "{id=101704,Text='好慢啊，本小姐都快饿得变成飞机场啦！',Speaker=9504,}",
  [101705] = "{id=101705,Text='呼，饿肚子的时候果然吃什么都香呢，谢谢你啦~',Speaker=9504,}",
  [101729] = "{id=101729,Text='卖这么久关子才说重点……',}",
  [101870] = "{id=101870,Text='嗯，已经顺利完成储存了，感谢使用，[c][ffff00][PlayerName][-][/c]！',Speaker=5961,}",
  [101871] = "{id=101871,Text='嗯，已经顺利完成储存了，感谢使用，[c][ffff00][PlayerName][-][/c]！',Speaker=5990,}",
  [101872] = "{id=101872,Text='现在要打开仓库了，收费%sZeny，谢谢您的使用！',Speaker=5961,Option='{好的,2},{下次吧,1}',}",
  [101873] = "{id=101873,Text='现在要打开仓库了，收费%sZeny，谢谢您的使用！',Speaker=5990,Option='{好的,2},{下次吧,1}',}",
  [101874] = "{id=101874,Text='[c][ffff00]准它公司[-][/c]拥有最便捷的物流技术，只要找到[c][ffff00]准它公司职员[-][/c]，就能进行物件存放和物件收取啦，请放心使用！',Speaker=5961,}",
  [101875] = "{id=101875,Text='以前使用仓库服务需要100z的费用，现在为了回馈冒险家所作出的贡献，仓库可以免费使用啦！希望冒险者们能够喜欢我们的服务哦。',Speaker=5961,}",
  [101876] = "{id=101876,Text='现在帮你打开仓库了，本次打开会扣除%sZeny，请好好利用！',Speaker=5961,Option='{打开仓库,2},{下次吧,3}',}",
  [101877] = "{id=101877,Text='[c][ffff00]准它公司[-][/c]拥有最便捷的物流技术，只要找到[c][ffff00]准它公司职员[-][/c]，就能进行物件存放和物件收取啦，请放心使用！',Speaker=5990,}",
  [101878] = "{id=101878,Text='以前使用仓库服务需要100z的费用，现在为了回馈冒险家所作出的贡献，仓库可以免费使用啦！希望冒险者们能够喜欢我们的服务哦。',Speaker=5990,}",
  [101879] = "{id=101879,Text='现在帮你打开仓库了，本次打开会扣除%sZeny，请好好利用！',Speaker=5990,Option='{打开仓库,2},{下次吧,3}',}",
  [101880] = "{id=101880,Text='冒险者！这里有个紧急事件需要你的帮助！',Speaker=5775,Option='{帮助他,2},{放弃,1}',}",
  [101881] = "{id=101881,Text='南门出现了一个奇怪的时空裂隙！！',Speaker=5775,Option='什么！',}",
  [101882] = "{id=101882,Text='是的，你没有听错呢！',Speaker=5775,}",
  [101883] = "{id=101883,Text='南门有众多刚刚加入乐园团的萌新冒险者！',Speaker=5775,Option='是啊',}",
  [101884] = "{id=101884,Text='如此未知的时空裂隙对他们来说实在是太危险了。',Speaker=5775,Option='是',}",
  [101885] = "{id=101885,Text='你现在就去调查一下那个时空裂隙吧，但愿不要有什么奇怪的魔物从裂隙里跑出来才好！！',Speaker=5775,Option='好的',}",
  [101886] = "{id=101886,Text='这！！这是哪里！？',Speaker=5772,Emoji=18,}",
  [101887] = "{id=101887,Text='嗯…',Speaker=5772,Emoji=8,}",
  [101888] = "{id=101888,Text='我从来没有来过这里…',Speaker=5772,Option='你是谁',}",
  [101889] = "{id=101889,Text='你好…',Speaker=5772,}",
  [101890] = "{id=101890,Text='我叫圆大古，是地球和平联合组织的一员。',Speaker=5772,Option='呃',}",
  [101891] = "{id=101891,Text='我只记得，之前在和一个巨型怪兽殊死搏斗。',Speaker=5772,}",
  [101892] = "{id=101892,Text='然后就从一道光线里掉到了这儿。',Speaker=5772,Option='是嘛',}",
  [101893] = "{id=101893,Text='你能告诉我这是哪里吗？',Speaker=5772,Option='{普隆德拉,2},{依斯鲁得,1},{梦罗克,1},{克雷斯特汉姆,1}',}",
  [101894] = "{id=101894,Text='我从来没听说过这里。',Speaker=5772,}",
  [101895] = "{id=101895,Text='不过用我的火花棱镜变身，应该能飞回总部去。',Speaker=5772,Option='火花棱镜？',}",
  [101896] = "{id=101896,Text='是的！',Speaker=5772,}",
  [101897] = "{id=101897,Text='面前这位奇怪的人身上发出了强烈的白光',}",
  [101898] = "{id=101898,Text='什么都没有发生…',}",
  [101899] = "{id=101899,Text='呃… 有点尴尬…',Speaker=5772,}",
  [101900] = "{id=101900,Text='我也不知道发生了什么。',Speaker=5772,}",
  [101901] = "{id=101901,Text='本来用这根神光棒就能变身为迪迦奥特曼呢…',Speaker=5772,Option='奥特曼！',}",
  [101902] = "{id=101902,Text='嘘，这是个秘密。',Speaker=5772,}",
  [101903] = "{id=101903,Text='但不知道为什么，神光棒没反应了。',Speaker=5772,Option='我看看',}",
  [101904] = "{id=101904,Text='一根大理石质感的神光棒，',}",
  [101905] = "{id=101905,Text='棒头护甲部分似乎缺失了一片大谷所说的棱镜。',}",
  [101906] = "{id=101906,Text='什么！那可真是糟糕！！',Speaker=5772,}",
  [101907] = "{id=101907,Text='火花棱镜坏了，我就没办法变身成迪迦奥特曼了！',Speaker=5772,Option='奥特曼！',}",
  [101908] = "{id=101908,Text='啊…',Speaker=5772,}",
  [101909] = "{id=101909,Text='这件事希望你能替我保密…',Speaker=5772,Option='好吧',Emoji=10,}",
  [101910] = "{id=101910,Text='这可如何是好…',Speaker=5772,}",
  [101911] = "{id=101911,Text='如果你…能帮我就太好了！',Speaker=5772,Option='{答应,4},{表示困扰,3}',}",
  [101912] = "{id=101912,Text='噢不，可能我就要永远困在这儿了。',Speaker=5772,}",
  [101913] = "{id=101913,Text='太好了，总而言之。',Speaker=5772,}",
  [101914] = "{id=101914,Text='~~~~咕~~~~~~~~~',}",
  [101915] = "{id=101915,Text='从大谷的肚子传来的声音。',}",
  [101916] = "{id=101916,Text='抱歉，来了这儿以后我就一口东西都没吃过呢…',Speaker=5772,Emoji=18,}",
  [101917] = "{id=101917,Text='可以带我去买点食物和水吗？',Speaker=5772,Option='当然',}",
  [101918] = "{id=101918,Text='这是是柠檬汁酸甜的气味！？',Speaker=5772,Emoji=2,}",
  [101919] = "{id=101919,Text='好浓郁的肉串香！！',Speaker=5772,}",
  [101920] = "{id=101920,Text='唔！虽然不知道这是哪里。',Speaker=5772,}",
  [101921] = "{id=101921,Text='可是这里的料理真的是太棒了！',Speaker=5772,}",
  [101922] = "{id=101922,Text='饱了饱了！',Speaker=5772,}",
  [101923] = "{id=101923,Text='真是多谢款待了。',Speaker=5772,}",
  [101924] = "{id=101924,Text='我们可不能忘了正事…',Speaker=5772,Option='是啊',}",
  [101925] = "{id=101925,Text='我的火花棱镜…',Speaker=5772,}",
  [101926] = "{id=101926,Text='总之我们先分头在刚才的地方找找。',Speaker=5772,}",
  [101927] = "{id=101927,Text='说不定会掉在附近。',Speaker=5772,}",
  [101928] = "{id=101928,Text='似乎是棱镜的碎片在地上闪闪发光。',}",
  [101929] = "{id=101929,Text='把碎片全都收集起来交给圆大古比较好…',}",
  [101930] = "{id=101930,Text='我的天呐！！这是我的火花棱镜吗？！',Speaker=5772,}",
  [101931] = "{id=101931,Text='噢，我都等不及要出发了！',Speaker=5772,}",
  [101932] = "{id=101932,Text='我向这里的居民收集了好多关于这里的情报呢！',Speaker=5772,Option='是吗',}",
  [101933] = "{id=101933,Text='听说吉芬是个魔法之都，希望这趟旅行可以让我大开眼界！！',Speaker=5772,Option='嘿嘿',}",
  [101934] = "{id=101934,Text='瞧啊！这城市实在是太神奇了！',Speaker=5772,}",
  [101935] = "{id=101935,Text='我知道说这话有点不合时宜！',Speaker=5772,Option='什么',}",
  [101936] = "{id=101936,Text='可是这儿和我居住的国家太不一样了。',Speaker=5772,}",
  [101937] = "{id=101937,Text='到处充满了魔法气息！',Speaker=5772,Option='是啊',}",
  [101938] = "{id=101938,Text='这太让人兴奋了不是吗！',Speaker=5772,Option='还好',Emoji=2,}",
  [101939] = "{id=101939,Text='[c][ffff00][PlayerName][-][/c]可以请你为我拍张照吗？',Speaker=5772,}",
  [101940] = "{id=101940,Text='我想回去以后，给我的队员们看看，我到过如此奇妙的地方！',Speaker=5772,Option='好吧',}",
  [101941] = "{id=101941,Text='这真是太棒了，队员们看到一定会目瞪口呆的！',Speaker=5772,Emoji=2,}",
  [101942] = "{id=101942,Text='不说笑了，嗯…',Speaker=5772,}",
  [101943] = "{id=101943,Text='瞧我，一不小心就忘记自我了！',Speaker=5772,Option='没事',}",
  [101944] = "{id=101944,Text='听普隆德拉广场上那只会说话的占卜猫说。',Speaker=5772,}",
  [101945] = "{id=101945,Text='吉芬地下有颗十分名贵的魔法水晶！',Speaker=5772,Option='猫！？',}",
  [101946] = "{id=101946,Text='重点不在这里啊喂！',Speaker=5772,}",
  [101947] = "{id=101947,Text='总之，听说多斯.福克纳先生将这颗水晶收藏在吉芬的图书馆内！',Speaker=5772,}",
  [101948] = "{id=101948,Text='我这里确实收藏了一块水晶。',Speaker=3308,Option='真的吗？',}",
  [101949] = "{id=101949,Text='不过我这个人，不喜欢那些成天期待头顶会掉馅饼的人。',Speaker=3308,Option='嗯。',}",
  [101950] = "{id=101950,Text='我可以分一小片给你，但必须要付出等价的代价。',Speaker=3308,}",
  [101951] = "{id=101951,Text='我这里正好缺一些魔法研究材料，带一些[c][ffff00]恶魔角[-][/c]给我作为交换吧！',Speaker=3308,Option='没问题',}",
  [101952] = "{id=101952,Text='已经收集到了吗？',Speaker=3308,Option='{收集到了,5},{没有,4}',}",
  [101953] = "{id=101953,Text='看来你已经收集到足够的[c][ffff00]恶魔角[-][/c]了，你愿意把这些[c][ffff00]恶魔角[-][/c]交给我吗？',Speaker=3308,Option='{愿意,6},{不愿意,7}',}",
  [101954] = "{id=101954,Text='别想不劳而获年轻人。',Speaker=3308,}",
  [101955] = "{id=101955,Text='看来你好像后悔这笔买卖了。',Speaker=3308,}",
  [101956] = "{id=101956,Text='你还没有收集到足够的[c][ffff00]恶魔角[-][/c]',Speaker=3308,}",
  [101957] = "{id=101957,Text='我认可你的努力，年轻人....',Speaker=3308,}",
  [101958] = "{id=101958,Text='水晶就在那里，自己去取一小片吧！',Speaker=3308,}",
  [101959] = "{id=101959,Text='小心，可不要把整块水晶都砍下来！',Speaker=3308,}",
  [101960] = "{id=101960,Text='太好了！现在就装进神光棒里试试看！',Speaker=5772,}",
  [101961] = "{id=101961,Text='圆大古身上再次发出了强烈的白光！',}",
  [101962] = "{id=101962,Text='呃…',Speaker=5778,Emoji=10,}",
  [101963] = "{id=101963,Text='发生了什么！？',Speaker=5778,}",
  [101964] = "{id=101964,Text='看来好像不太对…',Speaker=5778,Option='是啊',}",
  [101965] = "{id=101965,Text='我怎么变成这副模样了',Speaker=5778,Emoji=14,}",
  [101966] = "{id=101966,Text='算了，神光棒的威力只有三分钟…',Speaker=5778,}",
  [101967] = "{id=101967,Text='三分钟后我自然会变回来…',Speaker=5778,Option='嗯',}",
  [101968] = "{id=101968,Text='看来吉芬的魔法水晶不能代替火花棱镜。',Speaker=5778,}",
  [101969] = "{id=101969,Text='我们只能明天另想对策了…',Speaker=5778,Option='是啊',}",
  [101970] = "{id=101970,Text='嗯…',Speaker=5778,}",
  [101971] = "{id=101971,Text='我这个样子太丢人了，你赶快走！',Speaker=5778,}",
  [101972] = "{id=101972,Text='明天再来见我…',Speaker=5778,}",
  [101973] = "{id=101973,Text='[c][ffff00][PlayerName][-][/c]你可来的真早！',Speaker=5772,Option='嗯',}",
  [101974] = "{id=101974,Text='我又和这里魔法学院的学生聊了很多！',Speaker=5772,Option='是嘛',Emoji=14,}",
  [101975] = "{id=101975,Text='据说有一座叫艾尔帕兰的水都！',Speaker=5772,}",
  [101976] = "{id=101976,Text='都内高大雄伟的钟塔内，有一块时空钟表。',Speaker=5772,}",
  [101977] = "{id=101977,Text='钟表的表面和指针都蕴藏着巨大的能量。',Speaker=5772,Option='然后呢',}",
  [101978] = "{id=101978,Text='你猜我想说什么！',Speaker=5772,}",
  [101979] = "{id=101979,Text='没错，也许那些透明的表面可以用来代替火花棱镜！',Speaker=5772,Option='是嘛',}",
  [101980] = "{id=101980,Text='不试试怎么知道！',Speaker=5772,}",
  [101981] = "{id=101981,Text='我们现在就出发！目的地——艾尔帕兰！',Speaker=5772,}",
  [101982] = "{id=101982,Text='我已经迫不及待了！',Speaker=5772,}",
  [101983] = "{id=101983,Text='我能感受到一股巨大的能量就隐藏在这个钟塔内！',Speaker=5772,Option='是嘛',}",
  [101984] = "{id=101984,Text='也许我们该问问钟塔前的时钟守卫者们！',Speaker=5772,}",
  [101985] = "{id=101985,Text='说不定能了解些什么！',Speaker=5772,}",
  [101986] = "{id=101986,Text='的确有时空钟表的存在！',Speaker=5779,}",
  [101987] = "{id=101987,Text='只不过大家都觉得那只是一个传说。',Speaker=5779,Option='噢？',}",
  [101988] = "{id=101988,Text='如果你能找到足够的[c][ffff00]铠甲碎片[-][/c]，也许能启动钟塔内的时空齿轮。',Speaker=5779,Option='怎么做',}",
  [101989] = "{id=101989,Text='我可以帮你的忙，但你得先带些[c][ffff00]铠甲碎片[-][/c]来。',Speaker=5779,}",
  [101990] = "{id=101990,Text='这么快就带来了吗？',Speaker=5779,Option='{收集到了,5},{没有,4}',}",
  [101991] = "{id=101991,Text='没有[c][ffff00]铠甲碎片[-][/c]是没办法启动时空齿轮的',Speaker=5779,}",
  [101992] = "{id=101992,Text='看来你已经收集到足够的[c][ffff00]铠甲碎片[-][/c]了，你愿意把这些[c][ffff00]铠甲碎片[-][/c]交给我吗？',Speaker=5779,Option='{愿意,6},{不愿意,7}',}",
  [101993] = "{id=101993,Text='我想不明白你为什么不愿意给我。',Speaker=5779,}",
  [101994] = "{id=101994,Text='你还没有收集到足够的[c][ffff00]铠甲碎片[-][/c]。',Speaker=5779,}",
  [101995] = "{id=101995,Text='嗯，正是你所需要的！',Speaker=5779,}",
  [101996] = "{id=101996,Text='这些[c][ffff00]铠甲碎片[-][/c]能够合成一把小钥匙。',Speaker=5779,}",
  [101997] = "{id=101997,Text='好了，带着这把钥匙去钟楼一层开启时空齿轮吧！',Speaker=5779,}",
  [101998] = "{id=101998,Text='祝你好运！如果你见到了传说中的时空钟表，',Speaker=5779,}",
  [101999] = "{id=101999,Text='那一定要告诉我，让我也开开眼界！',Speaker=5779,}",
  [102000] = "{id=102000,Text='随着震耳的轰隆声，从钟楼的的地表转出一只巨大的时钟。',}",
  [102001] = "{id=102001,Text='这就是传说中的时空钟表啊！',Speaker=5772,}",
  [102002] = "{id=102002,Text='看呐，那钟表的表盘。',Speaker=5772,}",
  [102003] = "{id=102003,Text='我想这一定可以成功代替火花棱镜',Speaker=5772,}",
  [102004] = "{id=102004,Text='发生什么事！？',Speaker=5772,}",
  [102005] = "{id=102005,Text='什么！？是巴尔坦星人！',Speaker=5772,}",
  [102006] = "{id=102006,Text='这个国度怎么也会出现巴尔坦星人！',Speaker=5772,}",
  [102007] = "{id=102007,Text='嚯嚯嚯嚯嚯~~',Speaker=5774,}",
  [102008] = "{id=102008,Text='可恶，这时候没有火花棱镜，我什么都做不了！',Speaker=5772,Option='别自责',}",
  [102009] = "{id=102009,Text='我们快把时空钟表的表面卸下来吧！',Speaker=5772,}",
  [102010] = "{id=102010,Text='先离开这里！',Speaker=5772,}",
  [102011] = "{id=102011,Text='希望这次能够成功！',Speaker=5772,}",
  [102012] = "{id=102012,Text='拜托了，神光棒！',Speaker=5772,}",
  [102013] = "{id=102013,Text='圆大古身上再次发出了强烈的白光！',}",
  [102014] = "{id=102014,Text='又失败了…',Speaker=5780,Option='别灰心',}",
  [102015] = "{id=102015,Text='不过有一点我可以确定！',Speaker=5780,Option='什么',}",
  [102016] = "{id=102016,Text='巴尔坦星人会出现在这里，事情一定不简单！',Speaker=5780,Option='是嘛',}",
  [102017] = "{id=102017,Text='我在刚才的巴尔坦星人身上感知到了火花棱镜的力量！',Speaker=5780,Option='什么！',}",
  [102018] = "{id=102018,Text='你明天来见我，今天可得让我好好想想对策。',Speaker=5780,}",
  [102019] = "{id=102019,Text='[c][ffff00]储存服务[-][/c]是[c][ffff00]准它公司[-][/c]的兼职业务，为方便冒险家出行而推出的便捷服务，希望冒险者们会喜欢哦。',Speaker=5961,}",
  [102020] = "{id=102020,Text='储存后，[c][ffff00]只要使用蝴蝶翅膀，就可以回到这里[-][/c]，非常方便。不过，出门时请不要忘记携带[c][ffff00]蝴蝶翅膀[-][/c]哦~',Speaker=5961,Option='知道了！',}",
  [102021] = "{id=102021,Text='进行储存服务手续…好了，确认现在的储存位置，您可以安心进行冒险了！',Speaker=5961,}",
  [102022] = "{id=102022,Text='好了，储存已经顺利完成咯，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=5961,}",
  [102023] = "{id=102023,Text='[c][ffff00]储存服务[-][/c]是[c][ffff00]准它公司[-][/c]的兼职业务，为方便冒险家出行而推出的便捷服务，希望冒险者们会喜欢哦。',Speaker=5990,}",
  [102024] = "{id=102024,Text='储存后，[c][ffff00]只要使用蝴蝶翅膀，就可以回到这里[-][/c]，非常方便。不过，出门时请不要忘记携带[c][ffff00]蝴蝶翅膀[-][/c]哦~',Speaker=5990,}",
  [102025] = "{id=102025,Text='进行储存服务手续…好了，确认现在的储存位置，您可以安心进行冒险了！',Speaker=5990,}",
  [102026] = "{id=102026,Text='好了，储存已经顺利完成咯，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=5990,}",
  [102027] = "{id=102027,Text='这可怎么办，我的火花棱镜…',Speaker=5772,}",
  [102028] = "{id=102028,Text='全碎了。',Speaker=5772,}",
  [102029] = "{id=102029,Text='这下我再也没办法变身成迪迦奥特曼了…',Speaker=5772,Option='别放弃',Emoji=15,}",
  [102030] = "{id=102030,Text='嗯…',Speaker=5772,}",
  [102031] = "{id=102031,Text='你说的没错！或许还有希望。',Speaker=5772,Option='噢？',}",
  [102032] = "{id=102032,Text='我想，如果能像火花棱镜一样能折射光线并带有巨大能量，也许就能…',Speaker=5772,Option='{破坏棱镜,3},{代替棱镜,3},{丢弃棱镜,3},{修复棱镜,4}',}",
  [102033] = "{id=102033,Text='你是认真的吗…?',Speaker=5772,Emoji=14,}",
  [102034] = "{id=102034,Text='你们这个国度…',Speaker=5772,}",
  [102035] = "{id=102035,Text='有没有可以折射光线且带有强大能量的东西呀。',Speaker=5772,Option='{水晶？,5},{石块？,12}},{土豆？,12}},{铁块？,12}',}",
  [102036] = "{id=102036,Text='就是这个，请问哪里可能有这种水晶！',Speaker=5772,Option='{吉芬,7},{蚂蚁洞穴,6}},{斐扬,6}},{姜饼城,6}',}",
  [102037] = "{id=102037,Text='真的吗？听名字就不太像有水晶的地方啊…',Speaker=5772,Emoji=10,}",
  [102038] = "{id=102038,Text='好！这听起来像是个计划！',Speaker=5772,}",
  [102039] = "{id=102039,Text='你帮了我这么多，该怎么感谢你才好。',Speaker=5772,Option='不用',}",
  [102040] = "{id=102040,Text='今天不早了。',Speaker=5772,}",
  [102041] = "{id=102041,Text='不如明天我们就出发去吉芬！！',Speaker=5772,Option='没问题',}",
  [102042] = "{id=102042,Text='希望你能好好休息！',Speaker=5772,}",
  [102043] = "{id=102043,Text='也祝明天我能顺利的修好神光棒！',Speaker=5772,}",
  [102044] = "{id=102044,Text='明天见！[c][ffff00][PlayerName][-][/c]！',Speaker=5772,}",
  [102144] = "{id=102144,Text='就在那时！！',Speaker=5870,}",
  [102145] = "{id=102145,Text='一只比我高两倍的鸟人哈比向我扑了过来！',Speaker=5870,Emoji=7,}",
  [102146] = "{id=102146,Text='是是是…',Speaker=5868,}",
  [102147] = "{id=102147,Text='然后你反身一躲，它就磕在了岩石上。',Speaker=5868,}",
  [102148] = "{id=102148,Text='哈哈哈哈！！',Speaker=5870,}",
  [102149] = "{id=102149,Text='爸…',Speaker=5868,}",
  [102150] = "{id=102150,Text='这故事你都讲了多少遍了。',Speaker=5868,}",
  [102151] = "{id=102151,Text='那只是凑巧而已。',Speaker=5868,}",
  [102152] = "{id=102152,Text='哈哈哈，那你爸也有两下子不是吗？',Speaker=5870,}",
  [102153] = "{id=102153,Text='嗯……',Speaker=5868,}",
  [102154] = "{id=102154,Text='我的梦想，是当一个真正的英雄。',Speaker=5868,}",
  [102155] = "{id=102155,Text='等我长大了，我要加入朱诺守卫队！',Speaker=5868,}",
  [102156] = "{id=102156,Text='真是不错的梦想！',Speaker=5870,Emoji=20,}",
  [102157] = "{id=102157,Text='不愧是我儿子。',Speaker=5870,}",
  [102158] = "{id=102158,Text='什么呀。',Speaker=5868,}",
  [102159] = "{id=102159,Text='爸你明明就只是个普通的魔物研究员。',Speaker=5868,}",
  [102170] = "{id=102170,Text='我一人永不可及。',Speaker=5872,Option='什么意思',}",
  [102190] = "{id=102190,Text='书架上凌乱的摆着一些关于强化人体机能的书。',}",
  [102191] = "{id=102191,Text='桌面左手边有本翻开的笔记。',}",
  [102192] = "{id=102192,Text='上面写着几人...一体？...一人...不可…',}",
  [102193] = "{id=102193,Text='台上放着一本空白的羊皮纸书。',}",
  [102194] = "{id=102194,Text='小心！',Speaker=5874,}",
  [102195] = "{id=102195,Text='朱诺城内怎么会有这样的魔物！',Speaker=5874,}",
  [102196] = "{id=102196,Text='这本羊皮纸书一定有问题！',Speaker=5874,Option='是啊',}",
  [102197] = "{id=102197,Text='嗯…',Speaker=5874,}",
  [102198] = "{id=102198,Text='让我想想…',Speaker=5874,Option='怎么',}",
  [102199] = "{id=102199,Text='刚才父亲的谜题！',Speaker=5874,}",
  [102200] = "{id=102200,Text='你试试在上面写上“家人”两个字。',Speaker=5874,}",
  [102201] = "{id=102201,Text='一个木箱！？',Speaker=5874,}",
  [102202] = "{id=102202,Text='打开看看。',Speaker=5874,}",
  [102203] = "{id=102203,Text='嗯！？',Speaker=5874,}",
  [102204] = "{id=102204,Text='什么人！？',Speaker=5873,}",
  [102205] = "{id=102205,Text='我们被人发现了！',Speaker=5874,}",
  [102206] = "{id=102206,Text='先出去！',Speaker=5874,}",
  [102221] = "{id=102221,Text='钟楼的魔物非常强大，只有勇敢的冒险者才能击败这些狂暴的魔物，冒险者，一切小心。',Speaker=1016,}",
  [102222] = "{id=102222,Text='钟楼地下的气氛阴森恐怖，哪怕现在回想起来也会瑟瑟发抖，冒险者，请千万要注意安全。',Speaker=1016,}",
  [102223] = "{id=102223,Text='玩具工厂的魔物看上去非常可爱，而实际上它们已经开始狂暴了，冒险者，请务必要镇压它们。',Speaker=1016,}",
  [102224] = "{id=102224,Text='因为工业污染的缘故，艾因布洛克原野上的魔物比以往都要暴躁，陷入狂暴的它们更是拥有着巨大的力量。',Speaker=1016,}",
  [102225] = "{id=102225,Text='拥有着熔岩与火焰力量的魔物可不是那么好对付的，冒险者，请去镇压它们，保证人们的安全。',Speaker=1016,}",
  [102322] = "{id=102322,Text='我们该到处找找。',Speaker=5874,}",
  [102350] = "{id=102350,Text='美妙的歌声从前方的树林传出。',Option='聆听',}",
  [102351] = "{id=102351,Text='前往声音的源头看看吧。',}",
  [102352] = "{id=102352,Text='地上散落着奇怪的羽毛。',}",
  [102407] = "{id=102407,Text='我昨天辗转反侧一晚上，难以入眠！',Speaker=5772,Option='理解',}",
  [102408] = "{id=102408,Text='还有谁能偷取我的火花棱镜呢！',Speaker=5772,Option='{刺刀哥布灵,3},{钟怪,3},{巴尔坦星人,4},{波利,3}',}",
  [102409] = "{id=102409,Text='你和我想的有些偏差！',Speaker=5772,}",
  [102410] = "{id=102410,Text='你和我想的果然一样！',Speaker=5772,}",
  [102411] = "{id=102411,Text='十分懊悔让那可恶的巴尔坦星人逃跑了！',Speaker=5772,Option='安慰',}",
  [102412] = "{id=102412,Text='我明白朋友，现在不是懊悔的时候！',Speaker=5772,}",
  [102413] = "{id=102413,Text='我们得尽快找到替代棱镜的东西！',Speaker=5772,Option='是的！',}",
  [102414] = "{id=102414,Text='艾尔帕兰的卡普拉小姐姐们告诉我。',Speaker=5772,}",
  [102415] = "{id=102415,Text='克特森林附近，有一处远古遗迹！',Speaker=5772,Option='是嘛',}",
  [102416] = "{id=102416,Text='我第一次发现迪迦也是在一个古老的遗迹里！',Speaker=5772,}",
  [102417] = "{id=102417,Text='去那里看看一定会有收获的。',Speaker=5772,}",
  [102418] = "{id=102418,Text='我很确定！这附近有棱镜能量的存在。',Speaker=5772,}",
  [102419] = "{id=102419,Text='不如我们分头找找，看看这里有没有类似远古遗迹的石碑！',Speaker=5772,Option='好！',}",
  [102420] = "{id=102420,Text='一处犬妖森林特有的石雕像，似乎这不是什么遗迹。',}",
  [102421] = "{id=102421,Text='茂密的丛林深处似乎隐藏着些什么',}",
  [102422] = "{id=102422,Text='一座布满青苔的古老石碑，或许这就是圆大古所说的遗迹!',}",
  [102423] = "{id=102423,Text='这一定是遗迹石碑，准没错！',Speaker=5772,}",
  [102424] = "{id=102424,Text='碑面上模糊的刻着一行碑文。',Speaker=5787,}",
  [102425] = "{id=102425,Text='古老的河流封尘着能量，犬妖石像旁静待着。',Speaker=5787,}",
  [102426] = "{id=102426,Text='两座石盆，当水替代了火，秘密将会展现在你眼前。',Speaker=5787,}",
  [102427] = "{id=102427,Text='嗯…这行碑文究竟是什么意思！',Speaker=5772,}",
  [102428] = "{id=102428,Text='我想我明白了！',Speaker=5772,}",
  [102429] = "{id=102429,Text='答案就在刚才的犬妖石像旁！',Speaker=5772,}",
  [102430] = "{id=102430,Text='跟我来！',Speaker=5772,}",
  [102431] = "{id=102431,Text='这就是碑文上提到的两个火盆！',Speaker=5772,}",
  [102432] = "{id=102432,Text='我想我们只要用克特森林的湖水代替火，将水注入这个火盆内。',Speaker=5772,}",
  [102433] = "{id=102433,Text='那么秘密就会展现在我们眼前，对吗？',Speaker=5772,Option='是的！',}",
  [102434] = "{id=102434,Text='糟糕，前方的取水点被森林里的荆棘缠住了。',}",
  [102435] = "{id=102435,Text='荆棘被清理干净了',}",
  [102436] = "{id=102436,Text='希望这次能够成功！',Speaker=5772,}",
  [102437] = "{id=102437,Text='随着泉水的倒入，大地剧烈的震动起来。',}",
  [102438] = "{id=102438,Text='人类，说出你来的目的。',Speaker=5788,Option='说出来由',}",
  [102439] = "{id=102439,Text='想要得到棱镜的力量，就请回答我的问题吧！',Speaker=5788,}",
  [102440] = "{id=102440,Text='你将用这份力量做什么？',Speaker=5788,Option='{欺负小朋友,6},{偷东西,6},{什么都不做,6},{保护大家,7}',}",
  [102441] = "{id=102441,Text='你没有资格拥有棱镜！',Speaker=5788,Emoji=12,}",
  [102442] = "{id=102442,Text='好吧，我相信你们善良的内心！',Speaker=5788,Option='谢谢',}",
  [102443] = "{id=102443,Text='这片棱镜你们可以拿走，但我知道你们要找的并不是我这一片。',Speaker=5788,}",
  [102444] = "{id=102444,Text='什么！你知道我的火花棱镜在哪儿？',Speaker=5772,}",
  [102445] = "{id=102445,Text='是的，我看到有外星来的生物去了克雷斯特汉姆城的郊外。',Speaker=5788,}",
  [102446] = "{id=102446,Text='并且在他身上感受到了另一片棱镜的能量。',Speaker=5788,}",
  [102447] = "{id=102447,Text='一定是巴尔坦星人！',Speaker=5772,}",
  [102448] = "{id=102448,Text='我能告诉你们的只有这么多，希望对你们有帮助。',Speaker=5788,}",
  [102449] = "{id=102449,Text='再见。',Speaker=5788,}",
  [102450] = "{id=102450,Text='等等！！',Speaker=5772,}",
  [102451] = "{id=102451,Text='我还没有问完呢…',Speaker=5772,Emoji=18,}",
  [102452] = "{id=102452,Text='先不管这么多，我们先用这片棱镜试试看！',Speaker=5772,}",
  [102453] = "{id=102453,Text='拜托了，神光棒！',Speaker=5772,}",
  [102454] = "{id=102454,Text='圆大古身上再次发出了强烈的白光！',}",
  [102455] = "{id=102455,Text='这真是太令人尴尬了。',Speaker=5772,}",
  [102456] = "{id=102456,Text='看来犬妖棱镜的守护者说的没错。',Speaker=5772,}",
  [102457] = "{id=102457,Text='只有找到属于神光棒的那偏火花棱镜，我才能变回迪迦奥特曼！',Speaker=5772,Option='没错',}",
  [102458] = "{id=102458,Text='明天我们就出发去克雷斯特汉姆！',Speaker=5772,}",
  [102459] = "{id=102459,Text='[c][ffff00][PlayerName][-][/c]！你总算来了！',Speaker=5772,Option='这么着急',}",
  [102460] = "{id=102460,Text='事情似乎变得严峻了起来！',Speaker=5772,Option='怎么说',}",
  [102461] = "{id=102461,Text='今天我计划出发去克雷斯特汉姆。',Speaker=5772,}",
  [102462] = "{id=102462,Text='可附近的卡普拉姐姐告诉我，南门出大事了！',Speaker=5772,Option='什么事',}",
  [102463] = "{id=102463,Text='还记得我来的时候南门出现的时空裂隙吗？',Speaker=5772,Option='记得',}",
  [102464] = "{id=102464,Text='这个裂隙出现了奇怪的异动！',Speaker=5772,Option='什么！',}",
  [102465] = "{id=102465,Text='我必须现在立刻赶过去。',Speaker=5772,Option='等等',}",
  [102466] = "{id=102466,Text='我知道我还没有找到代替火花棱镜的东西。',Speaker=5772,}",
  [102467] = "{id=102467,Text='可现在也顾不了这么多了。',Speaker=5772,}",
  [102468] = "{id=102468,Text='大谷队员没了神光棒的力量十分危险！',}",
  [102469] = "{id=102469,Text='我们猜的没错，果然是巴尔坦星人搞得鬼！',Speaker=5772,}",
  [102470] = "{id=102470,Text='就是它破坏了我的神光棒！',Speaker=5772,}",
  [102471] = "{id=102471,Text='嚯嚯嚯~~你没了神光棒，什么都不是！！',Speaker=5774,Option='我帮你！！',}",
  [102472] = "{id=102472,Text='可恶的人类！！',Speaker=5790,}",
  [102473] = "{id=102473,Text='不过没用的。',Speaker=5790,}",
  [102474] = "{id=102474,Text='我用火花棱镜的力量。',Speaker=5790,}",
  [102475] = "{id=102475,Text='带来了你的老朋友，迪迦…',Speaker=5790,}",
  [102476] = "{id=102476,Text='嚯嚯嚯嚯',Speaker=5790,}",
  [102477] = "{id=102477,Text='随着巴尔坦星人的消失，最后一块火花棱镜的碎片从它身上掉了下来。',}",
  [102478] = "{id=102478,Text='这是！火花棱镜的最后一片碎片！',Speaker=5772,}",
  [102479] = "{id=102479,Text='我找这片碎片已经很久了！',Speaker=5772,}",
  [102480] = "{id=102480,Text='原来一直都在巴尔坦星人身上！',Speaker=5772,Option='是啊 ',}",
  [102481] = "{id=102481,Text='巴尔坦星人最后说，用棱镜的力量带来了我的老朋友！',Speaker=5772,Option='是的',}",
  [102482] = "{id=102482,Text='我有种不祥的预感，这和裂隙的异动有关系！',Speaker=5772,Option='是吗！',}",
  [102483] = "{id=102483,Text='我们必须抓紧时间，既然找回了最后的碎片。',Speaker=5772,}",
  [102484] = "{id=102484,Text='那就代表有希望修好它。',Speaker=5772,Option='对',}",
  [102485] = "{id=102485,Text='我听说，普隆德拉有位传说中的神工匠。',Speaker=5772,}",
  [102486] = "{id=102486,Text='那是谁！',Speaker=5772,Option='{雷藏,3},{忽克连,4},{卡普拉,3},{艾莉儿,3}',}",
  [102487] = "{id=102487,Text='好像不是这个名字',Speaker=5772,}",
  [102488] = "{id=102488,Text='就是他！也许他会有办法修好棱镜！',Speaker=5772,}",
  [102489] = "{id=102489,Text='冒险者！好久不见，是什么风把你吹来了。',Speaker=1014,Option='说明来由',}",
  [102490] = "{id=102490,Text='嗯…让我看看。',Speaker=1014,}",
  [102491] = "{id=102491,Text='嗯…',Speaker=1014,}",
  [102492] = "{id=102492,Text='这，很难，很难…',Speaker=1014,Emoji=14,}",
  [102493] = "{id=102493,Text='不过，也不是没有办法。',Speaker=1014,Option='真的吗',}",
  [102494] = "{id=102494,Text='是的，修复这枚火花棱镜需要两样东西！',Speaker=1014,}",
  [102495] = "{id=102495,Text='第一样，我需要一些[c][ffff00]钢铁[-][/c]材料。',Speaker=1014,}",
  [102496] = "{id=102496,Text='给我带一些来，我再告诉你第二样东西是什么。',Speaker=1014,}",
  [102497] = "{id=102497,Text='没想到你的腿脚还是一如既往的快！那么你带来了吗？',Speaker=1014,Option='{带来了,50},{没有,40}',}",
  [102498] = "{id=102498,Text='没有钢铁是没有办法帮你修复火花棱镜的',Speaker=1014,}",
  [102499] = "{id=102499,Text='看来你已经收集到足够的材料了，你愿意交给我吗？',Speaker=1014,Option='{愿意,70},{不愿意,60}',}",
  [102500] = "{id=102500,Text='难道你不想修复火花棱镜？',Speaker=1014,}",
  [102501] = "{id=102501,Text='你还没有准备足够的钢铁材料',Speaker=1014,}",
  [102502] = "{id=102502,Text='非常好，第一样东西齐全了。',Speaker=1014,}",
  [102503] = "{id=102503,Text='这第二样东西就是——',Speaker=1014,}",
  [102504] = "{id=102504,Text='光！',Speaker=1014,Option='什么？？',}",
  [102505] = "{id=102505,Text='你没有听错。',Speaker=1014,}",
  [102506] = "{id=102506,Text='去和城里的孩子们谈谈吧！',Speaker=1014,}",
  [102507] = "{id=102507,Text='你将得到他们最纯洁的爱和勇气！',Speaker=1014,Option='我没懂',}",
  [102508] = "{id=102508,Text='时间紧迫，快去吧！',Speaker=1014,}",
  [102509] = "{id=102509,Text='别磨磨蹭蹭的！',Speaker=1014,}",
  [102510] = "{id=102510,Text='爱和勇气？',Speaker=5791,}",
  [102511] = "{id=102511,Text='妈妈每天给我的苹果给了我想要当一名士兵的勇气！',Speaker=5791,}",
  [102512] = "{id=102512,Text='我愿意把今天拿到的苹果给你！',Speaker=5791,Emoji=17,}",
  [102513] = "{id=102513,Text='爱和勇气？',Speaker=5792,}",
  [102514] = "{id=102514,Text='妹妹把她最喜欢的熊偶送给了我，我感受到了妹妹的爱。',Speaker=5792,}",
  [102515] = "{id=102515,Text='但我愿意把这份爱传递给你！',Speaker=5792,Emoji=17,}",
  [102516] = "{id=102516,Text='哥哥每天都会给我扎个漂亮的蝴蝶结！',Speaker=5793,}",
  [102517] = "{id=102517,Text='我将来的梦想是当一个灵巧的理发师！哥哥给了我这份勇气！',Speaker=5793,}",
  [102518] = "{id=102518,Text='我愿意将这枚蝴蝶结给你！',Speaker=5793,Emoji=17,}",
  [102519] = "{id=102519,Text='没错，我要的就是这些！',Speaker=1014,}",
  [102520] = "{id=102520,Text='好了！给你。',Speaker=1014,}",
  [102521] = "{id=102521,Text='能不能成功，还要看使用者本人！',Speaker=1014,}",
  [102522] = "{id=102522,Text='唔…',Speaker=5791,Emoji=18,}",
  [102523] = "{id=102523,Text='南门出现了一只巨大怪兽！！！',Speaker=5791,}",
  [102524] = "{id=102524,Text='得赶快把棱镜交给圆大古才行。',}",
  [102525] = "{id=102525,Text='冒险者！！快把棱镜给我！！',Speaker=5772,}",
  [102526] = "{id=102526,Text='谢谢你为我找回了神光棒的力量！',Speaker=5900,}",
  [102527] = "{id=102527,Text='谢谢！',Speaker=5900,}",
  [102528] = "{id=102528,Text='再见！',Speaker=5900,}",
  [102529] = "{id=102529,Text='噢~天呐！',Speaker=5775,}",
  [102530] = "{id=102530,Text='原来这几天发生了这么多事。',Speaker=5775,Option='是的',}",
  [102531] = "{id=102531,Text='普隆德拉的人民将永远记住这位伴着光明来到的迪迦奥特曼！',Speaker=5775,}",
  [102532] = "{id=102532,Text='圆大古身上碰撞出激烈的光环！',}",
  [102533] = "{id=102533,Text='奥特曼加油！！',Speaker=5905,}",
  [102534] = "{id=102534,Text='奥特曼加油！！',Speaker=5796,}",
  [102535] = "{id=102535,Text='孩子们的爱与勇气汇成了无数道光！',}",
  [102536] = "{id=102536,Text='拜托了，神光棒！',Speaker=5799,}",
  [102537] = "{id=102537,Text='一切都结束了！',Speaker=5900,}",
  [102538] = "{id=102538,Text='没有发现棱镜的碎片',}",
  [102656] = "{id=102656,Text='邪恶向日葵都被赶跑了，被袭击的贤者似乎并没有受伤。',}",
  [102657] = "{id=102657,Text='谢谢你，幸好有你出手帮忙，不然我可就惨了。',Speaker=4687,}",
  [102658] = "{id=102658,Text='不过，你是？',Speaker=4687,Option='说明来意',}",
  [102659] = "{id=102659,Text='原来是杰拉德老师派你来的。',Speaker=4687,Emoji=9,}",
  [102660] = "{id=102660,Text='没想到他这么关心我们呀。',Speaker=4687,Option='对呀',}",
  [102661] = "{id=102661,Text='哎，是我太冲动了。',Speaker=4687,}",
  [102662] = "{id=102662,Text='一心只想着调查智慧巨人的线索。',Speaker=4687,}",
  [102663] = "{id=102663,Text='走着走着就入迷了……',Speaker=4687,}",
  [102664] = "{id=102664,Text='居然顺着魔力闯进了邪恶向日葵的巢穴。',Speaker=4687,Emoji=24,}",
  [102665] = "{id=102665,Text='对了，你刚才是不是在附近看到过一张残破的书卷？',Speaker=4687,Option='是的',}",
  [102666] = "{id=102666,Text='那其实是我刚才发现的智慧残卷，被魔物追的时候掉在附近了。',Speaker=4687,Option='智慧残卷？',}",
  [102667] = "{id=102667,Text='智慧残卷原本是智慧卷轴的一部分。',Speaker=4687,}",
  [102668] = "{id=102668,Text='智慧巨人密米尔将毕生所钻研的知识都撰写在了卷轴里。',Speaker=4687,Option='这么厉害?',}",
  [102669] = "{id=102669,Text='据说一千年前诸神黄昏之战，智慧巨人密米尔为了不让敌人得到智慧卷轴，才将它破坏成了几十份智慧残卷。',Speaker=4687,}",
  [102670] = "{id=102670,Text='还好是你捡到了，谢谢你。',Speaker=4687,Option='不用谢',}",
  [102671] = "{id=102671,Text='要是被魔物抢走了，我可就要哭了。',Speaker=4687,}",
  [102672] = "{id=102672,Text='这里真是太危险了，智慧残卷还是放在你身上安全。',Speaker=4687,}",
  [102673] = "{id=102673,Text='那我就先回老师那儿去了。',Speaker=4687,}",
  [102674] = "{id=102674,Text='你记得待会儿去老师那里找我噢。',Speaker=4687,}",
  [102754] = "{id=102754,Text='杰拉德和四位学生按顺序开始了仪式的咏唱。',}",
  [102755] = "{id=102755,Text='伟大的智慧巨人密米尔啊……',Speaker=4055,}",
  [102756] = "{id=102756,Text='我们以人类虔诚的求知欲向您请求……',Speaker=4056,}",
  [102757] = "{id=102757,Text='如果您在遥远的另一头听见了呼唤……',Speaker=4057,}",
  [102758] = "{id=102758,Text='哪怕传授我们知识的冰山一角……',Speaker=4058,}",
  [102759] = "{id=102759,Text='……',Speaker=4059,Emoji=14,}",
  [102760] = "{id=102760,Text='格拉，你在等什么，就差你的最后一句咏唱了！',Speaker=4055,Emoji=7,}",
  [102761] = "{id=102761,Text='是啊，格拉，快说话啊，为什么阴沉着脸？',Speaker=4056,}",
  [102762] = "{id=102762,Text='哈哈哈哈哈……愚蠢的人啊。',Speaker=4059,Emoji=5,}",
  [102763] = "{id=102763,Text='你们真的以为我是你们的同类么？',Speaker=4059,}",
  [102764] = "{id=102764,Text='这具身体原本的精神早就被我以伪神的力量侵蚀了！',Speaker=4059,}",
  [102765] = "{id=102765,Text='最后一句咏唱，听好吧……',Speaker=4059,}",
  [102766] = "{id=102766,Text='我以恶魔的名义向异界征召，回归吧，属于我原本的魔力！',Speaker=4059,}",
  [102767] = "{id=102767,Text='哈哈哈，我终于拿回了自己的魔力。',Speaker=4060,}",
  [102768] = "{id=102768,Text='还顺便偷了一具年轻的肉体。',Speaker=4060,Emoji=5,}",
  [102769] = "{id=102769,Text='你……究竟是什么时候侵占了格拉的身体和精神的？！',Speaker=4055,}",
  [102770] = "{id=102770,Text='哼，他第一次被智慧井拉入异世界的地方，就是囚禁我的牢笼。',Speaker=4060,}",
  [102771] = "{id=102771,Text='原本我以为要被他消灭了，可惜这个人类实在太弱了，竟然连失去大部分魔力的我都无法抵抗。',Speaker=4060,}",
  [102772] = "{id=102772,Text='早在那个时候我就顺势侵占了他的精神了。',Speaker=4060,}",
  [102773] = "{id=102773,Text='现在，这场召唤仪式的魔力通道变成了我取回伪神魔力的通道。',Speaker=4060,}",
  [102774] = "{id=102774,Text='人类！为我的重生而献祭吧！',Speaker=4060,}",
  [102775] = "{id=102775,Text='混账！你休想侵占我学生的身体来实施恶行！',Speaker=4055,}",
  [102776] = "{id=102776,Text='冒险者，快！',Speaker=4055,}",
  [102777] = "{id=102777,Text='伪神融合精神需要时间，他现在还没完全和格拉合为一体。',Speaker=4055,}",
  [102778] = "{id=102778,Text='只要现在打败他，就能救回格拉！',Speaker=4055,Option='知道了！',}",
  [102779] = "{id=102779,Text='随着你的最后一击，伪神的魔力逐渐消散了。',}",
  [102780] = "{id=102780,Text='格拉，格拉，你快醒醒！',Speaker=4055,Emoji=18,}",
  [102781] = "{id=102781,Text='呜呜呜，格拉你别死啊！',Speaker=4056,}",
  [102782] = "{id=102782,Text='坚持住啊，格拉！',Speaker=4057,}",
  [102783] = "{id=102783,Text='格拉，我们相信你啊！',Speaker=4058,}",
  [102784] = "{id=102784,Text='……格拉渐渐有了呼吸。',}",
  [102785] = "{id=102785,Text='我……这是怎么了？我只记得我被吸进智慧井，然后……',Speaker=4059,}",
  [102786] = "{id=102786,Text='别说了格拉，是我没有保护好你，是我没有保护好你们。',Speaker=4055,}",
  [102787] = "{id=102787,Text='你能回来就好，回来就好。',Speaker=4055,Emoji=24,}",
  [102788] = "{id=102788,Text='冒险者，这次真的是多亏有你在，才没有酿成大祸。',Speaker=4055,}",
  [102789] = "{id=102789,Text='我以贤者学院的名义向你表示最真诚的感谢！',Speaker=4055,}",
  [102790] = "{id=102790,Text='作为谢礼，我希望将密米尔号角送给你。',Speaker=4055,Option='什么？',}",
  [102791] = "{id=102791,Text='密米尔号角经过这次召唤，已经耗尽了大部分魔力了，留在我身边也只是个摆设。',Speaker=4055,}",
  [102792] = "{id=102792,Text='我想你可以带着它继续冒险，让号角在更遥远的地方，找回原有的魔力。',Speaker=4055,}",
  [102793] = "{id=102793,Text='希望密米尔号角能被你再次吹响，响彻整个大陆的天空！',Speaker=4055,}",
  [102818] = "{id=102818,Text='你们终究还是来了呀~',Speaker=5881,}",
  [102819] = "{id=102819,Text='很有勇气。',Speaker=5881,Option='什么意思',}",
  [102820] = "{id=102820,Text='我当然是~嘿嘿',Speaker=5881,}",
  [102821] = "{id=102821,Text='热烈欢迎咯~',Speaker=5881,}",
  [102822] = "{id=102822,Text='少来！',Speaker=5882,}",
  [102823] = "{id=102823,Text='好了，我们说正事。',Speaker=5881,}",
  [102824] = "{id=102824,Text='这的确，是塞壬父亲以前办公室的旧址。',Speaker=5881,}",
  [102825] = "{id=102825,Text='什么！！',Speaker=5882,Emoji=7,}",
  [102826] = "{id=102826,Text='这房间里所有的一切。',Speaker=5881,}",
  [102827] = "{id=102827,Text='都属于你父亲。',Speaker=5881,}",
  [102828] = "{id=102828,Text='现在属于你了。',Speaker=5881,}",
  [102829] = "{id=102829,Text='塞壬一脸怀疑和惊讶的看着眼前有些疯疯癫癫的研究员。',}",
  [102830] = "{id=102830,Text='是时候让你们知道真相了。',Speaker=5881,}",
  [102831] = "{id=102831,Text='去打开那只木箱吧。',Speaker=5881,}",
  [102832] = "{id=102832,Text='封尘的木箱被缓缓打开，阳光照在箱子上扬起一层薄薄的灰尘。',}",
  [102833] = "{id=102833,Text='箱子里躺着一把精致的小匕首，看的出有些岁月，但依然十分锋利。',}",
  [102834] = "{id=102834,Text='接过匕首的塞壬眼角抽搐了一下。',}",
  [102835] = "{id=102835,Text='这是我父亲的匕首，上面刻着他的名字…',Speaker=5882,Emoji=14,}",
  [102836] = "{id=102836,Text='你们把我父亲怎么样了！！！',Speaker=5882,}",
  [102837] = "{id=102837,Text='你们不要冲动。',Speaker=5881,}",
  [102838] = "{id=102838,Text='我不想伤害你们，只想告诉你真相，塞壬。',Speaker=5881,}",
  [102839] = "{id=102839,Text='是什么！！',Speaker=5882,}",
  [102840] = "{id=102840,Text='你父亲当年为我工作，我们一起参与了索斯计划。',Speaker=5881,Option='索斯计划？',}",
  [102841] = "{id=102841,Text='这是你父亲的研究，他发明了让人体变强壮的基因药剂。',Speaker=5881,}",
  [102842] = "{id=102842,Text='我们实验的第一个对象就是索斯。',Speaker=5881,Option='然后呢',}",
  [102843] = "{id=102843,Text='可惜索斯是个失败品，他没有控制自己思维的能力。',Speaker=5881,}",
  [102844] = "{id=102844,Text='你父亲他…',Speaker=5881,}",
  [102845] = "{id=102845,Text='什么！！',Speaker=5882,}",
  [102846] = "{id=102846,Text='惨死在失控的索斯手下…',Speaker=5881,}",
  [102847] = "{id=102847,Text='塞壬，你父亲很爱你。',Speaker=5881,}",
  [102848] = "{id=102848,Text='他奄奄一息的对我说，让我把这只匕首交给你。',Speaker=5881,}",
  [102849] = "{id=102849,Text='你一定要为他…',Speaker=5881,}",
  [102850] = "{id=102850,Text='报仇！',Speaker=5881,}",
  [102851] = "{id=102851,Text='不可能！',Speaker=5882,Emoji=7,}",
  [102852] = "{id=102852,Text='我父亲还活着！！！',Speaker=5882,}",
  [102853] = "{id=102853,Text='我不相信！！！！！',Speaker=5882,}",
  [102854] = "{id=102854,Text='这不是真的！！！！！！！！',Speaker=5882,}",
  [102855] = "{id=102855,Text='塞壬，你冷静一点！',Speaker=5883,}",
  [102856] = "{id=102856,Text='不！！！！',Speaker=5882,}",
  [102857] = "{id=102857,Text='塞壬根本不顾赛尼亚的劝阻，悲愤的冲出了宝伏的办公室。',Emoji=18,}",
  [102890] = "{id=102890,Text='不许你们伤害索斯！！',Speaker=5878,Emoji=12,}",
  [102891] = "{id=102891,Text='叽叽喳喳的吵死了。',Speaker=5882,}",
  [102892] = "{id=102892,Text='！！！',Speaker=5878,Emoji=12,}",
  [102893] = "{id=102893,Text='这道栏杆似乎放不下来！',}",
  [102894] = "{id=102894,Text='我见过这种机关！这是熔洞牢栏。',Speaker=5882,}",
  [102895] = "{id=102895,Text='是那些可恶的熔岩恶魔铸出来的!',Speaker=5882,}",
  [102896] = "{id=102896,Text='我们得把路上的熔岩恶魔全都清理掉！',Speaker=5882,}",
  [102897] = "{id=102897,Text='现在应该能降下牢栏了！',Speaker=5882,}",
  [102898] = "{id=102898,Text='你们小心！是熔洞领主的火焰尊魔！',Speaker=5883,}",
  [102899] = "{id=102899,Text='能遇到它，看来今天我们的运气真的有些差。',Speaker=5883,}",
  [102900] = "{id=102900,Text='火焰挡住了通往前方的路！',Speaker=5882,}",
  [102901] = "{id=102901,Text='攻击尊魔本身是无效的！',Speaker=5882,}",
  [102902] = "{id=102902,Text='把它身上分出来的火焰全部消灭才能消灭它！',Speaker=5882,}",
  [102903] = "{id=102903,Text='快看！挡住我们的火焰墙消失了！',Speaker=5882,}",
  [102904] = "{id=102904,Text='随着轰隆声，火焰墙熄灭了…',}",
  [102905] = "{id=102905,Text='仿佛是里面的魔物已放弃了抵抗。',}",
  [102906] = "{id=102906,Text='住手！',Speaker=5882,}",
  [102907] = "{id=102907,Text='把它交给我，这件事必须我自己来完成。',Speaker=5882,}",
  [102908] = "{id=102908,Text='塞壬掏出了父亲给他留下的匕首。',}",
  [102909] = "{id=102909,Text='魔物！！为什么不反击！！！',Speaker=5882,}",
  [102910] = "{id=102910,Text='反击啊！！！',Speaker=5882,}",
  [102911] = "{id=102911,Text='塞壬…',Speaker=5883,}",
  [102912] = "{id=102912,Text='杀了它，你的父亲也不会回来了。',Speaker=5883,}",
  [102913] = "{id=102913,Text='放过它吧...也放过你自己…',Speaker=5883,}",
  [102914] = "{id=102914,Text='…',Speaker=5882,Emoji=18,}",
  [359001] = "{id=359001,Text='有亮光！感觉控制不住寄己了！',Speaker=20050,}",
  [359002] = "{id=359002,Text='你真的……看不到……我吗？',Speaker=20051,}",
  [359003] = "{id=359003,Text='别动我的小饼干！噗噜噜噜……',Speaker=30064,}",
  [359004] = "{id=359004,Text='幻想乡四大天王、闪亮登场！',Speaker=30065,}",
  [359005] = "{id=359005,Text='黑暗——会将这世界吞噬！',Speaker=204200,}",
  [359006] = "{id=359006,Text='准备好，承受兽人的怒火吧！',Speaker=204210,}",
  [359007] = "{id=359007,Text='这里是……哪个维度的世界？',Speaker=30067,}",
  [359008] = "{id=359008,Text='我的眼睛，洞察一切！',Speaker=20052,}",
  [359009] = "{id=359009,Text='谁允许你踏入这片区域？',Speaker=204220,}",
  [359010] = "{id=359010,Text='吼……把宝物，放下！',Speaker=20053,}",
  [359011] = "{id=359011,Text='奉族长之名，奉旧良族之名，驱逐入侵者！',Speaker=30068,}",
  [360001] = "{id=360001,Text='呼噜……知道……呼噜呼噜……',Speaker=501310,}",
  [360002] = "{id=360002,Text='呼噜……上路啦……',Speaker=501310,}",
  [360003] = "{id=360003,Text='还能……再重一点哦……',Speaker=501310,}",
  [360005] = "{id=360005,Text='好多人……是商集吗……',Speaker=501310,}",
  [360009] = "{id=360009,Text='能走更远了……',Speaker=501310,}",
  [360010] = "{id=360010,Text='咱……不能陪了……呼……',Speaker=501310,}",
  [360011] = "{id=360011,Text='咱也……有尾巴的……',Speaker=501310,}",
  [360012] = "{id=360012,Text='呼噜……不够……饿……',Speaker=501310,}",
  [360013] = "{id=360013,Text='多一点……也没问题……虽然饱了……',Speaker=501310,}",
  [360014] = "{id=360014,Text='咱……哪儿都能陪你去……',Speaker=501310,}",
  [360015] = "{id=360015,Text='呼噜呼噜……给咱让开道……',Speaker=501310,}",
  [360016] = "{id=360016,Text='你们……太小了……',Speaker=501310,}",
  [360018] = "{id=360018,Text='你聊……咱睡……呼噜呼噜……',Speaker=501310,}",
  [360019] = "{id=360019,Text='你……好像大了一点儿……',Speaker=501310,}",
  [360021] = "{id=360021,Text='背上……痒痒……给咱摸摸……',Speaker=501310,}",
  [360022] = "{id=360022,Text='上来……快点儿……',Speaker=501310,}",
  [360023] = "{id=360023,Text='呼噜呼噜……舒服……',Speaker=501310,}",
  [360025] = "{id=360025,Text='虱子……身上虱子……快……',Speaker=501310,}",
  [360026] = "{id=360026,Text='胃里……没货了……呼噜。',Speaker=501310,}",
  [360027] = "{id=360027,Text='咱的头……可以戴吗……小了吗？……',Speaker=501310,}",
  [360101] = "{id=360101,Text='有名字是件好事！撒钱庆祝一下！',Speaker=501340,}",
  [360102] = "{id=360102,Text='咕唧！我屯了很多很多的钱了！',Speaker=501340,}",
  [360103] = "{id=360103,Text='缺钱的时候可以问我借哦！什么，本来就是主人的？',Speaker=501340,}",
  [360105] = "{id=360105,Text='是总社！',Speaker=501340,}",
  [360109] = "{id=360109,Text='阶段经营目标达成，主人！',Speaker=501340,}",
  [360110] = "{id=360110,Text='完了，破产了……主人……',Speaker=501340,}",
  [360111] = "{id=360111,Text='喂、喂！不要扯！',Speaker=501340,}",
  [360112] = "{id=360112,Text='这笔投资真及时！',Speaker=501340,}",
  [360113] = "{id=360113,Text='预算充分，不用追加！',Speaker=501340,}",
  [360114] = "{id=360114,Text='主人，工作时间到！',Speaker=501340,}",
  [360115] = "{id=360115,Text='我可要开张营业啦！',Speaker=501340,}",
  [360116] = "{id=360116,Text='薄利多销、薄利多销哟！',Speaker=501340,}",
  [360118] = "{id=360118,Text='本日流水多少？利润率下降了吗？成本——啊，主人别跑啊！',Speaker=501340,}",
  [360119] = "{id=360119,Text='主人的事业又做大了，可喜可贺！',Speaker=501340,}",
  [360121] = "{id=360121,Text='主人，现在摸摸可以打对折……开玩笑啦，免费的！',Speaker=501340,}",
  [360122] = "{id=360122,Text='风险过大啦，快规避呀！',Speaker=501340,}",
  [360123] = "{id=360123,Text='赚到啦赚到啦！',Speaker=501340,}",
  [360125] = "{id=360125,Text='唔、唔……主人，可以摸摸尾巴吗……是尾巴不是钱袋子！',Speaker=501340,}",
  [360126] = "{id=360126,Text='资金流要断了！主人，再投资一点！',Speaker=501340,}",
  [360127] = "{id=360127,Text='好看的招牌是赚钱的资本！',Speaker=501340,}",
  [361009] = "{id=361009,Text='欢迎来到王立克里图拉学院，愿你在这里度过美好的校园生活。',Speaker=821004,}",
  [361010] = "{id=361010,Text='星泪森林拥有美丽的湖光山色，相传林地中央的巨大湖泊是由流星坠落而形成，整片森林也因此得名。',Speaker=821018,}",
  [361018] = "{id=361018,Text='刘海不过眉，也可以剪出漂亮的发型哟~',Speaker=821010,}",
  [361025] = "{id=361025,Text='咕噜咕噜~不想跟你说话。',Speaker=501430,}",
  [361035] = "{id=361035,Text='也不是特别想跟你说话。',Speaker=501440,}",
  [361706] = "{id=361706,Text='远方的风路过此地，将流逝的时光吹拂成漫漫旷野。',Speaker=821020,}",
  [361801] = "{id=361801,Text='回去睡个养颜觉，皮肤才能更Q弹卟~',Speaker=501580,}",
  [361802] = "{id=361802,Text='又变强了卟！',Speaker=501580,}",
  [361803] = "{id=361803,Text='不要灰心卟~~',Speaker=501580,}",
  [361804] = "{id=361804,Text='不要吃我，吃这个吧~',Speaker=501580,}",
  [361805] = "{id=361805,Text='唔~你很强大呢！',Speaker=501580,}",
  [361806] = "{id=361806,Text='要被吃掉了卟QAQ',Speaker=501580,}",
  [361807] = "{id=361807,Text='我不是食物卟，虽然对味道还是挺有自信的……',Speaker=501580,}",
  [361808] = "{id=361808,Text='谢谢你卟~',Speaker=501580,}",
  [361809] = "{id=361809,Text='你这样是抓不到我的卟！',Speaker=501580,}",
  [361810] = "{id=361810,Text='逃走了卟~',Speaker=501580,}",
  [361811] = "{id=361811,Text='不能屈服卟……好舒服……',Speaker=501580,}"
}
Table_Dialog_Left_13.count = 2001
